(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Ladenbesitzer! Appa ist jetzt ausgeruht!"},{"a":"atlab_aang","t":"Also ... Dann heißt es jetzt wohl Abschiednehmen ..."},{"a":"atlab_sokka","t":"Hey, Kopf hoch! Wir können jederzeit wiederkommen!"},{"a":"atlab_aang","t":"Du hast recht! Kannst du dich an den Weg erinnern, Sokka?"},{"a":"atlab_sokka","t":"Äh ... Ich habe nicht aufgepasst ..."},{"a":"atlab_sokka","t":"E-Egal! Wir müssen uns jetzt um superwichtige Avatar-Angelegenheiten kümmern!"},{"a":"atlab_sokka","t":"Komm, Momo! Wir gehen!"},{"a":"atlab_aang","t":"Momo! ... Momo?"},{"a":"atlab_aang","t":"Dir gefällt es hier, was? Also gut, schön."},{"a":"atlab_aang","t":"Ladenbesitzer, würde es dir etwas ausmachen, Momo eine Weile im Auge zu behalten?"},{"a":"atlab_aang","t":"Ich hole dich später wieder ab, Momo. Versprochen!"},{"a":"atlab_aang","t":"Gehen wir, Sokka. Danke für alles, Ladenbesitzer!"},{"a":"atlab_sokka","t":"Tschüss!"},{"a":"atlab_aang","t":"Komm schon, Appa! Yip-Yip!"}]},{"id":"atlab_aang_01","i":1,"title":"Schicksalhafter Irrweg","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"inn","t":"Tut mir leid, Kleiner, das hab ich nicht ganz kapiert. Könntest du die Geschichte noch mal wiederholen?"},{"a":"atlab_aang","t":"Verzeihung. Ich beginne noch mal von vorn!"},{"a":"atlab_aang","t":"Ich bin Aang, der Avatar."},{"a":"atlab_aang","t":"Ich bin mit meinen Freunden auf meinem Himmelsbison gereist ..."},{"a":"atlab_aang","t":"Beim Fliegen müssen wir falsch abgebogen sein, denn wir sind hier gelandet!"},{"a":"inn","t":"Der Riesenochse da draußen? Das Ding kann fliegen?"},{"a":"atlab_aang","t":"Ja! Sein Name ist Appa. Er ist sehr freundlich!"},{"a":"inn","t":"Sieht auch ziemlich erschöpft aus. Ihr werdet von jemandem verfolgt, stimmt’s?"},{"a":"atlab_aang","t":"Oh, ähm ..."},{"a":"inn","t":"Hey, mach dir keine Sorgen. Unter meinem Dach kommt niemand zu Schaden. Oscar-Ehrenwort."},{"a":"inn","t":"Ich sag euch was: Wie würde es euch gefallen, hier gratis unterzukommen?"},{"a":"atlab_aang","t":"Gratis? Wirklich?!"},{"a":"inn","t":"Also erst mal sieht es nicht so aus, als wäre euer seltsames Geld hier viel wert."},{"a":"inn","t":"Und ich kann ja keine Kinder draußen auf der Straße schlafen lassen, oder?"},{"a":"atlab_aang","t":"D-Danke, Herr Oscar!"},{"a":"inn","t":"Ihr seht recht tüchtig aus. Wie wäre es, wenn ihr dafür meinem Ladenbesitzer-Kumpel helft?"},{"a":"atlab_aang","t":"Geht klar! Vielen Dank!"}]},{"id":"atlab_aang_02","i":2,"title":"Feuerbändigen?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"inn","t":"Hey Lilu! Das ist mein neuer Freund!"},{"a":"lilu","t":"Hallo. Solche Tattoos habe ich noch nie gesehen ..."},{"a":"atlab_aang","t":"Ich bin Aang! Und ich habe noch nie einen solchen Hut gesehen!"},{"a":"inn","t":"Komm schon, Aang, zeig ihr deinen Trick!"},{"a":"atlab_aang","t":"Du meinst ... den?"},{"a":"lilu","t":"W-Wie hast du das gemacht? Ich hab keine Magie gespürt!"},{"a":"atlab_aang","t":"Luftbändigen! Ich kann auch Erde und Wasser bändigen!"},{"a":"lilu","t":"Unglaublich! Warte mal, ich will mir das notieren ..."},{"a":"lilu","t":"Könnte das Chi sein? Ich habe das noch nie jemanden tun sehen ..."},{"a":"atlab_aang","t":"Das stimmt! Aber nicht jeder kann es. Man muss mit der Fähigkeit geboren werden und dann lernen, sie zu beherrschen!"},{"a":"lilu","t":"Du hast gesagt, du kannst Luft, Erde und Wasser bändigen ... Wie sieht es mit Feuer aus?"},{"a":"atlab_aang","t":"Ah ... Ich ... Das Feuerbändigen beherrsche ich noch nicht ..."},{"a":"atlab_aang","t":"... Ich hatte Schwierigkeiten, einen Feuerbändigungsmeister zu finden, der mich lehren kann."},{"a":"lilu","t":"Ist das so? Also ich kenne mich ein wenig mit Feuermagie aus!"},{"a":"lilu","t":"Es ist nicht ganz dasselbe, aber vielleicht möchtest du sehen, wie es funktioniert?!"},{"a":"atlab_aang","t":"Ah ... klar. Danke, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"Der letzte Luftbändiger","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"elderowen","t":"Aang, mein Junge. Wie gefällt dir das Stadtleben?"},{"a":"atlab_aang","t":"Ältester Owen! Es ist super! Danke für deine Gastfreundschaft."},{"a":"elderowen","t":"Das ist doch selbstverständlich. Aber verrate mir, Junge, wo sind deine Eltern?"},{"a":"atlab_aang","t":"Ah ... Ich habe ... keine Eltern mehr."},{"a":"atlab_aang","t":"Meine Familie ... Alle Luftnomaden wurden von der Feuernation getötet."},{"a":"atlab_aang","t":"... Ich bin als Einziger übrig."},{"a":"elderowen","t":"Du meine Güte! Mein Beileid, armes Kind ..."},{"a":"elderowen","t":"... Wenn du nirgendwohin zurückkannst, wie wäre es, wenn du mit deinen Freunden hierbleibst?"},{"a":"elderowen","t":"Die Stadt würde sich sicherlich freuen, wenn ihr bleibt. Ihr seid jetzt schon sehr beliebt!"},{"a":"atlab_aang","t":"Danke für das großzügige Angebot, Ältester. Aber ich kann es nicht annehmen."},{"a":"atlab_aang","t":"In diesem Augenblick plant Feuerlord Ozai bereits seinen nächsten Zug."},{"a":"atlab_aang","t":"Wenn Zosins Komet den Himmel wieder erhellt, wird die Feuernation meine Welt erobern ..."},{"a":"atlab_aang","t":"... Das Erdkönigreich ... Die Wasserstämme ... Sie werden dasselbe Schicksal wie die Luftnomaden erleiden."},{"a":"atlab_aang","t":"Als der Avatar bin ich der Einzige, der ihn aufhalten kann! Aber ich bin noch nicht bereit."},{"a":"elderowen","t":"Was für eine schreckliche Bürde für ein Kind ..."},{"a":"elderowen","t":"Egal, was kommt, denk daran, dass du die volle Unterstützung unserer Stadt hast."},{"a":"atlab_aang","t":"Danke, Ältester. Ihr alle habt schon so viel für uns getan!"},{"a":"atlab_aang","t":"Wir werden euch auf jeden Fall besuchen kommen, wenn all das vorbei ist!"}]},{"id":"atlab_aang_04","i":4,"title":"Zosins Omen","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"mana","t":"Avatar. Endlich begegnen wir uns."},{"a":"atlab_aang","t":"Wer bist du? Woher kennst du mich?"},{"a":"mana","t":"Die Anwesenheit des Avatars erstrahlt wie ein Leuchtfeuer für das Dritte Auge."},{"a":"atlab_aang","t":"Oh, Wahrsagerei ... Da muss ich passen!"},{"a":"mana","t":"Du, der du viele bist und doch nicht ganz ..."},{"a":"mana","t":"Ein heftiger Kampf gegen den Lord des Feuers steht bevor ..."},{"a":"atlab_aang","t":"Feuerlord Ozai ... Du weißt von ihm?"},{"a":"mana","t":"Unter dem Blick des Kometen wird das Land zerrissen und die Felder werden niedergebrannt!"},{"a":"atlab_aang","t":"Das weiß ich! Aber was kann ich tun?"},{"a":"mana","t":"Der Lauf des Schicksals kann nicht zerstört werden."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"... Aber die Tapferen können die Fäden ziehen und ihn umleiten."},{"a":"mana","t":"Ein seltsamer Verbündeter und eine zerbrechliche Allianz könnten der Schlüssel sein."},{"a":"atlab_aang","t":"Danke, Wahrsagerin ... Ich werde darüber nachdenken."},{"a":"mana","t":"..."},{"a":"mana","t":"Sei tapfer, Avatar. Bleib dir treu, dann wirst du siegen."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"Der Schatten des Königs","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"... und dann habe ich den Nervtöter-Kobold mit meinem Schwert niedergestreckt! Zack!"},{"a":"elderowen","t":"Hoho! Eine fantastische Geschichte, Argon!"},{"a":"elderowen","t":"Ah, das Feuer der Jugend ..."},{"a":"elderowen","t":"Ich muss schon sagen, es ist nett, dass du einen alten Mann wie mich auf seinem Morgenspaziergang begleitest."},{"a":"argon","t":"Nicht der Rede wert! Wenn ich eines Tages Ritter werden will, muss ich Menschen in Not helfen!"},{"a":"elderowen","t":"Genau wie dein Vater, was? Du wirst sicher einmal ein edler Ritter, mein Junge."},{"a":"elderowen","t":"Oh, vielleicht könntest du sogar in der Königswache dienen!"},{"a":"elderowen","t":"Wenn man vom Teufel spricht, er ist gerade auf dem Markt! Warum fragst du ihn nicht einfach?"},{"a":"argon","t":"EURE MAJESTÄT! Ich möchte Euch meine Dienste als Ritter anbieten!"},{"a":"king","t":"W-Was hat das zu bedeuten?! Sia, bitte kümmere dich um diesen gemeinen Bürger."},{"a":"sia","t":"Natürlich, mein König."},{"a":"sia","t":"Na, junger Mann? Was gibt es denn?"},{"a":"argon","t":"Wow! Ich, äh ..."},{"a":"argon","t":"Ich bin Ritter! Ich möchte ein Argon werden!"},{"a":"argon","t":"Nee, Moment mal ..."},{"a":"sia","t":"Du hast wirklich Mut!"},{"a":"sia","t":"Wenn du wirklich so zielstrebig bist, dann triff mich nächste Woche im Schlosshof."},{"a":"sia","t":"Trainiere bis dahin hart! Ein Faulenzer hat bei den Rittern des Königs nicht zu suchen ..."}]},{"id":"argon_02","i":2,"title":"Training-Montage","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Argon, was machst du denn hier draußen?"},{"a":"argon","t":"Ich trainiere hart! Endlich habe ich eine Chance, ein Ritter für den König zu werden!"},{"a":"lilu","t":"Für den König? Oder für seine geheimnisvolle Ratgeberin Sia?"},{"a":"argon","t":"Ist das ihr Name? Sie ist auch echt hübsch!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Gah! Nein! Nur der König hat Bedeutung!"},{"a":"argon","t":"Ich muss ein Ritter werden! Alles andere ist nebensächlich!"},{"a":"lilu","t":"Gut ... Lass mich deine Wunden heilen."},{"a":"argon","t":"Dankesch... autsch! Der Zauberspruch piekt!"}]},{"id":"argon_03","i":3,"title":"Zwei Seiten einer Medaille","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Also gut, Sia wird jeden Moment auftauchen!"},{"a":"argon","t":"Meine Ausbildung hat sich gelohnt, ich bin bereit!"},{"a":"argon","t":"... Aber ich bin immer noch viel zu nervös ..."},{"a":"argon","t":"Oh! He da! Du, im Gebüsch!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Bist du auch hier, um ein Ritter zu werden?"},{"a":"argon","t":"Sia wird gleich hier sein! Kein Grund, sich zu verstecken. Sie ist echt nett!"},{"a":"yami","t":"Sia ...!"},{"a":"yami","t":"Ich muss los. Leb wohl."},{"a":"argon","t":"W-warte!"},{"a":"argon","t":"Wow! Rauchbombe?!"},{"a":"argon","t":"Was für ein seltsames Mädchen ..."},{"a":"sia","t":"Junger Mann, mit wem redest du da?"},{"a":"argon","t":"Ah, Sia! Nur eine schüchterne Passantin! Kein Grund zur Sorge!"},{"a":"sia","t":"... Verstehe. Nun denn, es scheint, dein Entschluss steht fest."},{"a":"sia","t":"Bist du bereit, als einer der Ritter des Königs dein Leben zu riskieren?"},{"a":"argon","t":"Darauf kannst du wetten! I-Ich meine, natürlich! Ich werde meinen Vater stolz machen!"},{"a":"sia","t":"Gut. Für deinen ersten Auftrag habe ich ein wichtiges, bevorstehendes Ereignis gewählt ..."}]},{"id":"argon_04","i":4,"title":"Mit leeren Händen","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Du beliebst wohl zu scherzen!"},{"a":"sia","t":"Du hast die Assassinin in die Ecke getrieben ... und konntest sie nicht aufhalten."},{"a":"sia","t":"Und nicht nur das. Du sagst auch noch, DU HÄTTEST SIE GEHEN LASSEN, weil du sie für einen guten Menschen hältst?!"},{"a":"argon","t":"..."},{"a":"sia","t":"Was für ein Unsinn ist das?"},{"a":"sia","t":"Dir ist SCHON bewusst, dass diese Assassinin unseren König töten wollte? Den Mann, den du geschworen hast, zu beschützen?"},{"a":"sia","t":"Solch ein Vorfall ist weitaus gefährlicher, als dein kleiner Geist verstehen kann."},{"a":"sia","t":"Uh ... Der König hat das letzte Wort, wenn es um die Entlassung seiner Ritter geht ..."},{"a":"sia","t":"... Aber erwarte nicht, dass ich mich für dich einsetzen werde. Und jetzt geh."},{"a":"argon","t":"..."},{"a":"argon","t":"Oh Mann ..."},{"a":"argon","t":"Tut mir leid, Papa."}]},{"id":"argon_a","i":4,"title":"Der Turm der Titanen","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"elderowen","t":"Der Turm der Titanen, was?"},{"a":"lilu","t":"Bitte erzähle uns alles darüber!"},{"a":"argon","t":"Ich habe Helden darüber flüstern gehört, aber niemand hat ihn je gesehen ..."},{"a":"elderowen","t":"Ja, der Turm der Titanen ist ein mythischer Ort. Niemand weiß, ob er wirklich existiert."},{"a":"elderowen","t":"Den Geschichten zufolge taucht er aus dem Nichts auf und fordert die mächtigsten Helden dazu heraus, seine vielen Etagen zu erklimmen ..."},{"a":"elderowen","t":"... bevor er plötzlich wieder verschwindet und die Erinnerungen aller löscht, die ihn gesehen haben könnten."},{"a":"argon","t":"Er l-löscht Erinnerungen?!"},{"a":"lilu","t":"Das ist seltsam ... Woher kommt dann die Legende?"},{"a":"argon","t":"Stimmt! Ein paar Leute müssten sich erinnern können!"},{"a":"elderowen","t":"Es heißt, jene, die die Herausforderung des Titanen bestehen, werden vom Turm als würdig erachtet."},{"a":"elderowen","t":"Diese Helden kehren zurück ... vom Erlebnis gezeichnet und mit ihren Erinnerungen."},{"a":"elderowen","t":"Um genauer zu sein: Ein Teil von ihnen bleibt im Turm und ein Teil des Turms bleibt bei ihnen."},{"a":"elderowen","t":"Und das war die Märchenstunde für heute. Danke, dass ihr den Geschichten eines alten Mannes gelauscht habt."},{"a":"lilu","t":"Wow! Ich frage mich, ob es ihn wirklich gibt?"},{"a":"argon","t":"Ja! Ich würde nur zu gern so einen Dungeon erkunden!"},{"a":"lilu","t":"Aber eines ist komisch ... Woher weiß der Älteste Owen das alles?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Fahrender Ritter","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Seufz ..."},{"a":"steel","t":"Wenn das nicht Argon ist! Wie geht es dir heute?"},{"a":"argon","t":"Oh, hallo Brohm ... Gibt es Aufträge für mich?"},{"a":"steel","t":"Heute nicht, Herr Ritter! Warum so traurig?"},{"a":"argon","t":"Ich bin jetzt nur noch Argon. Ich ... habe meinen Titel verloren."},{"a":"steel","t":"Oh, das tut weh ..."},{"a":"steel","t":"„Was auch passiert, du musst positiv denken! Du stehst das durch!“"},{"a":"steel","t":"Sicher hast du bald mehr Glück!"},{"a":"argon","t":"Stimmt ... Danke, Brohm."},{"a":"argon","t":"Ich ... hänge solange auf dem Marktplatz herum."},{"a":"argon","t":"Seufz ..."}]},{"id":"argon_b","i":5,"title":"Sind wir die Titanen?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"lilu","t":"Guten Morgen ... Argon."},{"a":"argon","t":"Gähn ... Morgen."},{"a":"lilu","t":"Du spürst es auch, oder?"},{"a":"argon","t":"Ja, ich bin total fertig! Ich fühle mich, als wäre ich die ganze Nacht auf einer Quest gewesen!"},{"a":"lilu","t":"Sieh mal, dein Schild ist auch ganz zerkratzt!"},{"a":"argon","t":"Was? Du hast recht! Ich könnte schwören, dass er gestern noch strahlend rein war ..."},{"a":"lilu","t":"Argon ... Glaubst du ...?"},{"a":"polonia","t":"Ahoi! Ist irgendwer von euch netten Landratten auf der Suche nach <c1>Molochschienen</c1>?"},{"a":"lilu","t":"Nein ... Vor allem keine 20 davon! Wo hast du die alle her?!"},{"a":"polonia","t":"Ha! Lustig, dass du fragst. Ich habe keine Ahnung."},{"a":"polonia","t":"Ich glaube, ich plündere vielleicht im Schlaf. Da rührt sich wohl die Piratenseele in mir, arr."},{"a":"lilu","t":"Diese seltsame Piratenfrau auch ..."},{"a":"lilu","t":"Haben wir uns alle dem Turm gestellt und danach unsere Erinnerungen verloren ...?"},{"a":"argon","t":"Das bedeutet, wir waren nicht stark genug ..."},{"a":"argon","t":"Ich werde hart fürs nächste Mal trainieren! Du wirst schon sehen!"}]},{"id":"argon_06","i":6,"title":"Zweites Licht","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Also war deine Assassinin diesem ... „Ritter“ ausgeliefert ..."},{"a":"sia","t":"... Aber er ließ sie gehen, weil er sie für einen guten Menschen hielt!"},{"a":"king","t":"Eine faszinierende Geschichte! Dieser neue Ritter scheint ein vielversprechender Kerl zu sein!"},{"a":"sia","t":"Bei allem Respekt, mein König ..."},{"a":"sia","t":"Dieser Mann hielt deine Assassinin nicht auf, nur wegen eines Bauchgefühls."},{"a":"king","t":"Der Inbegriff eines <c1>Paladins</c1>, findest du nicht?"},{"a":"sia","t":"Wie bitte?"},{"a":"king","t":"Dem Feind gegenüberzustehen und doch hinter Streit und Konflikt zu blicken ..."},{"a":"king","t":"... Und ihn dann gehen zu lassen, seiner Unschuld so sicher, dass er seinen Titel riskiert."},{"a":"king","t":"Ein unglaublicher Akt der Tapferkeit und der Güte!"},{"a":"sia","t":"Ich ... muss zugeben, dass ich diese Perspektive noch nicht in Erwägung gezogen habe, mein König."},{"a":"sia","t":"Aber im Königreich gab es seit Jahrzehnten keinen aufstrebenden Paladin mehr ..."},{"a":"sia","t":"Soll ich den Rat der Ritter versammeln, um die Angelegenheit zu besprechen?"},{"a":"king","t":"Unsinn! Ich kümmere mich selbst um die Formalitäten."},{"a":"sia","t":"Wie Ihr wünscht, mein König. Ich bereite sofort eine Eskorte vor."},{"a":"king","t":"Das ist nicht nötig. Ich werde so unauffällig wie eine Maus vorgehen!"}]},{"id":"argon_07","i":7,"title":"Der unscheinbare König","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"king","t":"Tretet beiseite, Bauern! Ein gewöhnlicher Arbeiter wandelt unter euch!"},{"a":"tavern","t":"Ah, König Reinhold! Lange nicht gesehen. Soll ich ein Fass Ambrosia aufmachen?"},{"a":"king","t":"Psst! Ich bin heute verdeckt unterwegs! Achte nicht auf mich!"},{"a":"tavern","t":"Ja, natürlich. Wie dumm von mir!"},{"a":"king","t":"Du da! Hinter der Theke!"},{"a":"argon","t":"Ah! Äh, tut mir leid, Majestät. Ich bin schon weg ..."},{"a":"king","t":"Unsinn! Ein zukünftiger Paladin ist mehr als würdig, neben meiner strahlenden Wenigkeit zu sitzen!"},{"a":"argon","t":"Neben ... Paladin?!"},{"a":"king","t":"Gewiss! In meiner unglaublichen Weisheit spüre ich großes Potenzial in dir!"},{"a":"king","t":"Trotz deiner ... ungewöhnlichen Methoden sitzt dein Herz am rechten Fleck und dein Sinn für Gerechtigkeit ist ... bewundernswert!"},{"a":"king","t":"Das Königreich hält dich deswegen für bereit, an der Paladin-Prüfung teilzunehmen!"},{"a":"argon","t":"Eine Paladin-Prüfung ... Wow!"},{"a":"argon","t":"Ich weiß alles darüber! Jede ist einzigartig und hängt vom Paladin selbst ab ..."},{"a":"argon","t":"Es muss eine gefährliche Aufgabe sein, wie das Töten eines Drachen ... oder das Zerstören eines gefährlichen Artefakts ..."},{"a":"king","t":"In der Tat! Eine angemessen tapfere und selbstlose Tat, die dem Wohle des Königreichs dient, soll es sein!"},{"a":"argon","t":"Verstanden! Danke, Majestät! Ihr werdet es nicht bereuen!"},{"a":"king","t":"Natürlich nicht, ich habe immer recht!"},{"a":"king","t":"Nun denn, da ich schon verdeckt unterwegs bin ..."},{"a":"king","t":"Du da! Alter Mann! Zeig mir, wie man Karten spielt!"},{"a":"master","t":"Karten, was? Der alte Theodor spielt nur mit hohem Einsatz ..."}]},{"id":"argon_08","i":8,"title":"Neu entflammt","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Argon! Warum hast du es so eilig?"},{"a":"argon","t":"Lilu, ich werde Paladin!"},{"a":"lilu","t":"Ein Paladin! D-das ist wunderbar, Argon! Wie ...?"},{"a":"argon","t":"Der König will, dass ich mich einer Prüfung stelle! Nur so kann man sich des Titels eines Paladins würdig erweisen."},{"a":"lilu","t":"Eine Prüfung ... Weißt du, was du da machen musst?"},{"a":"argon","t":"..."},{"a":"argon","t":"Oh nein! Ich habe keine Ahnung!"},{"a":"argon","t":"Es muss etwas von epischen und glorreichen Ausmaßen sein ..."},{"a":"lilu","t":"Aber Argon, du bist doch glorreich! Du hast Monster weit und breit in die Flucht geschlagen ..."},{"a":"argon","t":"Schon, aber es muss etwas Bedeutsameres sein ..."},{"a":"argon","t":"Ich habe von gefiederten Dämonen am Düsterturmgipfel gehört. Vielleicht würde das reichen ..."},{"a":"lilu","t":"Also, was auch immer es sein mag, ich bin mir sicher, dass du der Prüfung gewachsen bist!"},{"a":"argon","t":"Danke, Lilu ... Selbst, als ich kein Ritter mehr war, hast du noch an mich geglaubt ..."},{"a":"lilu","t":"Oh! D-das war doch nichts!"},{"a":"lilu","t":"Wie dem auch sei, du wirst Hilfe bei deiner Quest brauchen! Ich werde ein paar Heilungsschriftrollen für dich vorbereiten!"},{"a":"argon","t":"Wunderbar! Vorwärts!"}]},{"id":"argon_09","i":9,"title":"Treffen auf dem Düsterturm (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Uh ... was für ein nerviger Ort!"},{"a":"argon","t":"Dieses ganze Geklettere und keine Harpyien in Sicht ... Ich wurde sogar von Meuchelmördern überfallen!"},{"a":"argon","t":"Die haben irgendwie wie dieses Ninja-Mädchen ausgesehen, nicht?"},{"a":"argon","t":"Zum Glück hat Lilu mir diese Heilungsschriftrollen mitgegeben, puh!"},{"a":"argon","t":"Ich werde hier eine Pause machen."},{"a":"argon","t":"Hm?"},{"a":"yami","t":"Du schon wieder."},{"a":"argon","t":"D-Die Meuchelmörderin, die auf den König angesetzt war!"},{"a":"argon","t":"Das muss Schicksal sein. Eine noch höhere Prämie als die für eine Harpyie!"},{"a":"yami","t":"Na komm schon. Dich mache ich im Handumdrehen fertig."}]},{"id":"argon_10a","i":10,"title":"Siegreiche Rückkehr","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"König Reinhold! Die Aufgabe ist erledigt!"},{"a":"king","t":"Wunderbar! Welche Art schreckliche Bestie hast du erschlagen?"},{"a":"argon","t":"Ähm ... Was das angeht."},{"a":"yami","t":"... Hallo."},{"a":"king","t":"W-W-Was hat das zu bedeuten?!"},{"a":"sia","t":"Wachen! Verhaftet die beiden!"},{"a":"argon","t":"Nein! Moment! Sie hat sich geändert!"},{"a":"king","t":"Stimmt das?"},{"a":"yami","t":"Ich bin gekommen, um mich ... zu entschuldigen."},{"a":"sia","t":"Mein König, wir sollten ihr sicher nicht glauben ..."},{"a":"argon","t":"Ich kann für sie bürgen! Bei meiner Ritterehre!"},{"a":"king","t":"Also schön! Ich werde sie anhören!"},{"a":"sia","t":"Uh ... Ich hatte befürchtet, dass das passieren würde."},{"a":"sia","t":"Wachen! Holt Verstärkung und lasst sie keine Sekunde lang aus den Augen!"},{"a":"sia","t":"Argon, bitte warte draußen, während wir mit dieser ... Invasorin sprechen."},{"a":"argon","t":"Jawohl!"},{"a":"argon","t":"(Habe ich gerade einen Riesenfehler gemacht?)"}]},{"id":"argon_10b","i":11,"title":"Wiedergutmacher","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Uh ... Das kann ich heute nun wirklich nicht gebrauchen."},{"a":"argon","t":"Fräulein Sia! Wie ist es gelaufen?"},{"a":"sia","t":"Entgegen allen Erwartungen ist König Reinhold bereit, seiner Möchtegern-Meuchelmörderin zu verzeihen."},{"a":"sia","t":"Ich bin da weniger naiv, aber sie konnte uns wertvolle Informationen zu ihrem Orden in Azuma geben."},{"a":"argon","t":"D-Dann heißt das ...!"},{"a":"sia","t":"Ja, wir werden ihre Kapitulation und ihre Entschuldigung annehmen."},{"a":"sia","t":"Derzeit wird sie medizinisch versorgt, weil sie so abgemagert ist, aber sie sollte sich zur Gänze erholen."},{"a":"sia","t":"Und was dich angeht, Paladin Argon ..."},{"a":"argon","t":"P-Paladin!"},{"a":"sia","t":"Ja, eine Bedrohung abzuwenden ist eine Sache, aber eine Todfeindin des Königreichs dazu zu bringen, die Seiten zu wechseln ..."},{"a":"sia","t":"König Reinhold hatte wohl letztlich recht, was dich anbelangt."},{"a":"sia","t":"Und jetzt geh und feiere, Paladin. Ich bin sicher, dass du bald viel zu tun haben wirst!"},{"a":"argon","t":"Das mache ich! Danke."},{"a":"argon","t":"Papa ... Ich hoffe, du bist stolz auf mich."}]},{"id":"argon_epilogue","i":12,"title":"Epilog","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"P-Paladin?! Du hast es geschafft, Argon!"},{"a":"argon","t":"Einen Moment lang dachte ich wirklich, ich hätte alles vermasselt ..."},{"a":"argon","t":"Aber Papa hatte recht. Ich muss nur meinem Herzen folgen!"},{"a":"lilu","t":"Ah ... Aber bedeutet das, dass du auf Missionen ins Ausland geschickt wirst?"},{"a":"argon","t":"Noch nicht. Fräulein Sia hofft, dass ich Helden zu Paladinen ausbilden kann."},{"a":"lilu","t":"Ah, was für eine Erleichterung! Obwohl ich mir dich nur schwer als Lehrer vorstellen kann."},{"a":"lilu","t":"Wirst du nicht mit superwichtigen Paladin-Quests beschäftigt sein?"},{"a":"argon","t":"Ich werde mein Bestes geben! Das Königreich zählt auf mich!"},{"a":"tavern","t":"Hey du, edler Paladin!"},{"a":"tavern","t":"Brohm hat mir erzählt, dass er mal wieder neue Arbeitshandschuhe braucht!"},{"a":"argon","t":"Natürlich! Schon unterwegs!"},{"a":"lilu","t":"Manche Dinge ändern sich einfach nie, was?"},{"a":"tavern","t":"Nicht unser Argon, so viel ist sicher."}]},{"id":"argon_c","i":13,"title":"In Stein gehauen","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Der Trank ... hat nicht gewirkt, oder?"},{"a":"lilu","t":"Seufz ... Dabei haben wir so hart daran gearbeitet ..."},{"a":"lilu","t":"Entschuldige, Argon, ich war nicht gut genug ... Ich hoffe, da drin ist es nicht zu ungemütlich."},{"a":"elderowen","t":"Hmm ... Das sind wirklich schlechte Neuigkeiten."},{"a":"lilu","t":"Wir haben durchaus noch Optionen, aber ..."},{"a":"lilu","t":"... Es ist echt schwer, wenn er nicht hier bei uns ist."},{"a":"elderowen","t":"Ohne ihn fühlt sich die Stadt ganz leer an, nicht wahr?"},{"a":"lilu","t":"... Wie eine Geburtstagsparty ohne Freunde."},{"a":"lilu","t":"Zu jammern bringt ihn auch nicht schneller zurück. Ich mache mich wieder an die Arbeit."},{"a":"lilu","t":"Vielleicht kann Donovan uns helfen."},{"a":"lilu","t":"Das wird teuer, aber wir können unser Geld zusammenlegen!"},{"a":"lilu","t":"Ich weiß, dass du gar nicht anders kannst, aber ... Kopf hoch! Wir werden dich retten!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"Ein ungewöhnlicher Samurai","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Ein echter Samurai ...! Ich kann es kaum erwarten!"},{"a":"argon","t":"Fräulein Samurai! Ich bin Argon, Ritter in der Aus..."},{"a":"ashley","t":"Hi. Ich bin Ashley! Was geht?"},{"a":"argon","t":"H-Hi?"},{"a":"tavern","t":"Füße vom Tisch, wenn ich bitten darf!"},{"a":"ashley","t":"Ts. Okay."},{"a":"ashley","t":"Also? Was brauchst du?"},{"a":"argon","t":"Äh ... Sind Samurai sonst nicht eher gesittet und so?"},{"a":"ashley","t":"Hm? Ja, die Leute daheim waren ganz schön spießig."},{"a":"ashley","t":"Jetzt bin ich frei. Einfach ein Rōnin. Ein Samurai ohne Herr."},{"a":"argon","t":"Ich verstehe ... Oh, okay!"},{"a":"argon","t":"Ich hatte eine Quest mit Lilu zum Spukschloss geplant, aber ..."},{"a":"argon","t":"Mir ist im Trainingsraum etwas dazwischengekommen! Kannst du für mich einspringen?"},{"a":"ashley","t":"Klar. Aber dafür schuldest du mir was, Ritterjunge."}]},{"id":"ashley_02","i":2,"title":"Bewaffnet und bereit","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"Du bist Lilu, oder?"},{"a":"lilu","t":"Ja, ganz genau! Schön, dich kennenzulernen!"},{"a":"ashley","t":"Also gut, dann mal los."},{"a":"lilu","t":"M-Moment! Warte mal!"},{"a":"lilu","t":"Wir haben noch keine Vorbereitungen getroffen. Tränke, Vorräte und ..."},{"a":"ashley","t":"Egal, das brauchen wir alles nicht."},{"a":"ashley","t":"Wir leben oder wir sterben. Dazwischen gibt es nichts."},{"a":"lilu","t":"Das ... nein! Das ist zu leichtsinnig!"},{"a":"ashley","t":"Also, ich geh dann mal. Hier entlang, oder?"},{"a":"lilu","t":"Nein! Da ist der Wisperwald ..."},{"a":"argon","t":"Ähm ... Viel Glück?"}]},{"id":"ashley_03","i":3,"title":"Gratwanderung","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"Mehr habt ihr Monster nicht drauf? GEBT ALLES!"},{"a":"lilu","t":"Ashley! Bitte geh es ein wenig ruhiger an! Ich komm mit der Heilung gar nicht nach!"},{"a":"ashley","t":"Das ... ist ... NICHTS!"},{"a":"ashley","t":"Puh ... nette Rauferei, was?"},{"a":"lilu","t":"Machst du Scherze?! Du wärst beinahe gestorben!"},{"a":"lilu","t":"Kein Wunder, dass du deinen Arm verloren hast, wenn du dich so benimmst!"},{"a":"ashley","t":"Hey. Das war was anderes."},{"a":"ashley","t":"Dieser Fehler ... passiert mir nicht noch mal."},{"a":"lilu","t":"Hmpf. Ich verwende keine Narkosemittel für diese Heilung."},{"a":"lilu","t":"Du bist selber schuld. Mach dich bereit."},{"a":"ashley","t":"Haha ... hah ... Ich halte das aus ..."},{"a":"ashley","t":"Autsch! Au-au-au ..."}]},{"id":"ashley_a","i":4,"title":"Vertrautes Gefühl","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"ashley","t":"Hey! Was ist mit all diesen kleinen Monstern hier?"},{"a":"elven","t":"Das sind meine lieben Vertrauten. Willkommen."},{"a":"elven","t":"Würdige Champions können einen als treuen Gefährten adoptieren."},{"a":"ashley","t":"Oh. Haustiere also? Kapiert."},{"a":"ashley","t":"Also gut. Du, grünes Kerlchen. Ich werde dich <c1>Streichmeisterin</c1> nennen. Komm mit."},{"a":"ashley","t":"Du bist süß, <c1>Schneeball</c1>. Ich werde dich tragen."},{"a":"elven","t":"Ah ... Tut mir leid, das ..."},{"a":"ashley","t":"Puh, das ist ja mal ein hässlicher Vogel!"},{"a":"ashley","t":"Ich nenne dich <c1>Spatz</c1>. Dich nehm ich auch mit."},{"a":"elven","t":"... Ich verstehe. Viel Spaß!"}]},{"id":"ashley_04","i":5,"title":"Quest erfolgreich gescheitert","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Wie ist die gestrige Quest gelaufen? Lilu sah ziemlich aufgebracht aus ..."},{"a":"ashley","t":"Ich bin wohlbehalten zurückgekehrt. Bedauerlicherweise."},{"a":"argon","t":"Was!? Ist das nichts Gutes?"},{"a":"king","t":"Seid gegrüßt, Normalsterbliche! Bestaunt ruhig meine Herrlichkeit!"},{"a":"ashley","t":"Ah, Königliche Hoheit! Ashley meldet sich zum Dienst!"},{"a":"king","t":"Das ist doch mal ein gutes Beispiel für einen Soldaten! Weiter so!"},{"a":"ashley","t":"Ja, Sir! Danke, Sir!"},{"a":"tavern","t":"Tut mir leid, Reinhold, dein Jahrgang ist noch nicht reif genug."},{"a":"king","t":"Also schön! Ich werde morgen wiederkommen!"},{"a":"argon","t":"Was war das denn?"},{"a":"ashley","t":"Oh, äh. Ich habe früher einem Herrn gedient. Da kommen alte Gewohnheiten wieder zum Vorschein."},{"a":"argon","t":"Cool! Erzähl mir davon!"},{"a":"ashley","t":"Nein."}]},{"id":"ashley_05","i":6,"title":"Wendegeschichte","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"... Und dann sagte ich zu dem Typen ..."},{"a":"ashley","t":"„Allzeit bereit? Nun, man könnte sagen, ich bin bereit!“"},{"a":"argon","t":"Hahaha!"},{"a":"argon","t":"... Aber Ashley, was diesen Herrn angeht, den du vorhin erwähnt hast ..."},{"a":"ashley","t":"Aaaaah, Mann ... du hörst wohl nie auf. Na gut."},{"a":"ashley","t":"... Samurai haben einen Herrn, einen Daimyō. Wir dienen ihm und beschützen ihn mit unserem Leben."},{"a":"argon","t":"Sehr ehrenwert!"},{"a":"ashley","t":"Eines Tages aß er wie gewohnt zu Mittag ..."},{"a":"ashley","t":"Und plötzlich, bumm. Ninjas. Überall im Raum. Und alle hatten es auf den Kopf meines Meisters abgesehen."},{"a":"ashley","t":"Wir kämpften hart. Es war nicht das erste Mal. Aber ..."},{"a":"ashley","t":"Ich habe einen schweren Schlag abbekommen. Ich verlor meinen Arm."},{"a":"ashley","t":"Dann ... rannte ich davon. Und ließ ihn zum Sterben zurück."},{"a":"argon","t":"Ashley ..."},{"a":"ashley","t":"... RAAAAAAAH!!! Ich hätte dort einfach sterben sollen!"},{"a":"ashley","t":"... Naja, gib mir noch einen Drink."},{"a":"tavern","t":"Du hast wirklich genug für heute, Ashley."},{"a":"ashley","t":"Schon gut. Ist okay. Ich hab genug."},{"a":"ashley","t":"Also gut. Argon, geh und sag Lilu, dass Ashley sich auf eine wirklich gefährliche Quest begeben wird."},{"a":"argon","t":"Hm? Jetzt!?"},{"a":"ashley","t":"Natürlich. Ich mache mich auf zu ... sagen wir mal, den Aurorahöhlen. Du solltest dich besser beeilen!"}]},{"id":"ashley_06","i":7,"title":"Ein Auge für ein Ich","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"... Ninja-Mädchen. Hast du etwa gelauscht?"},{"a":"yami","t":"... Nur ein bisschen. Sollen wir das draußen klären?"},{"a":"ashley","t":"Hah! Ich bin nicht in der Stimmung für einen Streit."},{"a":"yami","t":"Mein Clan hat das Herrn Kusunoki angetan. Ich bin ein Verstoßener, aber vielleicht kann ich mich entschuldigen ..."},{"a":"ashley","t":"Danke, aber das musst du nicht tun. Ich hasse nicht dich, sondern mich selbst."},{"a":"yami","t":"Ich verstehe ... Vielleicht mehr, als du dir vorstellen kannst."},{"a":"yami","t":"Aber selbst wenn dein Ansehen ruiniert ist, hast du noch viel, wofür es sich zu leben lohnt."},{"a":"yami","t":"Du hast hier Freunde. Eine Stadt wie eine Familie. Haustiere, die du liebst."},{"a":"yami","t":"... Aber wenn dir das nicht reicht, kann ich dir ein ehrenhaftes Duell auf Leben und Tod anbieten."},{"a":"ashley","t":"Ein Ninja, der mich kostenlos umlegen will? Wie großzügig von dir."},{"a":"ashley","t":"Danke, ich verzichte. Ich werde aber darüber nachdenken."},{"a":"yami","t":"Wie du wünscht."}]},{"id":"ashley_07","i":8,"title":"Ein letzter Kampf","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Schnauf ... schnauf ... Ashley ist nicht hier ..."},{"a":"lilu","t":"Hat sie sich schon wieder verlaufen ...?"},{"a":"lilu","t":"Nein ... Moment mal. Wurde ich reingelegt?"},{"a":"ashley","t":"Ich dachte, ich wäre auf dem Weg zum Ascheseevulkan ..."},{"a":"ashley","t":"Wie auch immer, das reicht."},{"a":"ashley","t":"In Ordnuuuung! Aufwachen, ihr Schwachköpfe! Ashley ist hier!"},{"a":"monster_Grotto_Mob","t":"Ist der Mensch ... betrunken?"},{"a":"ashley","t":"Heute kein lästiger Heiler, nur ich und mein Todesmut! Ich höre erst auf, wenn ich tot bin!"},{"a":"ashley","t":"Egal, was passiert, ich gewinne! Also, wer will als Erster?"},{"a":"monster_Ruins_Mob","t":"Grah! Kommt schon!"},{"a":"ashley","t":"Das ist die richtige Einstellung!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"priest","t":"Oh Göttin ... ist dies der Ort?"},{"a":"priest","t":"Meine Güte, was für ein Blutbad."},{"a":"monster_Grotto_Mob","t":"Hehehe."},{"a":"priest","t":"Entschuldigt bitte, Monster. Lasst mich bitte meinen Begleiter holen."},{"a":"monster_Grotto_Mob","t":"Auf keinen Fall! Auf keinen Fall! Sie hat uns fertiggemacht! Dieser Samurai ist mausetot!"},{"a":"priest","t":"Sie lebt noch. Unsere Ashley ist stärker als das."},{"a":"monster_Ruins_Mob","t":"Was? Dann sollte ich die Sache besser zu Ende bringen!"},{"a":"priest","t":"Das wirst du nicht tun."},{"a":"monster_Grotto_Mob","t":"Hehe, ha! Und was willst du TUN? Uns heilen?"},{"a":"priest","t":"Du lässt mir keine Wahl. Möge die Göttin Asthea dir vergeben ..."},{"a":"priest","t":"Denn ich tue es nicht."}]},{"id":"ashley_09","i":10,"title":"Bettruhe-Bedrängnis","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"... Uff ..."},{"a":"priest","t":"Endlich bist du zu dir gekommen."},{"a":"ashley","t":"Was? Verdammt ... du auch noch? Wie hast du mich ... gefunden?"},{"a":"priest","t":"Es scheint, als ob sich die Göttin um dich sorgt. Ich wurde an ihrer Stelle geschickt."},{"a":"ashley","t":"Verdammt ... Komm schon, Doc, lass mich einfach sterben."},{"a":"priest","t":"Wenn das wirklich dein Wunsch ist."},{"a":"ashley","t":"Puh ... endlich ..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"Und warum HEILST du mich dann noch immer?"},{"a":"priest","t":"Trotz deiner Worte scheint es, als wolltest du noch immer leben."},{"a":"priest","t":"Heilmagie stärkt nur deine Lebenskraft. Wenn du wirklich sterben wolltest, könnte ich nichts tun, um dich zu retten."},{"a":"ashley","t":"Ist das ... so ..."},{"a":"priest","t":"Ruh dich jetzt aus. Es gibt vieles, worüber du nachdenken musst."}]},{"id":"ashley_10","i":11,"title":"Eine Zeit zum Nachdenken","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Du bist zurück! Lilu hat dich überall gesucht!"},{"a":"argon","t":"...Du siehst auch etwas mitgenommen aus."},{"a":"ashley","t":"Mach dir nichts draus, ich wurde geflickt. Mein Fett hab ich aber auch weggekriegt."},{"a":"argon","t":"Von Freyja? Das ist kaum vorstellbar."},{"a":"ashley","t":"Ja. Sie hat mir gesagt, ich soll anfangen nachzudenken. Also denk' ich nach."},{"a":"tavern","t":"Nachdenken? Das ist neu!"},{"a":"ashley","t":"Hör auf damit."},{"a":"ashley","t":"...das würde ich gerne sagen, aber du hast recht."},{"a":"ashley","t":"So lange in der Vergangenheit verweilt, ich vergaß, überhaupt zu denken."},{"a":"argon","t":"Worüber nachdenken?"},{"a":"ashley","t":"Hmm. So einiges."},{"a":"ashley","t":"Ohne es zu bemerken, habe ich wohl vieles angesammelt, das mir wichtig war."},{"a":"ashley","t":"Die Stadt. Die Menschen. Der Krämer. Du auch, Ritterjunge."},{"a":"ashley","t":"Es brauchte nur einige Male, dem Tod knapp zu entkommen, um es zu merken. Ich bin wohl begriffsstutzig, heh."},{"a":"argon","t":"Es ist mir eine Ehre, Dame Samurai!"},{"a":"ashley","t":"Bin immer noch ein Ronin hier. Erwarte nicht, dass sich das so schnell ändert."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Epilog","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"ashley","t":"Hey, Lilu. Ich mache mich auf zu einer neuen Quest. Willst du mitkommen?"},{"a":"lilu","t":"Hmpf! Damit du mich wieder an den falschen Ort schicken kannst?"},{"a":"lilu","t":"Oder dich so rücksichtslos auf die Monster stürzen kannst, dass ich dich wieder zusammenflicken muss?"},{"a":"ashley","t":"... Nein, ich bin jetzt eine andere Frau. Ich werde mich zurückhalten und nur mit einer Hand kämpfen."},{"a":"lilu","t":"Hm ... wenn du das sagst."},{"a":"lilu","t":"Moment mal ..."},{"a":"ashley","t":"Haha! War nur Spaß."},{"a":"ashley","t":"Wenn du mir Rückendeckung gibst, gebe ich dir Rückendeckung."},{"a":"lilu","t":"Klingt gut! Aber diesmal musst du es mir versprechen."},{"a":"lilu","t":"Wenn es zu brenzlig wird ... ziehen wir uns zurück. DU ziehst dich zurück."},{"a":"ashley","t":"Versprochen. Rōnin-Ehre ... falls das überhaupt noch etwas bedeutet."},{"a":"ashley","t":"Immerhin haben wir ein Zuhause, wohin wir zurückkehren können."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"Papa ist zu Hause","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"bjorn","t":"Hallo Kinder! Papa ist zu Hause!"},{"a":"steel","t":"Papa!"},{"a":"wood","t":"... Papa."},{"a":"bjorn","t":"Warum das lange Gesicht, Gorza?"},{"a":"wood","t":"Du warst monatelang fort!"},{"a":"bjorn","t":"So machen das Waldhüter eben! Draußen in der Natur sein, weit weg von zu Hause."},{"a":"wood","t":"Pfft. Du könntest ruhig öfter mal vorbeischauen."},{"a":"bjorn","t":"Das würde ich ja gerne, aber der Ascheseevulkan hält mich ganz schön auf Trab."},{"a":"wood","t":"Der Vulkan? Du hast doch gesagt, du würdest den Düsterturmgipfel erforschen ..."},{"a":"bjorn","t":"... Habe ich das?"},{"a":"bjorn","t":"Da bin ich wohl durcheinandergekommen! Haha!"},{"a":"bjorn","t":"Auf jeden Fall habe ich euch beiden Souvenirs mitgebracht! Schaut mal!"},{"a":"steel","t":"Oh, ich hoffe auf ein Krabben-Stofftier!"}]},{"id":"bjorn_a","i":1,"title":"Bester Kumpel Bamham","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"bjorn","t":"Hey Kinder, könntet ihr kurz auf Bamham aufpassen?"},{"a":"wood","t":"Dieses fiese Wildschwein? Vergiss es. Nimm ihn doch mit."},{"a":"steel","t":"Nichts für ungut, Papa, aber er ist irgendwie ... verrückt?"},{"a":"bjorn","t":"Och, sagt so was nicht! Er ist doch so niedlich!"},{"a":"wood","t":"Papa, immer wenn du ihn runterlässt, rastet er völlig aus."},{"a":"bjorn","t":"Das war nur ein Unfall. Er war nur etwas aufgeregt."},{"a":"wood","t":"Und die ganzen anderen Vorfälle?"},{"a":"bjorn","t":"Alles Unfälle. Der kleine Bamham würde keiner Fliege was zuleide tun!"},{"a":"wood","t":"Würde er doch, und er würde es genießen."},{"a":"wood","t":"Hör mal, Papa, es ist besser, du trägst dieses Untier, wenn du in die Stadt gehst."},{"a":"steel","t":"... So ist es für alle am sichersten."},{"a":"bjorn","t":"Also gut, ich hab verstanden. Schon okay, Bamham, ich hab dich lieb."},{"a":"bjorn","t":"Woah, woah! Ruhig, Bamham!"}]},{"id":"bjorn_02","i":2,"title":"Bjorns Einkaufsbummel","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"bjorn","t":"Danke, dass ihr mich so herzlich empfangen habt. Es ist schön, wieder hier zu sein!"},{"a":"elderowen","t":"Wir sind erleichtert, dass du heil zurückgekommen bist. Nachdem du monatelang verschwunden warst, hatten wir schon das Schlimmste befürchtet ..."},{"a":"bjorn","t":"Tut mir leid! So ist das Leben eines Waldhüters nun mal! Haha!"},{"a":"oils","t":"So wie ich dich kenne, planst du bestimmt schon wieder die nächste Expedition!"},{"a":"bjorn","t":"Haha, du kennst mich gut! Wir brechen morgen bei Sonnenaufgang auf!"},{"a":"oils","t":"Du änderst dich auch nie, Bjorn. Ich werde ein Auge auf Brohm und Gorza haben, während du fort bist."},{"a":"oils","t":"... Wenn es keine Umstände macht, würdest du unterwegs ein paar Leuchtpilze für mich sammeln?"},{"a":"bjorn","t":"Klar, das ist gar kein Problem!"},{"a":"elderowen","t":"Oh ... mein Rücken macht mir in letzter Zeit zu schaffen. Vielleicht findest du ein paar Eisperlen?"},{"a":"bjorn","t":"Kann ich machen. Ich halte die Augen offen, Ältester."},{"a":"engineer","t":"Oh, Bjorn! Ich könnte Rostwyrm-Schuppen für mein nächstes Experiment gebrauchen, wenn es nicht zu viel verlangt ist."},{"a":"bjorn","t":"Ist es nicht. Ist notiert."},{"a":"bjorn","t":"Puh! Wir sollten wohl lieber ein paar zusätzliche Taschen mitnehmen, Bamham!"}]},{"id":"bjorn_03","i":3,"title":"Altes Eisen","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"bjorn","t":"Hmm ... Riechst du das auch, Bamham?"},{"a":"bjorn","t":"Ja, Metall. Altmetall vermutlich. Komm, Bamham, hol es mir!"},{"a":"bjorn","t":"Guter Junge, lass mich mal sehen ..."},{"a":"bjorn","t":"Hm. Was für ein seltsames Gerät. Ich glaube nicht, dass jemand es hier vergessen hat ..."},{"a":"bjorn","t":"Ich wette, wenn ich hier ziehe ..."},{"a":"bjorn","t":"Hmm ... ja, genau das hatte ich erwartet."},{"a":"bjorn","t":"... Dann geht es kaputt. Wir haben wohl nicht viel gelernt, was? Haha!"},{"a":"bjorn","t":"Aber ich denke, wir haben unsere Spur. Wir haben uns monatelang umgesehen und dieses Ding war letztes Mal noch nicht da."},{"a":"bjorn","t":"Wir sollten lieber umkehren und einen Profi zurate ziehen. Du weißt ja, ich kenne mich mit Technik nicht gut aus."}]},{"id":"bjorn_04","i":4,"title":"Unbekanntes Signal","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"engineer","t":"Was für ein seltsames Objekt! Ich habe noch nie etwas Vergleichbares gesehen."},{"a":"engineer","t":"Es scheint Magie und Wissenschaft zu vereinen und funktioniert wie ein ... Signal? Ein Radar?"},{"a":"engineer","t":"Du sagtest, es war kaputt, als du es gefunden hast?"},{"a":"bjorn","t":"Ja. Was für ein Pech, was? Haha!"},{"a":"engineer","t":"Schade. Ich kann eigentlich nur so viel sagen: Es sendet eindeutig irgendwelche Informationen."},{"a":"engineer","t":"Weißt du was, wenn du einen Moment Geduld hast, kann ich ein Gerät für dich herstellen, mit dem du mehr von diesen ... Zaubersignalen finden kannst."},{"a":"bjorn","t":"Großartig! Bist du bereit, wieder loszuziehen, Bamham?"},{"a":"bjorn","t":"Wir wissen nicht, was das ist ... aber es ist bestimmt nichts Gutes."},{"a":"bjorn","t":"Es ist unsere Aufgabe, herauszufinden, wer dahintersteckt!"},{"a":"engineer","t":"Viel Glück! Und ... sei vorsichtig beim Umgang mit geheimnisvoller Technologie!"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Originalrezept","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"herbalist","t":"Willkommen bei Maribels Medizinhandel. Wie kann ich dir helfen?"},{"a":"donovan","t":"Fräulein Maribel? Ich wollte dir persönlich ein Lob für deine neueste Schöpfung aussprechen."},{"a":"donovan","t":"Als Erfinder des Tranks der Erholung muss ich sagen, dass dein überarbeiteter Entwurf einfach genial ist!"},{"a":"donovan","t":"Nur die Beifügung einer Prise Nebelblüte ist eine unglaubliche Verbesserung!"},{"a":"herbalist","t":"Moment mal ... Willst du damit sagen, du bist DER Donovan? Niemals!"},{"a":"herbalist","t":"Der Entwurf für den Trank der Erholung wurde vor circa 700 Jahren entwickelt ..."},{"a":"herbalist","t":"Selbst für einen Elfen siehst du keinen Tag älter als 150 aus!"},{"a":"donovan","t":"Du bist zu freundlich, Fräulein Maribel."},{"a":"donovan","t":"Ich will es so ausdrücken: Nicht alle meine Entwürfe sind im Handel erhältlich ..."},{"a":"donovan","t":"Aber ich bin sicher, dass eine meisterhafte Alchemistin wie du keine Schwierigkeiten damit hätte, sie zu erlernen."},{"a":"donovan","t":"Also dann, soll ich mir diese Nebelblüte mal ansehen?"}]},{"id":"donovan_02","i":2,"title":"Land des Überflusses","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"donovan","t":"Faszinierend ... Selbst die gewöhnlichen Äpfel hier sind von herausragender Qualität."},{"a":"donovan","t":"Wie kann das sein, frage ich mich ...?"},{"a":"lilu","t":"Wenn jemand eine Erklärung dafür hat, dann sicher Juniper!"},{"a":"lilu","t":"Oh, tut mir leid! Ich wollte deine Unterhaltung mit diesem ... Baum nicht stören."},{"a":"donovan","t":"Ah, eine junge Dame mit einem breitkrempigen Hut und ihrer treuen Eule ..."},{"a":"donovan","t":"Du musst Fräulein Lilu sein, ohne Zweifel."},{"a":"lilu","t":"Das stimmt! Und du, Herr Donovan, musst dich offensichtlich nicht vorstellen!"},{"a":"donovan","t":"Ich habe viel von der talentierten jungen Schülerin dieser Stadt gehört. Das Vergnügen ist ganz meinerseits."},{"a":"donovan","t":"Also, Fräulein Lilu. Was wolltest du sagen ...?"},{"a":"lilu","t":"Oh ja! Juniper spricht ständig davon, wie sehr das Land um die Stadt vor Leben sprüht ..."},{"a":"lilu","t":"Das ist mit ein Grund, warum sie hier so gerne gärtnert, sagt sie."},{"a":"lilu","t":"Jedenfalls war ich gerade auf dem Weg zu den Aurorahöhlen. Es war schön, dich kennenzulernen, Donovan!"},{"a":"donovan","t":"Hoffentlich sehen wir uns bald wieder."},{"a":"donovan","t":"Hm ... Diese junge Dame könnte da auf der richtigen Spur sein ..."},{"a":"donovan","t":"Kern ... ausgelaugt? Es scheint, als wäre in diesem Königreich alles viel lebendiger."},{"a":"donovan","t":"Ich sollte diese Gärtnerin besuchen. Wenn die Zutaten hier stärker sind ..."},{"a":"donovan","t":"... muss ich das ausnutzen."}]},{"id":"donovan_03","i":3,"title":"Hinter der Maske","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Du wolltest mit mir reden, Sia?"},{"a":"sia","t":"Ah, Lilu. Danke, dass du so kurzfristig kommen konntest."},{"a":"sia","t":"Soweit ich weiß, kennst du Donovan schon?"},{"a":"lilu","t":"Oh ja! Unter den Alchemisten ist er eine Legende! Ich freue mich so, dass ich ihn kennenlernen konnte!"},{"a":"sia","t":"Behandle den Mann mit extremer Vorsicht."},{"a":"lilu","t":"Hä?! Aber er ist so ein Gentleman! Und auch sehr klug ..."},{"a":"sia","t":"Der Schein kann trügen. Hinter seiner jungen Fassade schlummert ein gerissenes, Jahrtausende altes Genie."},{"a":"lilu","t":"Jahrtausende?! Das ist unmöglich, selbst für Elfen! Glaubst du ..."},{"a":"sia","t":"Ja. Manche glauben, er könnte eine Art Elixier für Unsterblichkeit entdeckt haben."},{"a":"lilu","t":"Wow! Dieses Rezept würde ich gern in mein Zauberbuch aufnehmen!"},{"a":"sia","t":"Genau wie viele Herrscher. Ich vermute, dass der Imperator von Kern nach seiner Pfeife tanzen könnte."},{"a":"lilu","t":"... Politik ist ja wirklich kompliziert."},{"a":"lilu","t":"Aber danke! Ich werde vorsichtig sein!"},{"a":"sia","t":"Ich wusste, du würdest das verstehen."},{"a":"sia","t":"Ich für meinen Teil werde ihn von unserem ... beeinflussbaren König fernhalten."},{"a":"lilu","t":"Ja ... So ist es wohl am besten."}]},{"id":"donovan_a","i":3,"title":"Zehn Goldstücke – ein Schnäppchen","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"leather","t":"Hey, Tranktyp, hast du schnell Zeit?"},{"a":"donovan","t":"Uh ... Landstreicher."},{"a":"donovan","t":"Mit wem habe ich das ... Vergnügen?"},{"a":"leather","t":"Ich bin Tamas, der Ledertyp."},{"a":"leather","t":"Ich habe gehört, dass du ein cooles Elixier der Unsterblichkeit brauen kannst, Mann. Kann ich eine Flasche haben?"},{"a":"donovan","t":"Ich habe keine Ahnung, wie du von diesem Gerücht erfahren hast."},{"a":"donovan","t":"Selbst wenn es wahr wäre, kannst du dir sicher sein, dass ich etwas derart Kostbares nicht einfach hergeben würde."},{"a":"leather","t":"Ich biete dir zehn Goldstücke dafür."},{"a":"donovan","t":"Auf KEINEN Fall. Kriege wurden um dieses Rezept geführt! Kaiser aus aller Welt betteln um einen Tropfen davon!"},{"a":"leather","t":"Du verhandelst hart, Mann. Fünfzehn Goldstücke, mein letztes Angebot."},{"a":"donovan","t":"Hat der Geruch von Leder deinem Hirn zugesetzt, Vagabund? Ich würde das Rezept nicht für alles Gold der Welt hergeben!"},{"a":"donovan","t":"Ich muss los. Bitte sprich nie wieder mit mir."},{"a":"leather","t":"Verdammt, fast hätte ich es bekommen."},{"a":"leather","t":"Dann muss ich wohl ein anderes Leckerli für diese Schafe auftreiben."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Lauernder Schatten","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"hemma","t":"... Und so fiel der Nervtöter-Kobold, aber vorher konnte er meinen Begleitern noch einige Schläge verpassen."},{"a":"hemma","t":"Bitte heile sie."},{"a":"priest","t":"Aber natürlich. Ich werde mich schnellstens um ihre Wunden kümmern."},{"a":"lilu","t":"Hallo! Ich habe gehört, dass eine neue Hexerin in der Stadt ist."},{"a":"lilu","t":"Ich bin Lilu! Schön, dich kennenzulernen!"},{"a":"hemma","t":"Du hast recht, junge Lilu. Unser Name ist Hemma. "},{"a":"lilu","t":"„Unser“?"},{"a":"hemma","t":"Ja. Nekromantie fordert ihren Tribut bei den Zauberern ..."},{"a":"hemma","t":"Ein Teil von dir bleibt hinter dem Schleier, während andere Dinge die Schwelle übertreten ..."},{"a":"hemma","t":"Diese Kräfte ... haben uns verändert. Zum Besten natürlich."},{"a":"lilu","t":"Nekromantie sagst du?! Ist das nicht ... gefährlich?"},{"a":"hemma","t":"Unglaublich gefährlich. Aber wir geben uns nicht mehr mit einfachen Tricks zufrieden."},{"a":"hemma","t":"Nun, wenn du uns entschuldigen würdest, wir müssen woanders hin. Leb wohl."},{"a":"lilu","t":"Eine Nekromantin ... Das ist richtig dunkle Magie, Pollux! Aber das ist das erste Mal, dass ich so einer Zauberin begegne!"},{"a":"lilu","t":"Sie wirkte nicht so übel ... Oder?"}]},{"id":"hemma_02","i":2,"title":"Zu jedem Preis","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"elderowen","t":"Eine Nekromantin ...?"},{"a":"elderowen","t":"Ich bin nicht sicher, was ich davon halten soll ..."},{"a":"hemma","t":"Deine Sorgen sind begründet. Nekromantie ist eine gefährliche Kunst, die schwächere Wesen verzehren würde ..."},{"a":"hemma","t":"Aber wir sind alles andere als schwach."},{"a":"elderowen","t":"Was ist mit den Abenteurern, die dich begleiten? Nutzt du sie nicht aus, um deine Zauber zu verstärken?"},{"a":"hemma","t":"Nur mit ihrer Zustimmung. Die Effekte sind nicht dauerhaft."},{"a":"hemma","t":"Und wir bezahlen sie auch gut für ihre Dienste."},{"a":"elderowen","t":"Ich nehme an, etwas Gutes machst du doch ..."},{"a":"elderowen","t":"Na schön. Ich denke, du kannst ein genehmigter Champion unserer Stadt sein."},{"a":"hemma","t":"Wir hätten deine Erlaubnis nicht gebraucht ... aber wir danken dir."},{"a":"elderowen","t":"Also, was hat dich in unsere Stadt geführt?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Wir sind nur auf der Suche nach Wissen und Macht. "},{"a":"hemma","t":"Es gibt ... eine Aufgabe, die wir erledigen müssen."},{"a":"elderowen","t":"Sehr vage ..."},{"a":"hemma","t":"Und so wird es auch bleiben. Leb wohl."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"In diesen Augen liegt viel Traurigkeit ..."}]},{"id":"hemma_03","i":3,"title":"Der innere Feind","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"herbalist","t":"... Unreife Lebendwurzeln und ein extraklobiges grusliges Ektoplasma. Darf’s sonst noch was sein?"},{"a":"hemma","t":"Das wäre alles. Den Rest holen wir uns beim Ladenbesitzer."},{"a":"herbalist","t":"Danke. Beehre uns bald wieder!"},{"a":"hemma","t":"<c4>... Vergiss die grimmigen Krallen nicht.</c4>"},{"a":"hemma","t":"Ah, ja. Ein Paar grimmige Krallen, bitte."},{"a":"herbalist","t":"Was war DAS denn gerade?"},{"a":"hemma","t":"Achte nicht darauf. Einfach nur ein Mitreisender."},{"a":"hemma","t":"<c4>Lass-mich-raus-lass-mich-raus-lass-mich-raus.</c4>"},{"a":"hemma","t":"Uh. Beruhige dich, okay?"},{"a":"hemma","t":"Der Rest ist für dich. Leb wohl."},{"a":"herbalist","t":"Danke für das Trinkgeld ... und die Albträume."}]},{"id":"hemma_a","i":3,"title":"Unter Unsterblichen","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"donovan","t":"Unreife Lebendwurzeln? Interessante Wahl."},{"a":"hemma","t":"Was meinst du damit?"},{"a":"donovan","t":"Lebendwurzeln sind mächtige Reagenzien für viele magische Formeln, die mit Jugend und Lebenserwartung zu tun haben."},{"a":"donovan","t":"Bist du etwa eine Alchemistenkollegin? Auf der Suche nach einem langen Leben vielleicht?"},{"a":"hemma","t":"... Fragst du eine Dame nach ihrem Alter? Wie ... unziemlich."},{"a":"hemma","t":"Wir sind keine Alchemisten. Blutopfer sind weitaus wirksamer."},{"a":"donovan","t":"Ah, Nekromantie! Ein respektables, wenngleich missverstandenes Gebiet."},{"a":"hemma","t":"Und was unser Alter betrifft ... wir zählen schon lange nicht mehr mit."},{"a":"donovan","t":"Das kann ich verstehen. Nach den ersten paar Jahrhunderten vergehen die Jahrzehnte fast wie im Flug!"},{"a":"donovan","t":"Unter all diesen Eintagsfliegen kann man sich schon mal einsam fühlen, nicht wahr?"},{"a":"hemma","t":"Einsam sind wir nicht. Du solltest dich lieber nicht in die Angelegenheiten einer Nekromantin einmischen."},{"a":"donovan","t":"Natürlich. Das liegt mir fern. Leb wohl!"},{"a":"donovan","t":"Seltsame Nekromantin ... Sind wir uns schon mal begegnet?"},{"a":"donovan","t":"... Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Exorzismus","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Keine Sorge, Hemma. Ich bin da! Und ich habe Freya mitgebracht!"},{"a":"priest","t":"Hemma, richtig? Bitte entspanne dich. Lass den Exorzismus durch dich fließen ..."},{"a":"hemma","t":"Wir erinnern uns nicht daran, dich um Hilfe gebeten zu haben."},{"a":"hemma","t":"<c4>Haut ab, Rotznasen. Ich gehe nirgendwohin.</c4>"},{"a":"lilu","t":"Aaah! Es übernimmt die Kontrolle! Schnell, Freya!"},{"a":"priest","t":"Ich ... kann nicht! Etwas blockiert meine Gebete ..."},{"a":"hemma","t":"Ja, wir. Hör auf damit."},{"a":"priest","t":"Hast du ... diesen bösartigen Geist freiwillig aufgenommen?!"},{"a":"hemma","t":"Mit der Zeit ist er ein wenig verrückt geworden, das gebe ich zu."},{"a":"hemma","t":"<c4>Ich bin hier das Opfer! Lasst mich raus!</c4>"},{"a":"hemma","t":"Uh. Eher frech als bösartig, das kann ich euch versichern."},{"a":"hemma","t":"Das geht euch nichts an. Bitte misch dich nicht ein, Freya."},{"a":"priest","t":"Diese Nekromanten ... immer spielen sie mit Kräften, die sie nicht verstehen!"},{"a":"lilu","t":"Schon okay, Freya! Ich bin sicher, sie weiß, was sie tut!"},{"a":"lilu","t":"... Stimmt’s?"}]},{"id":"hemma_05","i":5,"title":"Frau mit zwei Geistern","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"hemma","t":"<c4>Die Katze scheint wieder aus dem Sack zu sein. Bereit, die Stadt zu verlassen?</c4>"},{"a":"hemma","t":"Das war DEINE Schuld. Wenn du still sein könntest, wären die Dinge viel einfacher."},{"a":"hemma","t":"Wie dem auch sei, wir werden noch nicht gehen. Diese Stadt wirkt vielversprechend."},{"a":"hemma","t":"<c4>Na schön. Wie wäre es dann, wenn du mich wenigstens mal rauslässt?</c4>"},{"a":"hemma","t":"S-Sicher nicht. Es ist jetzt schon so schwierig, dich unter Kontrolle zu halten."},{"a":"hemma","t":"<c4>Lass-mich-raus-lass-mich-raus-lass-mich-raus.</c4>"},{"a":"hemma","t":"Ich mache das nur für dich, Claud."},{"a":"hemma","t":"... Bitte vergiss das nicht."}]},{"id":"hemma_06","i":6,"title":"Vermächtnis der Lügen","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn!"},{"a":"hemma","t":"Ja?"},{"a":"lilu","t":"Ich wusste es! Hemma ist nicht dein richtiger Name! Du bist das Monster, Fairlyn!"},{"a":"hemma","t":"Du meine Güte. Was für eine verschlagene, kleine Gaunerin."},{"a":"hemma","t":"Es ist wahr. Du hast wohl deine Hausaufgaben gemacht."},{"a":"hemma","t":"Vielleicht hast du auch von Ariel der Verrückten gehört? Oder Astrid der Gefallenen?"},{"a":"lilu","t":"Ich habe von ihnen gelesen ... Aber sie sind vor Jahrzehnten verschwunden! Es kann doch nicht ..."},{"a":"hemma","t":"Das sind alles wir, natürlich. Leider werden wir überall verfolgt, weswegen wir uns solcher Namen entledigen müssen ..."},{"a":"lilu","t":"Du bist ein Monster! Jemand muss dich aufhalten!"},{"a":"hemma","t":"Und wie willst du das machen? Hemma ist unschuldig. Wer würde so einer wilden Erzählung Glauben schenken?"},{"a":"hemma","t":"Es sei denn, du willst mich allein aufhalten ..."},{"a":"lilu","t":"Hmpf!"}]},{"id":"hemma_07","i":7,"title":"Seelenverbindung","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"hemma","t":"Na, schleichst du immer noch hier herum?"},{"a":"lilu","t":"Ich behalte dich im Auge. Dich und deine verdächtigen Monologe ..."},{"a":"hemma","t":"Oh, ja. Das ist Claud, unser Ehemann. Ihm ging es auch schon mal besser."},{"a":"hemma","t":"<c4>Ich will hier raus!</c4>"},{"a":"lilu","t":"Was ist ihm zugestoßen?"},{"a":"hemma","t":"Ein schrecklicher Nekromantie-Unfall. Ein dummer Fehler hat ihn an den Rand des Todes gebracht."},{"a":"hemma","t":"In Anbetracht unserer Sünden auf dieser Erde ist das Jenseits für uns Nekromanten eine schreckliche Vorstellung ..."},{"a":"hemma","t":"Wir konnten seinen Körper nicht retten, und so taten wir, was wir konnten ... und retteten seine Seele."},{"a":"lilu","t":"Eine Seelenverbindung? Für diesen Zauberspruch braucht man jahrelange Forschung, um ein geeignetes Gefäß herzustellen ..."},{"a":"hemma","t":"Stimmt. Aber wegen der Umstände mussten wir improvisieren."},{"a":"lilu","t":"Improvisieren? Du willst damit doch nicht sagen ... du hättest Clauds Seele an dich selbst gebunden?!"},{"a":"lilu","t":"Ein Körper kann keine zwei Seelen ertragen! Das würde ..."},{"a":"hemma","t":"Unsägliche Schmerzen bedeuten. Wahnsinn. Schlimmer noch, als du es dir vorstellen kannst."},{"a":"lilu","t":"Hemma ... Warum ...? Wie ...?"},{"a":"hemma","t":"Es ist ganz einfach, kleine Lilu. Versagen ... ist keine Option."}]},{"id":"hemma_08","i":8,"title":"Die Beute eines Jahrhunderts","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Zu mächtig für einen Exorzismus ... vielleicht könnte man die Seele an etwas anderes binden ...?"},{"a":"hemma","t":"Wie kooperativ du bist. Hast du doch noch ein Interesse an Nekromantie entwickelt?"},{"a":"lilu","t":"Nein! Ich hasse dich und alles, was du getan hast!"},{"a":"lilu","t":"So wie ich das sehe: Wenn dieser Claud entfesselt wird, bedeutet das für alle hier großen Ärger."},{"a":"lilu","t":"Ich helfe dir, dieses Problem zu beseitigen, aber mehr nicht!"},{"a":"hemma","t":"Eine edle Einstellung. Aber wie soll ein einfaches Kind mir helfen können?"},{"a":"lilu","t":"Ein geeignetes Gefäß herzustellen, würde Jahrzehnte der Forschung und Unmengen an Material erfordern ..."},{"a":"hemma","t":"Das sollte kein Problem sein. Sieh zu."},{"a":"lilu","t":"...! Wie konntest du an all das kommen ...? Selbst schwarze Diamanten!"},{"a":"hemma","t":"Die letzten Jahrzehnte waren nicht verschwendet. Unsere Zeit wird knapp."},{"a":"hemma","t":"Es fehlt nur noch der richtige Ort, um das Ritual durchzuführen. Wir befürchten, dass so ein Ort vielleicht nicht existiert."},{"a":"lilu","t":"Ja. Die Seele muss sich spirituell mit dem Gebiet verbunden fühlen, sonst schlägt die Verbindung fehl."},{"a":"hemma","t":"<c4>Oder du könntest den guten, alten Claud Favius einfach gehen lassen! Er wird viele Freunde finden!</c4>"},{"a":"lilu","t":"Moment ... Hast du gerade Favius gesagt?"}]},{"id":"hemma_09","i":9,"title":"Das Spukschloss","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"hemma","t":"Was für ein entzückend gruseliger Ort."},{"a":"lilu","t":"Es ist ein schrecklicher Ort. Niemand bei Verstand sollte hierherkommen."},{"a":"lilu","t":"Aber am wichtigsten: Meiner Forschung nach ..."},{"a":"lilu","t":"... hat hier vor Jahrhunderten ein irrer König der Favius-Familie geherrscht."},{"a":"lilu","t":"Vielleicht ist Claud ein entfernter Verwandter? Hoffentlich hatte er nichts mit dem Untergang dieses Königreichs zu tun ..."},{"a":"hemma","t":"Wir können es spüren. Wir sind mit diesem Ort verbunden. Das ist es."},{"a":"hemma","t":"Wir stehen in deiner Schuld, Lilu. Aber jetzt musst du uns allein lassen."},{"a":"lilu","t":"Hemma ... Viel Glück."}]},{"id":"hemma_10","i":10,"title":"Bis dass der Tod uns scheidet","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"hemma","t":"Ein dunkler, unheimlicher und abgeschiedener Ort, der nekromantische Energie ausstrahlt ..."},{"a":"hemma","t":"Wie lange haben wir nach solch einem Ort gesucht?"},{"a":"hemma","t":"Jetzt brauchen wir ein geeignetes Gefäß ..."},{"a":"hemma","t":"Wir müssen nicht darüber reden. Wir wissen genau, was du willst."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Die Rüstung des irren Königs höchstpersönlich, die für immer an diesen Ort gebunden ist."},{"a":"hemma","t":"<c1>Seelenverbindung!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Uh ... Wir fühlen ... oder ich ...?"},{"a":"hemma","t":"Ich hatte dieses Gefühl der Einsamkeit vergessen ..."},{"a":"hemma","t":"Ich habe eine Ewigkeit lang gelitten, um dich zu retten, mein Lieber. Weil ich weiß, dass du genau dasselbe getan hättest."},{"a":"hemma","t":"Es werden bestimmt tapfere Abenteurer kommen. Bekämpfe sie und heile deine geplagte Existenz durch Blutvergießen."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Leb wohl, mein Liebster. Aber nur im Tod sind wir wirklich getrennt."}]},{"id":"hemma_epilogue","i":11,"title":"Epilog","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>NARREN! IHR WAGT ES, MEIN LAND ZU BETRETEN?</c4>"},{"a":"sia","t":"Was für ein lästiger Gegner!"},{"a":"Castle_Boss","t":"<c4>MUAHAHA! KÜMMERLICHE STERBLICHE!</c4>"},{"a":"argon","t":"Fräulein Sia! Rudo! Wir müssen uns zurückziehen!"},{"a":"rudo","t":"Niemals! Ich gebe keinen Zentimeter nach!"},{"a":"yami","t":"Ich habe einen Ausgang gefunden. Schnell!"},{"a":"rudo","t":"Pah! Ich werde wiederkommen, du große Blechdose! Hast du mich verstanden?"},{"a":"Castle_Boss","t":"<c4>KOMM WIEDER, WENN DU MIR EINEN RICHTIGEN KAMPF BIETEN KANNST!</c4>"},{"a":"Castle_Boss","t":"<c4>SAGT EUREN GRÖSSTEN HELDEN, DASS DER TYRANNENKÖNIG WARTET!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Altkluger Lehrling","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Nun, Pollux? Was hältst du von diesem neuen Zauberspruch? Perfekt, nicht wahr?"},{"a":"lilu","t":"Ja, diesmal werden wir es bestimmt schaffen!"},{"a":"herbalist","t":"Guten Morgen, Lilu. Bist du wegen der wöchentlichen Lieferung Lebendwurzeln hier?"},{"a":"lilu","t":"Ja, danke, Maribel!"},{"a":"herbalist","t":"Diese Woche hast du wirklich jede Menge bestellt! Was stellt dein Meister denn mit so vielen an?"},{"a":"lilu","t":"Um ehrlich zu sein, ist etwa die Hälfte für mich. Ich büffele gerade so richtig!"},{"a":"herbalist","t":"Oh, was denn?"},{"a":"lilu","t":"Heilzaubersprüche! Letzte Woche habe ich fast nur Schnitte und Prellungen im Trainingsraum behandelt!"},{"a":"herbalist","t":"Oh ja, die Helden haben dich sicher gerne in ihrer Nähe."},{"a":"herbalist","t":"Und Argon auch!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"I-Ich muss los! Danke!"}]},{"id":"lilu_02","i":2,"title":"Grimmige Nachrichten","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Bitteschön, Meister Grimar. Die Lebendwurzeln für diese Woche."},{"a":"wizard","t":"Danke, Lola. Hier ist deine heutige Hausaufgabe."},{"a":"lilu","t":"Oh! Ein Zauberbuch! Geht es darin um Heilung?!"},{"a":"lilu","t":"„Das Handbuch der Verwünschungen für Schurken\" ...?"},{"a":"lilu","t":"Das Buch ist mir viel zu hoch! Da gibt es sogar ein ganzes Kapitel über Flüche!"},{"a":"wizard","t":"... Flüche?"},{"a":"wizard","t":"Hmm ... Flüche ...?"},{"a":"lilu","t":"Meister?"},{"a":"wizard","t":"Auf den Tag genau vor 35 Jahren ... habe ich ...!"},{"a":"lilu","t":"Meister Grimar?!"},{"a":"wizard","t":"Ich weiß es nicht mehr. Und wer bist du denn?"},{"a":"lilu","t":"Ich bin Euer Lehrling Lilu. Oder Lola, manchmal ..."},{"a":"lilu","t":"Oh, nun ja, egal. Ich werde mir dieses Buch durchlesen. Danke, Grim."}]},{"id":"lilu_03","i":3,"title":"Benebelter Verstand","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"... Man füge eine Prise silbernen Staub hinzu und ... fertig!"},{"a":"lilu","t":"Sieh nur, wie das leuchtet! Nicht schlecht, was, Pollux?"},{"a":"lilu","t":"Wenn „Das Handbuch der Verwünschungen für Schurken“ recht hat, sollte dieser Trank ..."},{"a":"wizard","t":"Lola, was ist das für ein Krawall? Ich versuche zu schlafen!"},{"a":"lilu","t":"Meister Grimar! Mithilfe Eures Buchs konnte ich einen sehr fortgeschrittenen Trank brauen! Er sollte ..."},{"a":"wizard","t":"Du hast was?!"},{"a":"wizard","t":"Na los, gib schon her! Dann wollen wir doch mal kosten."},{"a":"wizard","t":"..."},{"a":"lilu","t":"Meister Grimar?"},{"a":"wizard","t":"Lilu! L-la-lass m-mich f-f-frei! Be-befreie mich von diesem tölpelhaften, schwachsinnigen V-Ver-Verstand!"},{"a":"lilu","t":"M-Meister Grimar! Geht es Euch gut?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Hicks* Vielleicht etwas zu fruchtig!"},{"a":"wizard","t":"Nicht schlecht, Lola. Und jetzt marsch zurück zu deinen häuslichen Pflichten."},{"a":"lilu","t":"... Das war NICHT normal."}]},{"id":"lilu_a","i":3,"title":"Ewiger Hamsterer","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"lilu","t":"Grimar, du hast mir nicht erzählt, dass du ein zweites <c1>Sammlungsbuch</c1> hast!"},{"a":"wizard","t":"<c1>Sammlungsbuch</c1> ...? Das sagt mir was ..."},{"a":"lilu","t":"Wow! Das ist voller Infos! <c1>Damokles</c1> ... <c1>Bernsteinzitadelle</c1> ..."},{"a":"lilu","t":"<c1>Grimars Zauberstab</c1> ...? Hast du den benannt?"},{"a":"lilu","t":"Es sind so viele Seiten! Du musst ein richtiger Sammler gewesen sein!"},{"a":"sundragon","t":"Das war er auch!"},{"a":"wizard","t":"Bist du das, Sondra, alter Freund?"},{"a":"lilu","t":"Wow! Kennt ihr zwei euch etwa?"},{"a":"sundragon","t":"In der Tat. Der junge Grimar war ganz verrückt nach seinem Sammlungsbuch."},{"a":"sundragon","t":"Ich glaube, es hat ihm einen ehrwürdigen Titel unter seinen Mitmenschen eingebracht ... Nerd, glaube ich."},{"a":"lilu","t":"Autsch ..."},{"a":"sundragon","t":"Ich bin ihm bei seiner Suche nach seltenen Gegenständen begegnet und dann haben wir gemeinsam den <c1>Fusionskessel</c1> erschaffen."},{"a":"sundragon","t":"Er hat tage- und nächtelang Hunderte Gegenstände fusioniert ... und während des Vollmonds sogar noch mehr!"},{"a":"lilu","t":"Doch trotz all dieser Anstrengungen ... ist seine Sammlung immer noch unvollständig!"},{"a":"lilu","t":"Ich schwöre, ich werde dich heilen, Meister Grimar! Du musst dein Lebenswerk vollenden!"},{"a":"sundragon","t":"Für euch Menschen ist die Zeit fürwahr grausam. Ich wünsche dir viel Glück bei dieser Aufgabe, Kleine."}]},{"id":"lilu_04","i":4,"title":"Das Ende der Blutlinie","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Irgendwas stimmt nicht mit Meister Grimar ..."},{"a":"lilu","t":"Seine Stimme ... sie hat geklungen, als würde jemand anderes durch ihn sprechen!"},{"a":"lilu","t":"Vielleicht haben wir es hier ja mit einem komplexen Transmutationszauber zu tun?"},{"a":"lilu","t":"Oder vielleicht sogar ..."},{"a":"leather","t":"Hey, Lilu! Beim Fest des Königs ist etwas vorgefallen!"},{"a":"lilu","t":"Tamas? Was ist los?"},{"a":"leather","t":"Irgendetwas mit einem Eindringling im Schloss, Mann. Ziemlich gruselig!"},{"a":"lilu","t":"Ein Eindringling ...! Oh nein, heute ist Argons erster Tag als Ritter!"},{"a":"lilu","t":"Danke, Tamas, ich muss los!"},{"a":"lilu","t":"Oh nein ...! Was geht hier vor?!"},{"a":"lilu","t":"Argon, wo bist du?!"},{"a":"king","t":"Aaah ..."},{"a":"lilu","t":"KÖNIG REINHOLD?! Geht es Euch gut?!"},{"a":"king","t":"Aah ... Mein geschätztes Leben ... es schwindet ..."},{"a":"lilu","t":"Das ist nicht gut ...!"},{"a":"lilu","t":"Konzentriere dich, Lilu! Denke an deine Weisenausbildung!"},{"a":"lilu","t":"König Reinhold! Haltet still! <c1>Heilung</c1>!"},{"a":"king","t":"Es hat keinen Zweck ... Bitte ... Bewahrt meinen schönen Leichnam ..."},{"a":"lilu","t":"Keine Wirkung ..."},{"a":"lilu","t":"Oh nein ... könnte es ... Gift sein?"},{"a":"lilu","t":"... Wie bei meinen Eltern ...! Dieses Mal werde ich nicht versagen! Ich kann nicht!"},{"a":"lilu","t":"<c1>Mächtige Giftheilung!</c1>"},{"a":"king","t":"... Aaah ... Ha?"},{"a":"lilu","t":"König Reinhold! Wie fühlt Ihr Euch?"},{"a":"lilu","t":"Einen Moment ... Dieser Becher hat Euch vor dem Shuriken geschützt! Ihr wurdet gar nicht verletzt!"},{"a":"king","t":"Oh! Tatsächlich? Nun, ich mag ein wenig überreagiert haben."},{"a":"king","t":"Der Tod eines Monarchen ist immerhin eine dramatische Angelegenheit."},{"a":"lilu","t":"Ah! Reinhold!"}]},{"id":"lilu_05","i":5,"title":"Giftmischer","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Uh ... Das war knapp ... irgendwie."},{"a":"lilu","t":"Wenn Reinhold wirklich vergiftet worden wäre ... glaube ich nicht, dass ich ihn retten hätte können."},{"a":"lilu","t":"Ich muss mich auf meine Stärken besinnen. Um sicherzustellen, dass niemand so einen Verlust erleidet wie ich ..."},{"a":"lilu","t":"Fräulein Sia!"},{"a":"sia","t":"Ah, die Heldin des Augenblicks! Ein Ritter wurde ausgesandt, um sich um den Eindringling zu kümmern. Du kannst beruhigt sein."},{"a":"lilu","t":"(Ein Ritter? Viel Glück, Argon!)"},{"a":"sia","t":"Danke, dass du ... unseren König gerettet hast, trotz der Umstände."},{"a":"lilu","t":"Nicht der Rede wert! Aber wenn es noch mal passieren würde, weiß ich nicht, ob ich eine große Hilfe wäre ..."},{"a":"lilu","t":"Fräulein Sia, weißt du etwas über Gifte?"},{"a":"sia","t":"Natürlich. Der Gifthut, auch als Wolfswurz bekannt, ist ein schrecklich effizientes Mittel."},{"a":"sia","t":"Aber mein persönlicher Favorit ist Rizin. Leise, tödlich und leicht zu beschaffen ..."},{"a":"lilu","t":"Ähm ... Und wenn man ihnen entgegenwirken will?"},{"a":"sia","t":"Oh. Darüber habe ich nie viel nachgedacht."},{"a":"lilu","t":"Vergiss, dass ich gefragt habe."}]},{"id":"lilu_06","i":6,"title":"Meister und Schülerin","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Ich bin wieder da, Meister Grimar!"},{"a":"wizard","t":"Ah, willkommen zurück, Lola."},{"a":"lilu","t":"Ist das zu fassen? Der König wurde beinahe ermordet!"},{"a":"wizard","t":"Ist das so ..."},{"a":"lilu","t":"Eine Assassinin ist plötzlich aufgetaucht und hat ihn mit einem Shuriken angegriffen!"},{"a":"lilu","t":"Und dann bin ich ihm zu Hilfe geeilt, als er sterbend am Boden lag ...!"},{"a":"wizard","t":"Ähm ... Wer bist du noch mal?"},{"a":"lilu","t":"Ach ja. Die Krankheit ... Ich muss weiterarbeiten!"},{"a":"lilu","t":"Es könnte auch ein Gift sein ..."},{"a":"lilu","t":"Mal sehen ... Grimar ist richtig alt ..."},{"a":"lilu","t":"Was meinst du, Pollux?"},{"a":"lilu","t":"Ja, wir sollten in der Stadt herumfragen!"},{"a":"lilu","t":"Vielleicht können sich einige der älteren Stadtbewohner daran erinnern, wie sich der junge Grimar benommen hat ..."}]},{"id":"lilu_07","i":7,"title":"Wissen der Ahnen","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Meister Theodor!"},{"a":"master","t":"Wenn das nicht Lilu ist! Wie kann ich dir heute helfen?"},{"a":"lilu","t":"Ich habe mich gefragt, ob du mir von Grimar erzählen kannst, als er noch jung war ..."},{"a":"lilu","t":"Da du ja, äh ... alt bist und so."},{"a":"master","t":"Hohoho! Natürlich, natürlich."},{"a":"master","t":"Der alte Grimar war schon immer ein ziemlicher ... Exzentriker."},{"a":"master","t":"Aber damals, als ich ein kleines Bürschchen war, habe ich ihn viel klüger in Erinnerung. Er war mir sogar im Schach ebenbürtig."},{"a":"master","t":"Aber seit dem Ausflug in die Chronos-Ruinen ... Irgendwas stimmte nicht mehr mit ihm, jetzt, wo ich darüber nachdenke."},{"a":"lilu","t":"Die Chronos-Ruinen! Was für ein gefährlicher Ort!"},{"a":"lilu","t":"Eine gesamte Zivilisation wurde bei der Erforschung von Zeitmagie ausgelöscht ..."},{"a":"lilu","t":"Dieser Ort ist voller magischer Anomalien! Was hatte sich Grimar denn von solch einem Ort versprochen?"},{"a":"lilu","t":"Du hast recht, Pollux, das ist unser einziger Hinweis. Wir müssen dem nachgehen!"},{"a":"lilu","t":"Wir brauchen aber Geleitschutz ... Sollen wir Argon bitten ...?"},{"a":"lilu","t":"Nein! Was, wenn ein Zeitwirbel ihn plötzlich in einen alten Mann verwandelt? Oder in einen wie Grimar ..."},{"a":"lilu","t":"Mir fällt nur eine andere Person ein, die uns helfen könnte ..."},{"a":"lilu","t":"Das wird nicht einfach, Pollux! Aber wir müssen es probieren!"},{"a":"lilu","t":"Danke, Theodor! Du warst mir eine große Hilfe!"},{"a":"master","t":"Kein Problem, Lilu! Bis demnächst."},{"a":"master","t":"..."},{"a":"master","t":"Wie clever ist eigentlich diese Eule ...?"}]},{"id":"lilu_08","i":8,"title":"Gemeinsame Sache","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Rudo, bitte! Geh nicht fort, ich muss mit dir sprechen!"},{"a":"rudo","t":"Zisch ab, Kind, ich will es nicht hören."},{"a":"rudo","t":"Du kannst mit deiner Eule woanders spielen."},{"a":"lilu","t":"Ich weiß, du magst keine Hexer ... aber ich brauche wirklich deine Hilfe!"},{"a":"lilu","t":"Ich muss tief in die Chronos-Ruinen vordringen und ich kann nicht allein gehen! "},{"a":"rudo","t":"Warum fragst du nicht diesen Jungen Argon, deinen Ritter in strahlender Rüstung?"},{"a":"lilu","t":"Er ist ... äh, derzeit mit etwas anderem beschäftigt ..."},{"a":"lilu","t":"Vermutlich brauche ich dich dann nicht zu fragen ..."},{"a":"rudo","t":"Richtig erkannt, Kind."},{"a":"tavern","t":"Wie schade."},{"a":"tavern","t":"Ich habe gehört, dass der Zyklopenherr in den Chronos-Ruinen im Einzelkampf noch nie besiegt wurde ..."},{"a":"tavern","t":"Nur ein außergewöhnlicher Krieger kann Lilu durch diese Ruinen geleiten!"},{"a":"rudo","t":"Noch nie besiegt, sagst du?"},{"a":"rudo","t":"Na schön. Du hast mich überzeugt. Wie viel Prügel darf ich austeilen?"},{"a":"lilu","t":"Sicher sehr viel!"},{"a":"lilu","t":"Weißt du, ich muss die Quelle des Zeitstroms finden, der aus den verschiedenen Kristallen strömt, und ihn isolieren ..."},{"a":"rudo","t":"Komm zum Teil, bei dem es ums Zerschmettern geht."},{"a":"lilu","t":"... Es gibt Monster und magische Kristalle zu zerschmettern."},{"a":"rudo","t":"Na gut, ich bin dabei. Du schuldest mir was, Kind."},{"a":"lilu","t":"Das ist fantastisch! Vielen Dank, Rudo!"},{"a":"rudo","t":"Spar dir das für nach unserer Reise, Kind. Das wird kein Zuckerschlecken."},{"a":"lilu","t":"Ich werde deine Wunden heilen, wenn sich dir zu viele Monster stellen!"},{"a":"rudo","t":"Hmpf. Unwahrscheinlich."},{"a":"lilu","t":"Und danke, Naja!"},{"a":"tavern","t":"Kein Problem, Kleine."}]},{"id":"lilu_09","i":9,"title":"Spiegelwelt","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Ich werde den Zyklopen ablenken! Zieht weiter!"},{"a":"rudo","t":"Komm schon, Fettklops! Ich hab was für dich!"},{"a":"lilu","t":"Verstanden! Viel Glück!"},{"a":"lilu","t":"Das ist ... die Kammer der Zeit. Und meinen Forschungen zufolge ..."},{"a":"lilu","t":"Sollte dieses Becken mit einer zersplitterten Zeitachse verbunden sein!"},{"a":"lilu","t":"Ein Paralleluniversum, in dem die Chronosstadt noch floriert ..."},{"a":"lilu","t":"Sieh mal, Pollux! Wenn du in das Wasser blickst ... kannst du etwas erkennen!"},{"a":"lilu","t":"Es scheint, die Leute von Chronos leben ganz normal irgendwo da draußen ..."},{"a":"lilu","t":"Hey ... Wirkt es nicht so, als würde uns dieser Typ zuwinken?"},{"a":"lilu","t":"Er sieht ganz so aus wie ... Grimar?!"}]},{"id":"lilu_10a","i":10,"title":"Fluch der Immerjahre","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Grimar! Trink das!"},{"a":"wizard","t":"Hm? Irgendwie kommt mir das ... bekannt vor."},{"a":"lilu","t":"Es ist ein besonderes Getränk aus Chronoswasser ..."},{"a":"wizard","t":"... Stabilisiert und zweifach mit Schicksalsfäden behandelt ...?"},{"a":"lilu","t":"... und mit destilliertem Ektoplasma in materielle Form gebracht."},{"a":"wizard","t":"Mit einem Hauch Tiefenkoralle für den Geschmack!"},{"a":"wizard","t":"Großartig gemacht, Lilu. Kein Meister könnte stolzer sein."},{"a":"lilu","t":"G-Grimar ... Du bist wieder der Alte! Es hat funktioniert!"},{"a":"wizard","t":"Was für ein seltsames Erlebnis ... Es ist so, als hätte sich ein Nebel von meinem Geist verflüchtigt ..."},{"a":"lilu","t":"Ich habe eine ungefähre Ahnung, wie der Trank funktioniert, aber ... etwas ergibt keinen Sinn."},{"a":"lilu","t":"Wir haben dich im Becken gesehen! In der zersplitterten Zeitachse!"},{"a":"wizard","t":"Hoho! Ist das so? Dazu habe ich eine Theorie ..."},{"a":"wizard","t":"Pollux, mein Lieber. Würdest du bitte den alten Owen holen? Ich glaube, es gibt einiges zu erklären ..."}]},{"id":"lilu_10b","i":11,"title":"Zeitspaltung-Theorie","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"elderowen","t":"Du meine Güte, alter Freund, was für eine Geschichte!"},{"a":"lilu","t":"Ich kann es selbst kaum glauben ... Grimar ist ein Überlebender aus der Chronosstadt?"},{"a":"wizard","t":"Als der Zeitzauber verrücktspielte, stürzte die gesamte Stadt in eine andere Zeitachse."},{"a":"elderowen","t":"Ich kann mich daran erinnern, als wäre es gestern gewesen. Eine ganze Stadt ist einfach verschwunden!"},{"a":"elderowen","t":"Das Einzige, was wir in den Ruinen fanden, war ein einsames, umherirrendes Kind ..."},{"a":"lilu","t":"Grimar, oder? Ich kann mir euch beide nur schwer als Kinder vorstellen ..."},{"a":"elderowen","t":"Hoho! Wir sind richtig dicke Freunde geworden, oder?"},{"a":"wizard","t":"Ja. Ich habe die Ausbildung zum Zauberer gemacht, um dieses seltsame Ereignis untersuchen zu können."},{"a":"wizard","t":"Wenn das, was Lilu gesehen hat, wahr ist, denke ich, dass noch ein Grimar existiert."},{"a":"lilu","t":"Den anderen Grimar, den wir gesehen haben ... dich gibt es in der anderen Zeitachse?!"},{"a":"wizard","t":"So scheint es. Zuerst gab es keine Konsequenzen, aber ..."},{"a":"wizard","t":"Während beide Grimars heranwuchsen, begannen unsere Lebenserfahrungen und Persönlichkeiten voneinander abzuweichen."},{"a":"lilu","t":"Und das wachsende magische Paradoxon beschäftigte deinen Verstand ..."},{"a":"lilu","t":"Ich verstehe! Einen Trank aus den Chronos-Ruinen zu trinken, muss dich mit dieser anderen Zeitachse verbinden!"},{"a":"wizard","t":"Das ist meine Theorie. Ich bin sicher, der andere Grimar spürt das auch."},{"a":"lilu","t":"Mann ... Das ist ganz schön viel. Ich glaube, ich muss mindestens eine Nacht darüber schlafen ... Kommst du, Pollux?"},{"a":"elderowen","t":"Und was uns angeht, alter Grim, ich denke, wir haben einiges nachzuholen!"},{"a":"wizard","t":"Schließ nicht von dir auf mich, alter Kauz! Ich habe mich nie jünger gefühlt!"}]},{"id":"lilu_epilogue","i":12,"title":"Epilog","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Hey Grimar! Hier ist ein neues Rezept. Es sollte ein wenig länger anhalten!"},{"a":"wizard","t":"Eine beachtliche Verbesserung. Deine Eltern wären stolz."},{"a":"lilu","t":"... Hätte ich Alchemie nur ein wenig früher studiert ..."},{"a":"wizard","t":"So geht es mir auch. Wenn ich Herr meiner Funktionen wäre, vielleicht ..."},{"a":"lilu","t":"... Schon okay. Ich habe beschlossen, mich auf die Zukunft zu konzentrieren. Um besser zu werden und andere vor diesem Schicksal zu bewahren."},{"a":"lilu","t":"... Ich bin sicher, das hätten meine Eltern gewollt."},{"a":"wizard","t":"Du bist so groß geworden ... Ich erkenne dich kaum wieder."},{"a":"wizard","t":"Ähm ... Wer bist du noch mal?"},{"a":"lilu","t":"Oh nein! Die Wirkung lässt bereits nach! Ich sollte lieber ..."},{"a":"wizard","t":"Hohoho! Nur ein Scherz. Ich habe ein gutes Gefühl dabei."},{"a":"wizard","t":"Also dann, mein Kopf ist frei. Wollen wir ein wenig Magie lernen?"},{"a":"wizard","t":"Der Meister hat noch ein paar Tricks auf Lager!"},{"a":"lilu","t":"Oh! Wie wäre es mit Polymorph? Darauf freue ich mich schon!"}]}]},{"id":"malady","name":"Malady","chapters":[{"id":"malady_01","i":1,"title":"In Stein gehauen","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Quest erledigt! Vermisste Kinder: gefunden und gerettet!"},{"a":"argon","t":"Die Chronos-Ruinen sind wirklich kein Spielplatz."},{"a":"argon","t":"Ich sollte wohl auch besser den Rückweg antreten!"},{"a":"malady","t":"... Ich hoffe, die fiesen Nervtöter-Kobolde lassen mich heute in Ruhe."},{"a":"argon","t":"Hallo, junge Dame! Hast du dich auch verirrt?"},{"a":"malady","t":"Nein ... Komm nicht näher!"},{"a":"argon","t":"Hm?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Wenn du in meine Augen blickst, wirst du für immer zu Stein. Das ist der Fluch der Medusa."},{"a":"malady","t":"Obwohl ... du so nett gewirkt hast."},{"a":"malady","t":"... Tut mir leid."}]},{"id":"malady_02","i":2,"title":"Marmormann","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"*Uff* ... Ältester ... Owen ..."},{"a":"elderowen","t":"Lilu! Was zerrst du da für eine Statue herum?!"},{"a":"elderowen","t":"Eine Statue von ... Argon?!"},{"a":"lilu","t":"Schnauf ... schnauf ... Das IST Argon!"},{"a":"elderowen","t":"Du meine Güte. Wurde er versteinert?"},{"a":"lilu","t":"Ich denke schon. Ich habe ihn so in den Chronos-Ruinen gefunden."},{"a":"lilu","t":"Zum Glück hat Rudo mir beim Tragen geholfen!"},{"a":"elderowen","t":"Ein ziemlicher Schlamassel. Kannst du ihn heilen?"},{"a":"lilu","t":"Wahrscheinlich! Aber die Zutaten sind selten, das wird also nicht einfach."},{"a":"lilu","t":"Ich trommle die Stadtbewohner zusammen und hole auch den Ladenbesitzer! Pass du einstweilen auf Argon auf!"},{"a":"elderowen","t":"Natürlich. Ich hoffe, du hast nichts dagegen, eine Zeit lang als Gartendekoration zu dienen, Junge."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Oh, verfluchte Tauben! Kusch!"}]},{"id":"malady_03","i":3,"title":"Auge um Auge","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"... Diese feste Ranke sollte alt genug sein. Es gibt nicht mehr allzu viele davon."},{"a":"lilu","t":"Als Nächstes ... Blut der Medusa. Das wird nicht einfach."},{"a":"malady","t":"Ähm ..."},{"a":"lilu","t":"Huch! Monster!"},{"a":"malady","t":"... Bist du eine Freundin des Menschen von vorhin?"},{"a":"lilu","t":"Argon? Moment, warst DU das etwa?"},{"a":"lilu","t":"Ah, das erleichtert die Sache SEHR. Zufälligerweise bin ich gerade auf der Suche nach Medusa-Blut."},{"a":"malady","t":"Nein, bitte! Ich tue keinem was."},{"a":"lilu","t":"Ach ja? Du hast ihn zu Stein verwandelt!"},{"a":"malady","t":"... Es tut mir leid. Ich hatte Angst und unsere Blicke haben sich getroffen."},{"a":"malady","t":"Ich wusste nicht, wie ich reagieren sollte ... Niemand war je freundlich zu mir."},{"a":"lilu","t":"... Puh, du hattest es wohl schwer."},{"a":"malady","t":"Wenn du Blut brauchst ... kann ich es dir geben."},{"a":"malady","t":"Aber im Gegenzug ... nimm mich bitte mit. Ich möchte mich bei ihm entschuldigen."},{"a":"lilu","t":"... Na gut. Es gefällt mir zwar nicht, aber wenn ich zu Stein verwandelt würde, glaube ich nicht, dass Donovan uns retten würde."},{"a":"lilu","t":"Ich behalte dich im Blick. Aber wehe, dein Blick trifft mich!"},{"a":"malady","t":"... Natürlich. Danke."}]},{"id":"malady_04","i":4,"title":"Von Stein zu Fleisch zu Stein","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Fertig! Dieser Trank sollte helfen! Plitschplatsch!"},{"a":"argon","t":"... Ah! Strecken tut gut!"},{"a":"argon","t":"Moment, was ist passiert?"},{"a":"lilu","t":"Malady hat dich versehentlich zu Stein verwandelt und möchte sich entschuldigen."},{"a":"malady","t":"H-Hallo. Tut mir leid. Ich wollte nicht ..."},{"a":"argon","t":"War ja nicht schlimm! Ich fühle mich super! ... Vielleicht ein wenig steif."},{"a":"argon","t":"Malady also? Ich bin Argon. Schön, dich kennenzulernen!"},{"a":"argon","t":"Hey, dein Kopftuch ist verrutscht. Lass mich helfen!"},{"a":"lilu","t":"Argon! Nein!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon ... Ich muss ihm erklären, wie das mit Medusen funktioniert ..."},{"a":"malady","t":"Oh nein! Das tut mir so leid!"},{"a":"lilu","t":"Muss es nicht. Das war seine Schuld."},{"a":"malady","t":"I-Ich bin bereit für die nächste Blutspende ..."},{"a":"lilu","t":"Ich kenne mich zwar nicht mit Medusa-Anatomie aus, aber wir sollten ein paar Tage warten, bevor wir dir wieder Blut abnehmen."},{"a":"lilu","t":"Bleib inzwischen hier. Es ist nicht sicher, wenn du in geschwächtem Zustand allein herumspazierst."},{"a":"lilu","t":"Wobei, mit deinen ... Kräften ... Vielleicht fragen wir lieber zuerst mal den Ältesten Owen ..."},{"a":"malady","t":"... Ja."}]},{"id":"malady_05","i":5,"title":"Willkommen zu Hause","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Ältester Owen, wir sind wieder da!"},{"a":"elderowen","t":"Argon wurde also geheilt? Das sind ja erfreuliche Nachrichten!"},{"a":"lilu","t":"Noch nicht ... ganz. Aber ..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"B-bei der Göttin! Eine Medusa, hier?!"},{"a":"lilu","t":"Das ist Malady. Sie hat mir geholfen, Argon zu heilen!"},{"a":"lilu","t":"Sie muss ein paar Tage hierbleiben, damit wir ihn heilen können. Noch mal."},{"a":"elderowen","t":"Ich ... verstehe. Ich spüre, dass du nichts Böses im Schilde führst. Verzeih mir meine Reaktion, Malady."},{"a":"malady","t":"Wegen meines Fluchs ... hassen mich alle, sogar andere Monster. Das bin ich schon gewöhnt."},{"a":"elderowen","t":"Die Tore der Stadt stehen stets allen offen, die zum Wohle aller arbeiten möchten."},{"a":"malady","t":"... Wirklich?"},{"a":"elderowen","t":"Solange du deine Augen verdeckst, sehe ich keine Gefahr."},{"a":"elderowen","t":"Malady ... Ich wünsche dir, dass du hier mehr Glück hast als unter deinesgleichen."},{"a":"malady","t":"Danke ... Man hat mich noch nie irgendwo willkommen geheißen ..."},{"a":"elderowen","t":"Du solltest den Ladenbesitzer bald besuchen. Für junge Leute wie dich gibt es dort immer Arbeit."},{"a":"lilu","t":"Ja! Du solltest uns auf Quests begleiten!"},{"a":"malady","t":"Das mache ich ... Danke, Lilu und Owen."}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Herausragende Landratte","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Joho! Landratten!"},{"a":"polonia","t":"Habt ihr je von waghalsigen Geschichten voller Abenteuer und Kaperfahrten auf hoher See geträumt?"},{"a":"polonia","t":"Ich, Kapitänin Polonia Del Monte, rekrutiere eine Besatzung für mein Schiff!"},{"a":"polonia","t":"Als Tochter des legendären Piraten Baross Del Monte kann ich dir Beute und Abenteuer versprechen!"},{"a":"argon","t":"Kapitänin Polonia, richtig?"},{"a":"polonia","t":"Aye. Bist du interessiert? Ein feiner Kerl wie du ist gern gesehen."},{"a":"argon","t":"K-Kerl?!"},{"a":"argon","t":"Ähm, nicht wirklich! Ich bin Argon, Ritter in der Ausbildung!"},{"a":"argon","t":"Seeräuberei ist illegal, also ... bitte ergib dich und komm ohne Aufstand mit!"},{"a":"polonia","t":"Potz Blitz! Ein verdammter Ritter ..."},{"a":"polonia","t":"Äh, weißt du, ich bin ein legaler Pirat, wie diese ... Landratte Robin Hood."},{"a":"polonia","t":"Ich stehle von den Reichen und gebe den Armen!"},{"a":"argon","t":"Oh! Das klingt ziemlich nobel. Gut, dann mach weiter!"},{"a":"polonia","t":"Puh ...!"},{"a":"tavern","t":"Du hast heute auch kein Glück, hm?"},{"a":"polonia","t":"Arr, das Leben auf hoher See ist hart."}]},{"id":"polonia_02","i":2,"title":"Die Geschichte von Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"tavern","t":"Hast du das Rekrutieren für heute aufgegeben, Polonia?"},{"a":"polonia","t":"Es ist nutzlos. Als Piratenkapitänin bin ich eine Versagerin und nicht würdig, den Namen Del Monte zu tragen ..."},{"a":"tavern","t":"Dieser Baross Del Monte ... war dein Großvater, oder?"},{"a":"polonia","t":"Aye! Eine Legende unter den Legenden! Die heutigen Zeiten sind schwer für uns Piraten ..."},{"a":"polonia","t":"Alle Handelsschiffe haben dieser Tage ausgefallene magische Erkennungswerkzeuge, um uns Freibeuter zu meiden."},{"a":"polonia","t":"Aber gegen Baross hatten sie keine Chance! Magie hin oder her, er griff unentdeckt aus dem Nebel an!"},{"a":"polonia","t":"Er nahm ihnen all ihre Wertgegenstände und hinterließ nur das Echo seines Gelächters als Visitenkarte ..."},{"a":"polonia","t":"Selbst als alle anderen Piraten in den Ruhestand gegangen waren, machte er die Meere noch Jahrzehnte lang unsicher!"},{"a":"tavern","t":"So einem Namen muss man erst mal gerecht werden!"},{"a":"polonia","t":"Aye! Und nach jeder Reise fand er immer die Zeit, seine Enkeltochter zu besuchen und sie mit Abenteuergeschichten zu beglücken ..."},{"a":"polonia","t":"„Hisst die schwarze Fahne! Feuert die Kanonen ab! Alle Männer steuerseits, bereit machen zum Plündern!“"},{"a":"tavern","t":"Steuerseits? Heißt es nicht „steuerbord“?"},{"a":"polonia","t":"Ah! Zum Teufel! Ich bin nur eine Landratte in einem schicken Kostüm, die zu verbissen versucht, wie ein Pirat zu reden."},{"a":"polonia","t":"Und überhaupt: Was ist ein Pirat ohne ein Schiff denn schon?"},{"a":"tavern","t":"Kein Schiff, was? Vielleicht solltest du damit anfangen."},{"a":"polonia","t":"Was?"},{"a":"tavern","t":"Eine Kapitänin ohne Schiff wird nicht so bald eine Crew aufstellen können!"},{"a":"tavern","t":"Aber wenn du ein Schiff brauchst, kenne ich vielleicht den Richtigen für diese Aufgabe."},{"a":"polonia","t":"Wirklich?"},{"a":"polonia","t":"Ich meine: bei der Piratenflagge, danke dir, Schenkenfrau! Kapitänin Polonia schuldet dir etwas!"},{"a":"tavern","t":"Oh, darauf verlasse ich mich, das kannst du mir glauben."}]},{"id":"polonia_03","i":3,"title":"Nächster Halt: Schiffsbauer","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"carpenter","t":"Ich soll ein ganzes Schiff bauen?!"},{"a":"polonia","t":"Aye. Kannst du das?"},{"a":"carpenter","t":"Und ob! Das wird mein Meisterstück! Lass mal die Pläne sehen."},{"a":"carpenter","t":"Hmm ... Die sind ziemlich ausgeklügelt. Was sind das für Kritzeleien?"},{"a":"polonia","t":"Meine Handschrift. Ich kann nicht lesen."},{"a":"carpenter","t":"Ah, tja, das erklärt einiges. Aber trotzdem, das ist mehr als genug."},{"a":"polonia","t":"Joho! Das wird das beste Schiff, das diese Meere seit Baross und Bonaventura je gesehen haben!"},{"a":"carpenter","t":"Da ist aber noch die Frage der Geldmittel. Bist du sicher, dass du dir das leisten kannst?"},{"a":"polonia","t":"Aye, Dublonen sollten kein Problem sein. Baue das Schiff, ich bringe dir deinen Lohn."}]},{"id":"polonia_a","i":3,"title":"Hals- und Beinbruch","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"polonia","t":"Ahoi, schöne Frau, du bist eine Heilerin, nicht wahr?"},{"a":"priest","t":"Oh, ja! Ich bin Freya, Klerikerin dieses Tem..."},{"a":"polonia","t":"Hack mir das Bein ab."},{"a":"priest","t":"Wie bitte?"},{"a":"polonia","t":"Ich will, dass du mir das Bein abhackst!"},{"a":"priest","t":"Du meine Güte, nein! Warum würde jemand das wollen?"},{"a":"polonia","t":"Ich bin eine Piratin! Schon mal einen Piratenkapitän ohne verdammtes Holzbein gesehen?!"},{"a":"polonia","t":"Hack mir einfach das Bein ab und nähe es mit deiner tollen Magie zu!"},{"a":"priest","t":"Auf keinen Fall. Ich habe der Göttin einen Eid geschworen, nie einem Menschen zu schaden."},{"a":"polonia","t":"Argh, nutzlose Landratten! Na schön! Aber du wirst keine meiner Dublonen sehen!"},{"a":"priest","t":"Was für ein seltsames Mädchen ..."}]},{"id":"polonia_04","i":4,"title":"Der Anteil der Kapitänin","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Arr, diese Yetis sind sicher voller Beute! Ich werde im Handumdrehen mein Schiff bezahlen können!"},{"a":"leather","t":"Also, Mann, ich bin hier. Was soll ich tun?"},{"a":"polonia","t":"Nenn mich gefälligst Kapitänin Polonia, Matrose!"},{"a":"leather","t":"Klaro, Kapitänin, Mann. Was kann ich für dich tun?"},{"a":"polonia","t":"Du hast deinen Wagen mitgebracht. Du transportierst die Beute, während ich diese Yetis ausraube."},{"a":"leather","t":"Wow, Kapitänin, Mann, du raubst diese schönen, pelzigen Wesen aus?"},{"a":"polonia","t":"Aye. Aus irgendeinem Grund haben sie Unmengen Wertsachen dabei. Kriegshammer, Compoundbogen und so weiter."},{"a":"leather","t":"Was ist mit den Fellen, Kapitänin, Mann? Kann ich die haben?"},{"a":"polonia","t":"Reiß dich zusammen, Matrose! Piraten plündern, sie töten nicht!"},{"a":"leather","t":"Oh, was für eine Verschwendung."},{"a":"polonia","t":"Gar nicht. Wenn du deine Opfer am Leben lässt, sammeln sie mehr Beute an, die du später rauben kannst. Die Grundlagen der Wirtschaft!"},{"a":"polonia","t":"Und jetzt nimm die Beine in die Hand, wenn du einen Anteil haben willst, Matrose!"},{"a":"leather","t":"Aye, aye, Kapitänin, Mann."}]},{"id":"polonia_05","i":5,"title":"Jungfernfahrt","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"carpenter","t":"Sieh her, mein Lebenswerk und Meisterstück!"},{"a":"polonia","t":"Es ... es ist wunderschön. Du rührst diese alte Seebärin zu Tränen."},{"a":"carpenter","t":"Wirklich, oder? Ich musste ein paar Änderungen vornehmen, etwa wegen deiner eigenartigen Vorliebe für Kanonen auf dem Krähennest ..."},{"a":"carpenter","t":"Aber ich glaube, es ist echt super geworden, findest du nicht auch?"},{"a":"polonia","t":"In der Tat, Matrose. Hier sind deine Dublonen, du hast sie dir verdient."},{"a":"carpenter","t":"Finde ich auch! Aber eins noch: Ich bin zwar ein Zimmermannmeister, aber Tücher und Stoffe übersteigen meine Fähigkeiten."},{"a":"carpenter","t":"Und ohne ein Segel wird dein Schiff den Hafen so bald nicht verlassen!"},{"a":"polonia","t":"Du hast deine Kapitänin schon stolz gemacht, Matrose. Ich habe hier ein Segel."},{"a":"carpenter","t":"Wow! Das nenne ich mal ein Kunstwerk! Und auch magisch! Wo hast du das her?"},{"a":"polonia","t":"Ein Erbstück von meinem Opa Baross. Das Segel, das einst sein Schiff zierte, die Bonaventura!"},{"a":"carpenter","t":"Verstehe! Eine bemerkenswerte Krönung für dieses Schiff!"},{"a":"carpenter","t":"Also dann, Kapitänin Polonia, die „Prächtige Allan“ gehört dir!"},{"a":"polonia","t":"Du hast sie die „Prächtige Allan“ genannt? Warte mal ..."},{"a":"polonia","t":"Diese Gallionsfigur ... bist du das? Und auch noch splitternackt!"},{"a":"carpenter","t":"Haha! Ich kann mir keine schönere Gallionsfigur für so ein perfektes Schiff vorstellen!"}]},{"id":"polonia_b","i":5,"title":"Nimm die Beine in die Hand!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"polonia","t":"Ahoi da drüben."},{"a":"wood","t":"Ja?"},{"a":"polonia","t":"Hack mir das Bein ab."},{"a":"wood","t":"Klar."},{"a":"polonia","t":"Ich sagte ... Warte, du hast kein Problem damit?"},{"a":"wood","t":"Natürlich nicht. Streck dein Bein einfach so aus. Diese alte Axt sollte das schaffen."},{"a":"polonia","t":"Äh, Moment!"},{"a":"wood","t":"Es wird nicht schön, aber du bist doch ein zähes Mädchen, oder?"},{"a":"wood","t":"Vergiss nur nicht, einen guten Druckverband anzulegen. Wir wollen ja nicht, dass du verblutest."},{"a":"polonia","t":"Warte, Matrose! Langsam!"},{"a":"polonia","t":"Ich ... Mein Schiff segelt bald los! Ich muss es erwischen! Man sieht sich, Matrose!"},{"a":"wood","t":"Hah! Menschen! Mit denen wird es nie langweilig."}]},{"id":"polonia_06","i":6,"title":"Vermächtnis auf See","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Mein König, ich bringe düstere Kunde."},{"a":"king","t":"Oh nein! Gibt es in der verschollenen Goldstadt kein Gold mehr?!"},{"a":"sia","t":"So düster nun auch wieder nicht, zum Glück."},{"a":"sia","t":"Aber ich befürchte, dass eine lästige Piratin Eure persönliche Handelsflotte überfallen hat."},{"a":"sia","t":"Die gestohlene Summe wird auf über 100 Billionen Goldstücke geschätzt."},{"a":"king","t":"Bei der Göttin! Was ist mit der hochmodernen, magischen Piratenerkennung meiner Flotte?"},{"a":"sia","t":"Völlig nutzlos, wie es scheint. Wie einst der große Baross entzieht sich auch dieses Schiff unserer besten Magie ..."},{"a":"sia","t":"Euer Gold wird geplündert und dann segelt es wieder davon."},{"a":"king","t":"Absolut barbarisch! Was ist mit der Besatzung?"},{"a":"sia","t":"Verschont, mein König. Solange sie sich nicht wehren."},{"a":"king","t":"Dann ist Gold ein kleiner Preis. Ich werde bäuerliche Mahlzeiten essen, bis mein Vermögen wiederhergestellt ist!"},{"a":"king","t":"Wie lange wird das dauern?"},{"a":"sia","t":"Ungefähr zwei Tage, mein König."},{"a":"king","t":"Wahrlich düstere Zeiten ..."}]},{"id":"polonia_07","i":7,"title":"Landgang","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Joho! Kapitänin Polonia hat den Anker geworfen! Die nächsten paar Runden gehen auf mich!"},{"a":"tavern","t":"Polonia! Oder sollte ich sagen ... Kapitänin Polonia! Ich nehme an, dein „Geschäft“ läuft gut?"},{"a":"polonia","t":"Darauf kannst du wetten, du Landratte! Die See ist reif zum Plündern!"},{"a":"polonia","t":"Wohin mein Schiff auch segelt, sammelt sich der Wind in den Segeln meines Opas wie nichts, was ich je gesehen habe!"},{"a":"tavern","t":"Ich bin sicher, Baross wäre stolz. Wie hast du vor, diese ... unrechtmäßig erworbenen Güter auszugeben?"},{"a":"polonia","t":"So wie jeder gute Pirat. Ich habe sie mit meiner Crew an verschiedenen Orten vergraben."},{"a":"tavern","t":"Oh! Schatzkarten! Wie aufregend!"},{"a":"polonia","t":"Aye, so machen Piraten das. Man muss sich was für kalte Wintermonate aufheben, wie die Eichhörnchen auf dem Festland."},{"a":"tavern","t":"Und was ist mit dem Rest?"},{"a":"polonia","t":"Habe alles der hübschen Tempeldame gegeben."},{"a":"tavern","t":"Eine Spende für das Waisenhaus? Ich hätte dich nicht als wohltätig eingeschätzt."},{"a":"polonia","t":"Waisen... was?"},{"a":"tavern","t":"Ach, egal. Also, was darf ich dir bringen, Kapitänin?"},{"a":"polonia","t":"Mein Leibgetränk: Seebären-Gebräu! Und für jede Landratte, die meint, dass sie es unten behalten kann ..."},{"a":"polonia","t":"Die nächste Runde geht auf mich! Die Baross-Familie segelt wieder! Joho!"}]},{"id":"polonia_08","i":8,"title":"Flüstern aus der Vergangenheit","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Bereit für deinen nächsten Tauchgang, Meermann?"},{"a":"baker","t":"Jederzeit, Kapitänin! Obwohl ich sagen muss ..."},{"a":"baker","t":"Ich helfe immer gern bei Unterwassererkundungen, aber der Piraterie habe ich eigentlich nicht zugestimmt!"},{"a":"polonia","t":"Mach dir keine Sorgen, Matrose. Wir sind auf Erkundungsfahrt. Deine Kapitänin vergrößert ihr Revier."},{"a":"polonia","t":"Heute steht keine Piraterie an. Aber wenn wir Glück haben, finden wir vielleicht ein gesunkenes Wrack, das wir plündern können. Joho!"},{"a":"baker","t":"Ähm, Kapitänin? Was ist das für ein Schiff am Horizont?"},{"a":"polonia","t":"Arr. Halt die Flosse still, Meermann. Das ist die Bonaventura, das Schiff meines Großvaters!"},{"a":"baker","t":"Sicher? Sie sieht etwas mitgenommen aus."},{"a":"polonia","t":"... Bei Neptuns Bart! D-Die verfluchte Bonaventura! A-Aber das ist unmöglich! Mein Großvater ist schon lange tot!"},{"a":"polonia","t":"M-Matrosen! Planänderung! WIR VERFOLGEN DIESES SCHIFF!"}]},{"id":"polonia_09","i":9,"title":"Eine treibende Legende","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"baker","t":"... Ich hätte nie gedacht, dass ich mal ein so verwahrlostes Schiff betrete."},{"a":"polonia","t":"Pass auf, wo du hintrittst, Meermann. Dieses Schiff hat seine besten Tage längst hinter sich."},{"a":"baker","t":"Um ehrlich zu sein, würde ich lieber schwimmen gehen. Was machen wir überhaupt auf diesem Schiff?"},{"a":"polonia","t":"Was soll das heißen, was wir hier tun? Das ist die Bonaventura von Baross!"},{"a":"polonia","t":"Ich muss herausfinden, was hier passiert ist ... Dieses verwahrloste Schiff sollte nicht auf See sein ..."},{"a":"baker","t":"... Wohl eher Geisterschiff."},{"a":"polonia","t":"Ah, mach mir keine Angst! Geister gibt es nicht!"},{"a":"baker","t":"Und was ist mit Zol..."},{"a":"polonia","t":"Still j-jetzt, Matrose. Ich suche nach Hinweisen."},{"a":"baker","t":"Dieses Logbuch da drüben sieht ziemlich gruselig aus ..."},{"a":"polonia","t":"Arr, das Logbuch des Kapitäns!"},{"a":"baker","t":"Man fühlt sich richtig beobachtet ... findest du nicht?"},{"a":"polonia","t":"Du kommst mit mir, Logbuch. Halte die Piratenaugen nach weiteren Dingen offen."},{"a":"polonia","t":"... Matrose, kannst du aufhören, mein Haar anzutatschen?"},{"a":"baker","t":"Kapitänin, ich bin hier drüben."},{"a":"polonia","t":"... AAAAH! Alle von Bord!"}]},{"id":"polonia_10","i":10,"title":"Piratenerbe","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Eure Kapitänin ist wieder an Bord, Crew. Setzt die Segel, wir verschwinden hier."},{"a":"baker","t":"Kapitänin, sieh nur! Die Bonaventura geht unter!"},{"a":"polonia","t":"Heilige Makrele! Wie ist das nur möglich? Nach all dieser Zeit? Hat das Logbuch dafür gesorgt, dass sie übers Meer treibt?"},{"a":"baker","t":"... Vielleicht hat sie ihren Zweck erfüllt."},{"a":"polonia","t":"Baross, du alter Seebär ... Wie konntest du wissen ...?"},{"a":"baker","t":"Polonia, was ist mit dem Logbuch?"},{"a":"polonia","t":"Du hast recht, lass mich mal sehen ..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"... Ich muss dich um einen weiteren Gefallen bitten, Meermann."},{"a":"baker","t":"Natürlich, ich lese es dir vor."},{"a":"baker","t":"Hmm ... Klingt nach Anweisungen, um irgendeinen Ort unter Wasser zu finden."},{"a":"polonia","t":"Den versunkenen Tempel? Das ist nichts Neues."},{"a":"baker","t":"Nein, er scheint weit weg von hier zu liegen ... Hat wohl etwas mit der verschollenen Goldstadt zu tun?"},{"a":"baker","t":"Aber die verschollene Goldstadt liegt nicht unter Wasser ..."},{"a":"polonia","t":"D-Du meinst, das war nicht nur eine Geschichte? Den Ort gibt es wirklich?"},{"a":"polonia","t":"Meermann, du kannst schwimmen. Das ist Schicksal."},{"a":"polonia","t":"Wenn die Geschichten wahr sind ... wirst du es nicht bereuen, mich dorthin zu bringen."}]},{"id":"polonia_11","i":11,"title":"Die versunkene Goldstadt","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"baker","t":"Puh! Wir sind da! Wie geht es dir, Kapitänin?"},{"a":"polonia","t":"*Hust* *ack* ..."},{"a":"polonia","t":"Keuch ... du hast ... echt starke Beine ... für einen Meermann ..."},{"a":"baker","t":"Und das ist gut so! Dieser Eingang liegt so tief unter Wasser, dass ich nicht glaube, dass es ein Mensch da runter schaffen könnte."},{"a":"polonia","t":"Du hast recht! Ich wäre fast ertrunken. Dieser Ort sieht mich nie wieder ..."},{"a":"baker","t":"Bei der Göttin ... Polonia, sieh dich mal um!"},{"a":"polonia","t":"Bei Neptuns Bart ... die versunkene Goldstadt ..."},{"a":"polonia","t":"Dieser Ort ... Ich habe noch nie etwas Vergleichbares gesehen ..."},{"a":"baker","t":"So viele Schätze! Gold, Perlen ... Im Vergleich dazu sieht die verschollene Goldstadt richtig mickrig aus!"},{"a":"polonia","t":"Sein ganzes Leben lang hat mein Großvater nach diesem Ort gesucht ..."},{"a":"baker","t":"Schließlich konnte er nichts an Land bringen, also hat er es seiner Lieblingsenkelin hinterlassen."},{"a":"polonia","t":"Schnief ... Ich werde ganz sentimental ..."},{"a":"baker","t":"Brauchst du einen Moment für dich, Kapitänin?"},{"a":"polonia","t":"Machst du Scherze? Hier gibt es Beute zu holen! Und du wurdest gerade zum Ersten Maat befördert. Bist du bereit für ein paar Tauchgänge?"},{"a":"baker","t":"Ich muss Säcke voller Beute UND eine Piratin schleppen? Dann mach ich lieber mal meine Dehnübungen!"}]},{"id":"polonia_epilogue","i":12,"title":"Epilog","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Hmm ..."},{"a":"baker","t":"Machen wir uns für einen weiteren Tauchgang bereit, Polonia?"},{"a":"polonia","t":"Nee, Matrose. Ich habe da ein großes Problem."},{"a":"polonia","t":"Ich habe zu viel Geld! Ich weiß schon keinen Strand mehr, an dem ich es vergraben kann."},{"a":"baker","t":"Ich muss zugeben, dass ich mit meinem Anteil auch ein wenig überfordert bin!"},{"a":"baker","t":"Oh, da fällt mir ein:"},{"a":"baker","t":"Ich bin vorher zur versunkenen Bonaventura geschwommen ..."},{"a":"baker","t":"Da gab es nicht viel Besonderes, aber diese Augenklappe habe ich gefunden. Kommt sie dir bekannt vor?"},{"a":"polonia","t":"Erster Maat! Das ist die Augenklappe von Baross!"},{"a":"polonia","t":"Joho! Ich freue mich so, ich könnte dich knutschen!"},{"a":"baker","t":"Das Vergnügen ist ganz meinerseits, Kapitänin. Ich bin sicher, er hätte es so gewollt."},{"a":"polonia","t":"... Weißt du was, ich hab jetzt genug von dieser Plünderei unter Wasser."},{"a":"polonia","t":"Piraten sind doch auf dem Meer zu Hause und nicht in irgendeiner Goldstadt! Ganz egal, wie viel Beute dort wartet."},{"a":"polonia","t":"Als Enkelin des großen Baross schenke ich dir die versunkene Goldstadt mitsamt ihrer verbleibenden Beute."},{"a":"polonia","t":"Ich danke dir für deine Dienste, Erster Maat. Solltest du deine Meinung zur Piraterie je ändern, darfst du dich uns jederzeit anschließen."},{"a":"baker","t":"Danke, Kapitänin. Ich werde unsere gemeinsamen Abenteuer nie vergessen!"},{"a":"baker","t":"... Ich werde wohl noch mal mit Tutu Mano über den Urlaub in der Heimat sprechen!"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"König Reinhold ..."},{"a":"king","t":"Ah ... Meine Pflichten holen mich wohl ein!"},{"a":"sia","t":"Nicht nur das, sie haben sich regelrecht angehäuft. Die Würdenträger warten."},{"a":"king","t":"Leb wohl, Ladenbesitzer! Ich werde zurückkehren!"},{"a":"sia","t":"Das glaube ich weniger."}]},{"id":"king_01","i":1,"title":"Der Hof des Königs","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"king","t":"Der Hof des Königs ist jetzt geöffnet! Antragsteller, tretet vor!"},{"a":"rudo","t":"Hmpf."},{"a":"king","t":"Was kann Reinholds Königreich für seine Untertanen tun, großer ... Bärenmann?"},{"a":"rudo","t":"Ich finde, Ihr solltet jegliche Magie verbieten und die Hexer rauswerfen."},{"a":"king","t":"Ah ... das ist ... ähm ..."},{"a":"king","t":"Wir werden ... deinen Vorschlag überdenken! Die Nächste!"},{"a":"herbs","t":"Hallo! Ich finde, wir sollten jeden Tag zu einem PIÑATA-TAG machen!"},{"a":"king","t":"Was für eine wunderbare Idee! Wir könnten sogar ..."},{"a":"sia","t":"..."},{"a":"king","t":"... viel Zeit mit der Diskussion darüber verbringen! Danke für deinen Vorschlag!"},{"a":"king","t":"Sia, wie viele Antragsteller kommen heute noch?"},{"a":"sia","t":"55, mein König."},{"a":"king","t":"Du meine Güte."}]},{"id":"king_02","i":2,"title":"Ein törichtes Herz aus Gold","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"donovan","t":"Entschuldigung, ist der Platz noch frei?"},{"a":"sia","t":"Willst du mir meinen freien Tag verderben, Donovan?"},{"a":"donovan","t":"Du verletzt mich, Sia. Ich will mich nur mit einer kaiserlichen Mitbürgerin unterhalten."},{"a":"donovan","t":"Wie geht es unserem törichten König in letzter Zeit so?"},{"a":"sia","t":"Deine Spionagekunst ist auch nicht mehr das, was sie mal war, Donovan. Reinhold ist bei Weitem nicht so dumm, wie du vermutest."},{"a":"sia","t":"Er mag zwar immer lächeln, aber in Wahrheit opfert er viel für sein Volk."},{"a":"sia","t":"Davon könnte sich der Imperator ... UNSER Imperator eine Scheibe abschneiden."},{"a":"sia","t":"Meine Aufgabe bestand bisher darin, ihn davon abzuhalten, sich im Namen seines Volkes selbst zu ruinieren."},{"a":"donovan","t":"Wirklich? Faszinierend."},{"a":"sia","t":"Er ist ein Narr mit einem Herzen aus Gold, ja. Aber wenn du ihn unterschätzt, könnte das gefährlich für dich werden."}]},{"id":"king_03","i":3,"title":"Königliche Überstunden","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"king","t":"Puh! Dieser Stapel von Berichten wird auch nicht kleiner, was?"},{"a":"sia","t":"Ich fürchte, wir müssen uns auf eine weitere Nachtschicht einstellen."},{"a":"king","t":"Danke, dass du mich dabei unterstützt, liebe Sia!"},{"a":"sia","t":"Nicht der Rede wert, mein König. Also gut, weiter zum nächsten Bericht ..."},{"a":"sia","t":"Die Bauern von Südburg können ihre Steuern nicht zahlen. Angeblich wegen der schlechten Ernte."},{"a":"sia","t":"Ich glaube, das ist jetzt schon das zweite Mal ..."},{"a":"king","t":"Schicke ein paar der Hofzauberer für Nachforschungen zu ihnen. Vielleicht hat eine Fäule ihr Land befallen."},{"a":"sia","t":"Eine äußerst großzügige Lösung."},{"a":"king","t":"Und erlasse ihnen noch mal die Steuern. Das hätte mein Vater so gewollt!"},{"a":"sia","t":"Sehr wohl. Ich glaube auch, dass König Keinan dasselbe getan hätte."},{"a":"king","t":"Die Krone, die er hinterlassen hat, wiegt wahrlich schwer ..."},{"a":"king","t":"Was steht im nächsten Bericht?"},{"a":"sia","t":"Hier geht es um Spannungen an der Grenze zum Nachbarkönigreich ..."}]},{"id":"king_04","i":4,"title":"Überängstlich","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Mein König ..."},{"a":"king","t":"Wah!"},{"a":"king","t":"B-bitte kündige dich an, bevor du dich an mich anschleichst!"},{"a":"sia","t":"Ah, dieser Ninja-Angriff lässt Euch nicht los, was?"},{"a":"king","t":"Natürlich nicht! Ich habe nur um Haaresbreite überlebt!"},{"a":"sia","t":"Soll ich die Wachen verdoppeln?"},{"a":"king","t":"Das ... wird nicht nötig sein. Aber bitte mach in Zukunft lautere Schritte!"},{"a":"sia","t":"Wie Ihr wünscht, mein König."},{"a":"hemma","t":"Ah, es ist gut, zu Hause zu sein ... Hm?"},{"a":"king","t":"WAAAH! N-Ninjas?!"},{"a":"hemma","t":"Entschuldigt. Wir sind hier wohl falsch."},{"a":"hemma","t":"Das Schattenwandeln ist manchmal nicht so zielgenau."},{"a":"king","t":"B-bitte keine SCHATTENTELEPORTATIONEN mehr in meinem Thronsaal!"},{"a":"sia","t":"K-König Reinhold? Geht es Euch gut?"},{"a":"king","t":"Ja! Bitte geleite diesen ... entsetzlichen Gast zur Tür."},{"a":"sia","t":"Sehr wohl. Ich werde dafür Sorge tragen, dass das Schloss in Zukunft vor solchem Eindringen geschützt ist."},{"a":"hemma","t":"Da haben wir ja eine lustige Zwischenstation gefunden. Bis zum nächsten Mal."},{"a":"king","t":"Das hoffe ich nicht!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"Der lebende Berg","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Brrr ... Ich bin für diese Kälte nicht richtig angezogen! Warum sind wir nochmal hier?"},{"a":"lilu","t":"Die Edelsteine haben ein paar wunderbare Eigenschaften! Grimar hat mir gesagt ..."},{"a":"argon","t":"Warte, Lilu! Schau mal! Da drüben kämpft ein Mann gegen einen Yeti!"},{"a":"lilu","t":"Ein Mann?! Er ist so groß wie ein Berg!"},{"a":"lilu","t":"Und er ... besiegt den Yeti?!"},{"a":"rudo","t":"Wow ... Das sind zehn."},{"a":"argon","t":"Das war ja echt ein beeindruckender Kampf! Du warst fantastisch!"},{"a":"rudo","t":"Was?"},{"a":"lilu","t":"Oh, du bist verletzt! Lass mich dich heilen!"},{"a":"lilu","t":"<c1>Heilen</c1>...!"},{"a":"rudo","t":"ZURÜCK!"},{"a":"rudo","t":"Mir geht es gut. Das wird von selbst heilen."},{"a":"rudo","t":"Kinder sollten sich nicht an so einem Ort herumtreiben. Geht nach Hause."},{"a":"argon","t":"Puh, dieser Kerl hasst Magie aber wirklich, was?"},{"a":"lilu","t":"Nein. Was ich in seinen Augen gesehen habe ... das war Angst."}]},{"id":"rudo_02","i":2,"title":"Räumungsbefehl","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"elderowen","t":"Es tut mir leid, ich verstehe das nicht ..."},{"a":"rudo","t":"Bah! Dann werde ich es so einfach ausdrücken, dass sogar deine alten Ohren es verstehen!"},{"a":"rudo","t":"Der Zauberer in dieser Stadt ist ein durchgedrehter Wahnsinniger und sollte zum Wohle aller hinausgeworfen werden."},{"a":"elderowen","t":"Du meine Güte ... solch harte Worte ..."},{"a":"rudo","t":"Erst gestern hat er mir aufgetragen, Timotheus im Auge zu behalten ..."},{"a":"rudo","t":"... da „Tim“ angeblich wahnhaft und verwirrt ist und beobachtet werden sollte."},{"a":"rudo","t":"Er *IST* Timotheus!"},{"a":"elderowen","t":"Hmm, ja. Ich verstehe."},{"a":"elderowen","t":"Trotz seines ... „Zustands“ ist Timotheus Grimar ein wesentlicher Bestandteil dieser Stadt."},{"a":"elderowen","t":"Er ist so hilfsbereit wie harmlos. Ich sehe keinen Grund zur Panik."},{"a":"lilu","t":"Was redet ihr da, Meister Grimar hinauszuwerfen?!"},{"a":"rudo","t":"Halt dich da raus, Mädchen."},{"a":"lilu","t":"Nein! Meister Grimar ist ein sehr mächtiger Zauberer, aber er würde nie jemanden verletzen!"},{"a":"rudo","t":"Pah! Na schön! Aber wenn diese Stadt in die Luft geht, sagt nicht, ich hätte euch nicht gewarnt."},{"a":"elderowen","t":"Der da ist ein ziemlicher Unruhestifter."},{"a":"lilu","t":"Ich sollte ihn lieber im Auge behalten ..."}]},{"id":"rudo_03","i":3,"title":"Funkengeborener","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"priest","t":"Entschuldige ... Worüber meckerst du da?"},{"a":"rudo","t":"Verdammt. Warum gibt es so viele verdammte Hexer in dieser Stadt ..."},{"a":"priest","t":"Ah, Herr Rudo, nehme ich an."},{"a":"rudo","t":"Tu nicht so freundlich, Zauberin."},{"a":"priest","t":"Ich bin eine Klerikerin der Göttin, meine Kräfte unterscheiden sich von denen eines Zauberers."},{"a":"priest","t":"Mit meinem Eid habe ich mich einem Leben der Heilung und des Schutzes verschworen."},{"a":"rudo","t":"Das kaufe ich dir nicht ab. Ihr Funkengeborenen seid alle gleich."},{"a":"priest","t":"Du weißt vom Funken ...?"},{"a":"rudo","t":"Hmpf. Vergiss, was ich gesagt habe. Ich mach mich vom Acker."},{"a":"priest","t":"Hast du zugehört, Lilu?"},{"a":"lilu","t":"Ja, ich hab alles gehört!"},{"a":"priest","t":"Kannst du dich an meinen Vortrag über den Funken erinnern?"},{"a":"lilu","t":"Natürlich! Nur Leute, die mit dem Funken geboren wurden, können Zauber kontrollieren und wirken."},{"a":"lilu","t":"Dieses Phänomen ist aber den meisten Menschen unbekannt."},{"a":"priest","t":"Das stimmt! Das habe ich von meiner klügsten Schülerin auch erwartet!"},{"a":"priest","t":"Obwohl das die Frage aufwirft: Woher weiß er davon ...?"},{"a":"lilu","t":"Hmm ... Glaubst du ...?"}]},{"id":"rudo_04","i":4,"title":"Einbruch","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"polonia","t":"Joho! Kapitänin Polonia hat dieses Mal einen Glückstreffer gelandet!"},{"a":"polonia","t":"Ein ganzes königliches Grab, bereit für gutes, altes Plündern!"},{"a":"rudo","t":"Leise, Seemädchen. Ich bin beschäftigt."},{"a":"polonia","t":"Oder das wäre es ... wäre da nicht ein verflixter Berserker, der DIE GANZE BEUTE ZERTRÜMMERT!"},{"a":"polonia","t":"Was zum Klabautermann ist dein Problem, Freundchen? Dieses Zeug ist tonnenweise Dublonen wert!"},{"a":"rudo","t":"Es ist uralt."},{"a":"rudo","t":"Es ist magisch."},{"a":"rudo","t":"Und es ist wahrscheinlich verflucht."},{"a":"rudo","t":"Ich zerschmettere es, um anderen den Ärger zu ersparen."},{"a":"rudo","t":"Wenn diese Stadt zu dumm ist, um das Problem zu sehen, kümmere ich mich eben selbst darum!"},{"a":"polonia","t":"Oi, Landratte. Dieser Stab sieht RICHTIG wertvoll aus. Denn wirst du nicht ..."},{"a":"rudo","t":"Hmpf."},{"a":"rudo","t":"Autsch."},{"a":"polonia","t":"Beim Kraken! Zerbrich ihn nicht einfach über deinem Knie!"},{"a":"polonia","t":"Obwohl es aussieht, als wäre eher der Stab derjenige, der Dinge zerbricht. Er hat nicht mal einen Kratzer!"},{"a":"polonia","t":"Wie geht es deinem Bein, Freundchen?"},{"a":"rudo","t":"Gut. Aber dieser Stab ist härter, als er aussieht."},{"a":"rudo","t":"Und aus irgendeinem Grund kann ich ihn nicht fallen lassen. Als wäre er ... an meiner Hand festgeklebt."},{"a":"polonia","t":"Ich bin kein Schiffsdoktor, aber es sieht so aus, als hättest du dir einen richtigen Fluch eingebrockt, Freundchen."},{"a":"polonia","t":"Das solltest du vielleicht untersuchen lassen."},{"a":"rudo","t":"Natürlich ist es verfluchte Magie. Es ist IMMER verfluchte Magie."},{"a":"rudo","t":"Schön. Ich verschwinde. Mach den Rest für mich kaputt."},{"a":"polonia","t":"Aye, aye, Kumpel!"},{"a":"polonia","t":"Statt zerbrechen will ich lieber einbrechen, denn diese Piratin wird plündern!"}]},{"id":"rudo_a","i":4,"title":"Liebevolle Strenge","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"herbs","t":"Gorza!"},{"a":"gems","t":"Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Hey Juniper. Und Maylee! Was ist los?"},{"a":"herbs","t":"Ich und Maylee haben über ihren zukünftigen Traumprinzen gesprochen ..."},{"a":"gems","t":"Oh, ich kann es kaum erwarten!"},{"a":"herbs","t":"Und wir haben uns gefragt ... wie hast DU deinen kennengelernt?"},{"a":"wood","t":"Diesen großen Dummkopf Rudo? Ha!"},{"a":"wood","t":"Er mag nicht so aussehen, aber dieser Mann weiß wirklich, wie man mit einer Dame spricht."},{"a":"wood","t":"Mal sehen ... Es war ungefähr so ..."},{"a":"rudo","t":"Noch einen, für den Weg."},{"a":"tavern","t":"Also ... Rudo. Hast du je darüber nachgedacht, sesshaft zu werden?"},{"a":"rudo","t":"Kümmere dich um deine eigenen Angelegenheiten, Naja. Ich habe keine Zeit für so was."},{"a":"tavern","t":"Die Liebe trifft dich, wenn du es am wenigsten erwartest! Wer weiß, die Frau deiner Träume könnte jederzeit hereinspazieren ..."},{"a":"rudo","t":"Bah! Ich gebe mich bestimmt nicht mit einer Frau zufrieden, die mich nicht zu Boden werfen kann."},{"a":"wood","t":"Soll das eine Herausforderung sein, Großer?"},{"a":"rudo","t":"Probier’s doch, Zahngesicht!"},{"a":"tavern","t":"Gorza, bitte stell den Stuhl hin ..."},{"a":"wood","t":"Was sagst du dazu, Schwachkopf? Willst du mehr davon?"},{"a":"rudo","t":"RAAAH!"},{"a":"wood","t":"Wow!"},{"a":"wood","t":"Und die Woche darauf haben wir geheiratet. Die blutigste Hochzeit, die ich je gesehen habe."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"V-Vielleicht sollten wir jemand anderen fragen."}]},{"id":"rudo_05","i":5,"title":"Flüche und Ausbrüche","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Was meinst du damit, du kannst es nicht zerbrechen?"},{"a":"master","t":"Genau das meine ich damit, mein gewalttätiger Freund, ich kann dieses Relikt nicht zerbrechen."},{"a":"rudo","t":"Was nützt ein stahlharter Hammer, wenn er nicht mal diesen mickrigen Stab zerbrechen kann?"},{"a":"master","t":"Na ja, so mickrig ist er nicht ... Für mich sieht er ziemlich böse aus!"},{"a":"master","t":"Auf jeden Fall steckt hier mehr dahinter, vermutlich Magie ..."},{"a":"rudo","t":"NATÜRLICH ist es Magie."},{"a":"rudo","t":"Es ist immer verfluchte Magie."},{"a":"master","t":"Für mich wirkt das so, als hättest du das schon gewusst! Warum wendest du dich nicht an jemanden, der sich mit solchen Dingen auskennt, statt an mich?"},{"a":"rudo","t":"Man kann Magiern nicht trauen ... Kein bisschen."},{"a":"master","t":"Tja, ich glaube nicht, dass du da eine andere Wahl hast."},{"a":"master","t":"Außerdem, wie kann man der süßen Lilu nicht trauen? Sie ist entzückend!"},{"a":"rudo","t":"Sie ist doch eine Magierin, oder? Also ist sie wie alle anderen."},{"a":"rudo","t":"Gefährlich. Böse. GEMEIN."},{"a":"master","t":"Na ja, sie ist wahrscheinlich die Einzige, die helfen kann, wenn du diesen Stab irgendwann loswerden willst."},{"a":"rudo","t":"Verflixt."}]},{"id":"rudo_06","i":6,"title":"Zauberer wider Willen","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Hallo Naja, das Übliche."},{"a":"tavern","t":"Tut mir leid, Rudo, keine Waffen. Du kennst die Regeln."},{"a":"rudo","t":"Das? Das ist doch nur ein Gehstock."},{"a":"tavern","t":"Das glaube ich nicht! Ich erkenne doch einen magischen Stab, wenn ich einen sehe!"},{"a":"rudo","t":"Pah. Na schön. Siehst du? So was von verflucht. Kann ihn nicht ablegen."},{"a":"tavern","t":"Du meine Güte! Dann können wir wohl eine kleine Ausnahme für dich machen."},{"a":"rudo","t":"Hmpf, danke."},{"a":"tavern","t":"Also, was willst du dagegen tun?"},{"a":"rudo","t":"Ignorieren. Ich lebe einfach damit."},{"a":"tavern","t":"Wirklich? Ich finde, er macht dich schroffer. Schroffer als sonst, wenn das überhaupt möglich ist."},{"a":"tavern","t":"Außerdem würden dich alle auf den ersten Blick für eine Art Magier halten."},{"a":"rudo","t":"... Wirklich? Einen verdammten Magier?"},{"a":"tavern","t":"Dir würde nur noch ein alberner Hut fehlen! Und bessere Laune!"},{"a":"rudo","t":"Vielleicht hast du recht. Ich muss etwas dagegen tun. Bis dann!"},{"a":"tavern","t":"Schönen Tag noch. Ich setz das auf deine Liste!"}]},{"id":"rudo_07","i":7,"title":"Aufflackerndes Trauma","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Tut mir leid wegen vorhin. Ich habe gehört, du ... könntest mit diesem Fluch helfen."},{"a":"lilu","t":"Mit dem Stab, was? Sieht ziemlich fies aus!"},{"a":"lilu","t":"Ich habe noch nie versucht, einen Fluch zu brechen, aber theoretisch ... sollte ich es können."},{"a":"lilu","t":"Bist du wirklich bereit dafür? Du wirkst so angespannt."},{"a":"rudo","t":"... Ja."},{"a":"lilu","t":"Okay. Ich muss mich nur konzentrieren ..."},{"a":"lilu","t":"Ich sehe den Fluch ... er umgibt dich."},{"a":"lilu","t":"Warte, ich muss tiefer hinein ..."},{"a":"rudo","t":"... Nghn!"},{"a":"lilu","t":"Wow!"},{"a":"lilu","t":"Das hat gerade WIRKLICH so ausgesehen, als wolltest du mich schlagen!"},{"a":"rudo","t":"... Tut mir leid. Keine Absicht."},{"a":"lilu","t":"Ich glaube nicht, dass das so funktionieren wird. Ich muss mich konzentrieren, weißt du?"},{"a":"rudo","t":"Ja, das ist meine Schuld. Ich werde eine andere Lösung suchen."},{"a":"lilu","t":"Frag doch Malady. Vielleicht sieht sie etwas, das ich nicht sehe."},{"a":"rudo","t":"Malady, hm? Ich werde es versuchen."},{"a":"lilu","t":"Aber sei nett! Sie hat ... besondere Bedürfnisse, die du kennen solltest ..."}]},{"id":"rudo_08","i":8,"title":"Ein Fluch für zwei","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Fräulein Malady, hättest du eine Sekunde Zeit?"},{"a":"malady","t":"(Oh nein, Lilu hatte mich vor ihm gewarnt ...)"},{"a":"malady","t":"Ähm ... tut mir leid. Ich glaube nicht ..."},{"a":"rudo","t":"Entschuldigung, ich wollte dir keine Angst einjagen. Ich dachte, du kennst dich vielleicht mit den Stäben aus."},{"a":"malady","t":"Ich ... Ich dachte, du hasst Magie?"},{"a":"rudo","t":"Mehr als alles andere auf der Welt."},{"a":"rudo","t":"Aber du bist verflucht, nicht wahr? So wie ich."},{"a":"rudo","t":"Du hast dich nicht für die Magie entschieden. Es ist nicht deine Schuld."},{"a":"malady","t":"... In diesem Fall kann ich versuchen ... mit dem Stab zu reden."},{"a":"malady","t":"..."},{"a":"malady","t":"... Er ist wie ein Parasit. Er nährt sich an deinem Funken."},{"a":"rudo","t":"Das Ding hat einen Verstand?"},{"a":"malady","t":"Ja ... gewissermaßen."},{"a":"malady","t":"Dein Funke wirkt extrem stark. Es kann Jahrzehnte dauern, aber ..."},{"a":"malady","t":"... Vielleicht kann er dich von deiner Magie befreien?"},{"a":"rudo","t":"Hmpf. Da wär ich mir nicht so sicher."},{"a":"rudo","t":"Also will er einfach nur jemanden, dem er die Magie aussaugen kann?"},{"a":"malady","t":"Ähm ... ja. Mehr oder weniger."},{"a":"malady","t":"Bitte ... Ich bin schon verflucht, also ..."},{"a":"rudo","t":"Ha! Das würde mir im Traum nicht einfallen, Fräulein."},{"a":"rudo","t":"Danke für die Hilfe. Ich glaube, ich habe eine Idee ..."}]},{"id":"rudo_09","i":9,"title":"Die Vergangenheit eines Soldaten","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"malady","t":"Ähm, darf ich eintreten?"},{"a":"veteran","t":"Ah, die Medusa, von der ich so viel gehört habe."},{"a":"veteran","t":"Komm herein, Neuling. Ich habe leider keine passenden Stühle in deiner Größe."},{"a":"malady","t":"Schon gut ... danke. Ich wollte mich nach dem Mann erkundigen, Rudo."},{"a":"veteran","t":"Dieser Riese? Er hat dich doch nicht drangsaliert, oder?"},{"a":"malady","t":"Nein, er war ... ungewöhnlich nett zu mir."},{"a":"veteran","t":"Wirklich? Seltsam, er hasst Magie."},{"a":"malady","t":"Deswegen bin ich gekommen. Ich wollte fragen ... warum?"},{"a":"veteran","t":"Wir waren mal Teil der Armee des Imperiums. Alte Kriegskumpel."},{"a":"veteran","t":"Rudo war ein ... „Freiwilliger“ bei einem Experiment. Dabei ging es darum, Soldaten auf künstliche Weise mit dem Funken zu versehen."},{"a":"veteran","t":"Es war nicht schön. Danach war er nie wieder derselbe."},{"a":"malady","t":"Das ist schrecklich ... "},{"a":"veteran","t":"Es ist noch schlimmer, als es klingt. Wir sind so schnell abgehauen, wie wir konnten."},{"a":"malady","t":"Hat es denn wenigstens ... funktioniert? Ich habe einen extrem starken Funken in ihm gespürt ..."},{"a":"veteran","t":"Schwer zu sagen. Du hast ja gesehen, wie er ist. Nicht mal der Kaiser selbst konnte ihn dazu bringen, auch nur den einfachsten Zauber zu wirken."},{"a":"malady","t":"Und jetzt ... ist er deswegen mit einem schrecklichen Fluch gestraft ...Wie können wir ihm helfen?"},{"a":"veteran","t":"Er kam zu dir, oder? Dass er um Hilfe bittet, ist ein gutes Zeichen! "},{"a":"veteran","t":"Er mag nicht der Klügste sein, aber hartnäckig ist er. Ich bin mir sicher, dass ihm etwas einfallen wird."}]},{"id":"rudo_10","i":10,"title":"Eigentumsübertragung","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"rudo","t":"Also gut, du fieses Stäbchen. Ich mach dir einen Vorschlag."},{"a":"rudo","t":"Ich überlasse dich dem Nervtöter-Kobold da drüben."},{"a":"monster_Forest_Blacksmith","t":"Huch! Lass mich ... los!"},{"a":"rudo","t":"Du freundest dich mit ihm an und wir vergessen das alles."},{"a":"rudo","t":"Wenn du das nicht willst ..."},{"a":"rudo","t":"Tauche ich in diese Lava ein und wir sehen mal, wer von uns länger durchhält."},{"a":"rudo","t":"Also, was soll es sein? Das „Wasser“ sieht angenehm aus, wenn du mich fragst!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"... Gute Wahl. Viel Spaß damit, Nervtöter-Kobold."},{"a":"monster_Forest_Blacksmith","t":"Uh! Er ... steckt fest!"},{"a":"rudo","t":"Buhaha! Bis dann!"}]},{"id":"rudo_epilogue","i":11,"title":"Epilog","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"lilu","t":"Rudo! Also was neulich passiert ist ..."},{"a":"rudo","t":"Hm?"},{"a":"lilu","t":"Oh! Du bist den Stab losgeworden!"},{"a":"rudo","t":"Genau. Eine Sorge weniger."},{"a":"rudo","t":"Entschuldige wegen neulich. Ich war etwas nervös."},{"a":"lilu","t":"Ich glaube, ich kann dir verzeihen. Aber du musst an deiner Einstellung gegenüber Magiern arbeiten!"},{"a":"rudo","t":"Ha! Diese Malady war unerwartet hilfreich. Wer weiß, vielleicht gewöhne ich mich irgendwann an sie."},{"a":"lilu","t":"Konnte sie den Fluch aufheben?"},{"a":"rudo","t":"Nicht ganz. Aber dank ihr habe ich unerwartete ... Hilfe gefunden."},{"a":"rudo","t":"Ein bisschen Unterstützung hier und da kann nicht schaden. Buahaha!"},{"a":"argon","t":"Ashley, pass auf! Da kommt noch was anderes!"},{"a":"ashley","t":"Ich bin auf alles vorbereitet! Komm schon, Bestie!"},{"a":"monster_Forest_Blacksmith","t":"... Hilfe ..."},{"a":"argon","t":"Hm?"},{"a":"ashley","t":"Hmmmm?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Königliche erste Schritte","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"king","t":"Sia! Ich habe eine Entscheidung getroffen!"},{"a":"sia","t":"Ja, mein König?"},{"a":"king","t":"Heute möchte ich einkaufen gehen!"},{"a":"sia","t":"Eine vortreffliche Idee, Eure Majestät."},{"a":"sia","t":"Wenn ich mir aber Euren Terminkalender ansehe, steht für heute wohl ein Treffen mit ausländischen Würdenträgern an ..."},{"a":"king","t":"Oh, wie lästig! Können wir die nicht einfach wegschicken?"},{"a":"sia","t":"Vergesst nicht, mein König, Ihr mögt zwar noch jung sein, doch Ihr seid dennoch der König. Euer Wort ist Gesetz."},{"a":"king","t":"Du hast absolut recht! Also gehen wir einkaufen! Diese Würdenträger können warten!"},{"a":"sia","t":"Eure Entschlusskraft ist bewundernswert. Darf ich Euch begleiten?"},{"a":"king","t":"Selbstverständlich! Niemandem sonst kann ich den Schutz meiner anmutigen Person anvertrauen."}]},{"id":"sia_02","i":2,"title":"Freunde an niedrigen Orten","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"... und daher befürchte ich, dass das Leben unseres Königs in Gefahr ist."},{"a":"elderowen","t":"Ich verstehe. Einige uns feindlich gesinnte Königreiche würden vom Tod des Königs in der Tat profitieren."},{"a":"elderowen","t":"Mir sind keine verdächtigen Gesellen aufgefallen, aber Naja in der Schenke weiß sicher mehr."},{"a":"sia","t":"Danke, Älterer. Ich weiß deine Weisheit und deinen Patriotismus zu schätzen."},{"a":"elderowen","t":"Keine Ursache. Es ist meine Pflicht als Bürger, das Wohlergehen unseres Königs zu sichern."},{"a":"elderowen","t":"Reinhold mag jung und töricht sein, aber er wird sicher einmal ein fantastischer König werden ... früher oder später."},{"a":"sia","t":"Und es ist meine Pflicht, dafür zu sorgen, dass er bis dahin überlebt!"},{"a":"tavern","t":"Sieh an, hier in der Schenke bekommen wir nicht oft Besuch von hübschen Adligen!"},{"a":"sia","t":"Spar dir die Schmeicheleien, Naja. Du weißt, wer ich bin."},{"a":"tavern","t":"Natürlich! Sia Leonel, ein Geschenk des Imperators von Kern für unseren König ..."},{"a":"tavern","t":"Offiziell als Ratgeberin, aber sicher auch, um den König im Auge zu behalten, hab ich nicht recht?"},{"a":"sia","t":"...!"},{"a":"sia","t":"Du bist ja ganz schön naseweis, oder?"},{"a":"sia","t":"Nun denn, naseweise Naja, erzähl mir doch mal ..."},{"a":"sia","t":"Sind dir in letzter Zeit merkwürdige Gestalten in der Schenke aufgefallen?"},{"a":"tavern","t":"Oh, merkwürdige Gestalten haben wir hier zuhauf! Beschwipste Orks, Ladenbesitzer ..."},{"a":"tavern","t":"Aber die merkwürdigste Gestalt ist wohl das Mädchen in der Ecke dort drüben."},{"a":"yami","t":"...!"},{"a":"sia","t":"Sie ist entkommen ..."},{"a":"sia","t":"Das war eine Spionin aus Azuma! Oder eine Assassinin."},{"a":"sia","t":"Ich muss noch wachsamer sein ..."}]},{"id":"sia_03","i":3,"title":"Ungebetener Gast","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Wir haben uns heute hier versammelt, um die unglaubliche Großzügigkeit des Königs zu feiern."},{"a":"sia","t":"In den vergangenen Monaten hat er Gold im Wert mehrerer Millionen aus seiner eigenen Kasse ..."},{"a":"sia","t":"... an verschiedene örtliche Tempel, Schulen und Waisenhäuser gespendet."},{"a":"sia","t":"Alle sind bei diesem Fest willkommen, also bitte erzählt es euren Freunden und eurer Familie."},{"a":"sia","t":"Lang lebe König Reinhold!"},{"a":"yami","t":"Reinhold, du Tyrann, deine Herrschaft endet jetzt!"},{"a":"king","t":"Aaah ..."},{"a":"sia","t":"Ein Shuriken ...! Die Spionin aus Azuma!"},{"a":"sia","t":"Wachen! Riegelt das Schloss ab! Lasst niemanden entkommen!"},{"a":"sia","t":"Argon, verfolge die Assassinin!"},{"a":"argon","t":"Sofort!"},{"a":"sia","t":"Du, ungewaschener Nichtsnutz! Der König ist verletzt! Hol sofort einen Heiler!"},{"a":"leather","t":"Wow, wie gemein, Mann."},{"a":"sia","t":"(Jeder Eingang wurde strengstens überwacht ...)"},{"a":"sia","t":"(... Wer ist dieses Mädchen nur?)"}]},{"id":"sia_04","i":4,"title":"Erpresserische Neigungen","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Naseweise Naja, ich glaube, du schuldest mir eine Erklärung."},{"a":"tavern","t":"Oh, Frau Leonel. Ich denke, IHR schuldet mir eine Erklärung."},{"a":"sia","t":"Wie bitte?"},{"a":"tavern","t":"Ich habe einige ÄUSSERST interessante Briefe abgefangen, die von Euch verschickt wurden, wie ich glaube."},{"a":"tavern","t":"Sollen wir sie gemeinsam lesen?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Mal sehen ... Ein Kern-Siegel, direkt an den Imperator von Kern adressiert?"},{"a":"tavern","t":"Du meine Güte. Ich hatte so auf eine skandalöse Liebesaffäre gehofft, aber Hochverrat ist wohl auch okay."},{"a":"sia","t":"N-Naja, hör bitte auf!"},{"a":"tavern","t":"Oh! Das ist eine pikante Stelle!"},{"a":"tavern","t":"„König Reinhold ist ein vollkommener Narr, dessen Herrschaft Euch sehr zugute kommt.“"},{"a":"tavern","t":"„Ihn am Leben zu lassen schadet seinem Königreich bestimmt mehr als der Tod seines Herrschers.“"},{"a":"sia","t":"..."},{"a":"tavern","t":"Solch unfreundliche Worte sind doch ziemlich ungebührlich für seine Ratgeberin!"},{"a":"sia","t":"Naseweise ... Naja ... Dafür wirst du bezahlen!"},{"a":"tavern","t":"Eines Tages vielleicht. Aber einstweilen seid Ihr es, die bezahlt. Und zwar großzügig, vermute ich."},{"a":"sia","t":"... Du sinkst so tief und willst mich erpressen?"},{"a":"tavern","t":"Eine winzige Sünde, verglichen mit Hochverrat!"},{"a":"tavern","t":"Hättet Ihr jedoch geplant, unserem König Schaden zuzufügen ..."},{"a":"sia","t":"Hmpf. Na schön. Nenn mir deinen Preis. Und bete, dass mein Spionagenetzwerk deines nie überlistet, Naja."},{"a":"tavern","t":"Darauf freue ich mich schon!"}]},{"id":"sia_a","i":4,"title":"Die Laune des Königs","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Glücksmarken"},"side":true,"lines":[{"a":"sia","t":"Mein König."},{"a":"king","t":"Meine liebe Sia! Was kann ich für dich tun?"},{"a":"sia","t":"Habt Ihr zufällig in letzter Zeit Euren Launen nachgegeben?"},{"a":"king","t":"N-Nein! Natürlich nicht! Das würde ich nie tun!"},{"a":"sia","t":"Seltsam. Unsere Bücher besagen, dass Kammer 36 randvoll mit <c1>Kunai</c1> ist."},{"a":"sia","t":"Ich muss seine Majestät wohl nicht daran erinnern, dass es sich hierbei um einen äußerst seltenen Gegenstand handelt."},{"a":"king","t":"I-Ich bin mir sicher, es gibt eine ganz logi..."},{"a":"sia","t":"Außerdem wurden viele der seltensten Antiquitäten des Königreichs in den Händen gewöhnlicher Leute gesehen."},{"a":"sia","t":"Eure Großzügigkeit ist vorbildlich ..."},{"a":"sia","t":"... aber bitte unterlasst es, Eure Stimmungsschwankungen mit unschätzbar wertvollen Artefakten zu finanzieren."},{"a":"king","t":"Hmpf. Na schön! Ab dem heutigen Tage bin ich ein neuer Mann!"},{"a":"sia","t":"Danke für Euer Verständnis. Ich werde jetzt gehen."},{"a":"king","t":"Mein Wille ist stark! Ich brauche nichts Materielles!"},{"a":"king","t":"Aber in diesem Raum fehlen noch ein paar <c1>königliche Klingen</c1>, oder?"}]},{"id":"sia_05","i":5,"title":"Agentin Schwan","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"„... In einer dramatischen Wende der Ereignisse wurde ein Attentat auf König Reinhold verübt.“"},{"a":"sia","t":"„Azuma scheint hinter diesem Attentat zu stecken. Agentin Schwan wird dem weiter nachgehen.“"},{"a":"king","t":"Sia! Was machst du da?"},{"a":"sia","t":"Oh, ich schreibe nur einen Brief, nichts weiter."},{"a":"sia","t":"(Meinen Bericht an den Imperator von Kern, um genau zu sein ...)"},{"a":"king","t":"Nun gut! Einige ausländische Würdenträger erwarten meine Anwesenheit."},{"a":"king","t":"Sie sind vielleicht ein bisschen ... beleidigt wegen des letzten Shoppingtrips."},{"a":"king","t":"Ich würde mich über deine Hilfe freuen, diese Situation zu entschärfen!"},{"a":"sia","t":"Natürlich. Ich komme sofort, mein König."},{"a":"sia","t":"Wenn ich den Imperator von Kern über das versuchte Attentat informiere, könnte das fatale Konsequenzen nach sich ziehen ..."},{"a":"sia","t":"Ich ... brauche mehr Zeit zum Nachdenken. Das Königreich ist ... noch nicht bereit, sich Kern zu stellen."},{"a":"sia","t":"Um die Sicherheit aller zu garantieren ... kann ich dieses Detail wohl auslassen ..."},{"a":"sia","t":"„Alles läuft nach Plan. Agentin Schwan hat diesen Monat nichts zu berichten.“"}]},{"id":"sia_06","i":6,"title":"Von Rosen und Dornen","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"king","t":"Sia! Da ist ein Besucher für dich! Ein ziemlich fürstlicher Kerl, wenn ich das hinzufügen darf."},{"a":"sia","t":"Fürstlich, mein König? Es kann doch sicher nicht ..."},{"a":"donovan","t":"Fräulein Sia."},{"a":"sia","t":"... Donovan sein."},{"a":"sia","t":"Mein König, eine dringende Angelegenheit erfordert Eure Aufmerksamkeit in der Schatzkammer. Ich würde Euch raten, sofort dorthin zu gehen."},{"a":"king","t":"Oh, ist die letzte Lieferung reines Gold eingetroffen? Ich kann es kaum erwarten!"},{"a":"donovan","t":"Immer ein Narr, dieser König. Nicht wahr?"},{"a":"sia","t":"Welcher böse Wind treibt dich in Reinholds Königreich, Alchemist?"},{"a":"donovan","t":"Du kommst wie immer direkt zur Sache, Agentin Schwan."},{"a":"donovan","t":"Ich verbringe hier nur meinen Urlaub. Mit der Erlaubnis des Imperators von Kern natürlich."},{"a":"donovan","t":"Rieche an Blumen, verkoste Tränke ... Ein echter Alchemistenurlaub, könnte man sagen."},{"a":"sia","t":"Und dafür kommst du ausgerechnet hierher?"},{"a":"donovan","t":"Dieses rückschrittliche Königreich scheint seinen Anteil an begabten Alchemisten zu haben."},{"a":"donovan","t":"Aber wenn die Treue eines Schwans zu schwinden scheint ..."},{"a":"sia","t":"Du hast dich klar ausgedrückt, Donovan. Du kannst jetzt gehen. Genieße deinen ... Urlaub."},{"a":"donovan","t":"Wie du wünschst, Fräulein Sia. Es war mir ein Vergnügen, wie immer."},{"a":"sia","t":"Ein weiterer Dorn im Auge."}]},{"id":"sia_07","i":7,"title":"Fremder der Goldstadt","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Donovan? Ich hoffe, ich störe dich nicht beim ... Spionieren."},{"a":"donovan","t":"Oh! Fräulein Sia!"},{"a":"donovan","t":"Nein, überhaupt nicht! Ich sehe mich nur um."},{"a":"sia","t":"Es gibt keinen Grund, so geheimnisvoll zu tun. Alle sind in der verschollenen Goldstadt willkommen."},{"a":"sia","t":"Aber bedenke, dass nach dem Gesetz des Königreichs alles <c1>reine Gold</c1>, das darin gefunden wird, König Reinhold gehört."},{"a":"sia","t":"Im Gegenzug werden tapfere Abenteurer für ihren Beitrag belohnt."},{"a":"donovan","t":"Ich verstehe. Ein sehr ... großzügiger Herrscher."},{"a":"donovan","t":"Das <c1>reine Gold</c1> wird dann zu Münzgeld geprägt, wodurch die Inflation stark steigt ..."},{"a":"sia","t":"Das stimmt. Wie ich sehe, hast du meine Nachrichten an den Imperator abgefangen."},{"a":"donovan","t":"Ich weiß nun mal gerne Bescheid."},{"a":"sia","t":"Da du schon hier bist, mach dich nützlich und bring etwas <c1>reines Gold</c1> zum Schloss."},{"a":"donovan","t":"Natürlich. Alles für die Dame."},{"a":"sia","t":"Versuch, dir auf dem Rückweg keinen Nagel abzubrechen, lieber Donovan."}]},{"id":"sia_08","i":8,"title":"Am Kreuzweg des Schicksals","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"tavern","t":"Mein kleiner Schwan ist zurückgekehrt! Und pünktlich wie immer, wie von unserer bedeutendsten Verwalterin nicht anders zu erwarten."},{"a":"sia","t":"Ich bin deiner Aufforderung gefolgt, naseweise Naja. Komm schnell zur Sache, ich bin heute nämlich nicht besonders gut aufgelegt."},{"a":"tavern","t":"Dann muss ich dir die Stimmung leider noch weiter verderben. Ich habe die Nachricht eines gewissen Alchemisten abgefangen ..."},{"a":"tavern","t":"Er hat sie sogar per magischer Expresspost geschickt! Du machst dir keine Vorstellung, wie schwierig es ist, sich so eine zu schnappen!"},{"a":"sia","t":"Das heißt doch nicht etwa ..."},{"a":"tavern","t":"Dieser Donovan scheint Wind von deinem Spielchen bekommen zu haben."},{"a":"sia","t":"Wenn du sie abgefangen hast, dann ..."},{"a":"tavern","t":"... geht sie nirgendwohin, genau! Falls du bezahlst, versteht sich."},{"a":"sia","t":"Ich ... Na schön. Nenn mir deinen Preis, Naja. Ich werde ihn bezahlen."},{"a":"tavern","t":"Meine Gebühren sind gestiegen. Für diesen Schatz fordere ich eine ganz besondere Prämie."},{"a":"sia","t":"Also gut. Ich werde ..."},{"a":"tavern","t":"Wähle eine Seite, Sia. Das ist mein Preis."},{"a":"sia","t":"..."},{"a":"tavern","t":"Es ist gefährlich, beide Seiten gegeneinander ausspielen zu wollen ... Und wie mir scheint hast du dich richtig schön in diesem Netz verheddert."},{"a":"tavern","t":"Je nachdem, wie deine Antwort ausfällt, kann ich dir vielleicht helfen ..."}]},{"id":"sia_09","i":9,"title":"Kette des Verrats","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Lieber Donovan, ich hätte ein Gesuch, wenn du so nett wärst."},{"a":"donovan","t":"Oh? Lass mal hören."},{"a":"sia","t":"Geh zum Imperator. Sag ihm, Agentin Schwan ist tot. Ein ehrenwerter, tragischer Tod, während sie pflichtbewusst dem Imperium diente."},{"a":"donovan","t":"W-Wie bitte?"},{"a":"sia","t":"Ich kündige, Donovan. Wechsle sozusagen die Seiten."},{"a":"sia","t":"Und du wirst die Nachricht überbringen. Und meine Geschichte unterstützen, natürlich."},{"a":"donovan","t":"F-Frechheit! Das ist Hochverrat! Ich würde niemals ..."},{"a":"sia","t":"Ich denke schon, Donovan. Außer natürlich du willst, dass die Welt das Rezept für dein Unsterblichkeitselixier erfährt?"},{"a":"donovan","t":"Ah, bluffst du, Sia? Ich habe nie jemandem von diesem Rezept erzählt. Du kannst unmöglich ..."},{"a":"sia","t":"Wie ging es noch mal? Flügel einer hundert Jahre alten Eintagsfliege ... Wasser aus dem Styx ...?"},{"a":"donovan","t":"D-Das ist ..."},{"a":"sia","t":"Es gab so viele Zutaten ... war nicht auch ein Schuss Wein vorgesehen, für den Geschmack?"},{"a":"donovan","t":"Sch-schweig! SCHWEIG! Ich weiß nicht, durch welche dunklen Kräfte du davon erfahren hast ..."},{"a":"sia","t":"Du unterschätzt wohl mein Spionagenetzwerk."},{"a":"donovan","t":"... Aber ich werde dein kleines Spielchen mitspielen. Dieses Mal."},{"a":"sia","t":"Wie immer ein schlechter Verlierer, was? Ich halte meine Bedingungen für überaus großzügig."},{"a":"sia","t":"Was ist schon ein kleiner Verrat im Gegenzug für dein Lebenswerk?"}]},{"id":"sia_10","i":10,"title":"Unterstützung nach dem Tod","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Agent Flüster. Ich bin es."},{"a":"essence","t":"*Gääähn* ... jetzt schon?"},{"a":"sia","t":"Deine Informationen waren korrekt. Ich danke dir für deine ausgezeichnete Arbeit."},{"a":"essence","t":"Nicht der Rede wert ..."},{"a":"sia","t":"Donovan war schon immer sehr vorsichtig, aber einem Geist kann wohl kaum die Sicht versperren!"},{"a":"essence","t":"Ganz recht ..."},{"a":"essence","t":"Er sah ... richtig wütend aus ..."},{"a":"sia","t":"Wie vereinbart bekommst du deine Bezahlung als Opfergabe für dein Grab."},{"a":"sia","t":"Ich habe auch noch ein kleines Extra dazugegeben. Bitte zieh los und quäle Donovan noch etwas länger."},{"a":"essence","t":"Ich werde bezahlt ... um Geist zu spielen. Das ist großartig."}]},{"id":"sia_11","i":11,"title":"Ein befreiter Schwan","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"king","t":"Sia! Ich kann kaum noch an mich halten! Wie lange muss ich noch warten, bis ich die Welt mit meinen Launen beglücken kann?!"},{"a":"sia","t":"Es waren doch bisher nur ein paar Tage, Majestät. Etwas mehr Geduld, bitte."},{"a":"king","t":"Ah! Was hat es denn mit dem ganzen Papierkram auf sich?"},{"a":"sia","t":"Geburtsurkunden und andere wichtige Verwaltungsdokumente, die mich betreffen."},{"a":"sia","t":"Offenbar sind die meisten Dokumente, die mein Leben in diesem Königreich dokumentieren, rein zufällig abhandengekommen."},{"a":"sia","t":"Daher fülle ich diese Formulare pflichtbewusst aus dem Gedächtnis aus."},{"a":"king","t":"Natürlich! Es würde sich ja nicht geziemen, wenn meine beste Beraterin keine offizielle Untertanin meines Königreichs wäre!"},{"a":"king","t":"Hier! Ich werde sie umgehend mit meinem königlichen Siegel versehen!"},{"a":"king","t":"Und fertig! Wie immer entgeht nichts deinem scharfen Blick!"},{"a":"sia","t":"Vielen Dank, Hoheit. Ich hoffe, dass ich noch viele Jahrzehnte lang dienen kann."},{"a":"king","t":"Darauf zähle ich!"},{"a":"king","t":"Sia, erspähe ich da eine Träne? Bereitet dir das Ausfüllen von Formularen wirklich so viel Freude?"},{"a":"sia","t":"Oh ... nein. Ich würde vielmehr sagen, dass diese Dokumente so langweilig sind, dass sie mir die Tränen in die Augen treiben."},{"a":"sia","t":"Nun denn! Wollen wir uns den Launen widmen?"},{"a":"king","t":"Jawohl! Also wenn du mich fragst, ist die aktuelle Schildsituation ..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Großer Krieger Sokka","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"atlab_aang","t":"Und wie wäre es ... damit!"},{"a":"tavern","t":"Oh, das ist ein süßer Trick!"},{"a":"atlab_sokka","t":"Uh. Er macht das ständig!"},{"a":"argon","t":"Hallo, Sokka, stimmt’s? Ich bin Argon!"},{"a":"atlab_sokka","t":"Oh, hallo. Wenn du Bändigertricks sehen willst, bist du bei Aang an der richtigen Adresse."},{"a":"argon","t":"Oh nein. Ich weiß nicht viel über Magie. Oder das Bändigen."},{"a":"argon","t":"Deiner Ausrüstung nach zu urteilen bist du ein furchterregender Krieger."},{"a":"atlab_sokka","t":"F-Furchterregender Krieger?"},{"a":"atlab_sokka","t":"T-Tja, du hast recht! Ich bin Sokka, der große Krieger von Team Avatar!"},{"a":"argon","t":"Ich wusste es! Du hast bestimmt ein paar unglaubliche Geschichten auf Lager!"},{"a":"atlab_sokka","t":"Darauf kannst du wetten! Zum Beispiel während der Belagerung von Agna Qel’a ..."},{"a":"atlab_sokka","t":"Und so wurde meine damalige Freundin zum Mond."},{"a":"argon","t":"Z-Zum Mond?!"},{"a":"atlab_sokka","t":"Ja. Aber dann, als die Flotte der Feuernation ..."},{"a":"atlab_sokka","t":"... und zack! Da hab ich den riesigen Eulentypen in der Bibliothek bewusstlos geschlagen."},{"a":"argon","t":"Wow! War diese Eule nicht ein mächtiger Geist?"},{"a":"atlab_sokka","t":"Stimmt! Aber wenn Sokka da ist, gewinnt Team Avatar immer!"},{"a":"atlab_sokka","t":"... Apropos: Wo ist Aang?"},{"a":"argon","t":"Oh, er ist vor circa einer Stunde gegangen."},{"a":"atlab_sokka","t":"Verflixt, ich habe die Zeit aus den Augen verloren. Tut mir leid, Argon, ich muss los!"}]},{"id":"atlab_sokka_02","i":2,"title":"Großer Schmied Sokka","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"blacksmith","t":"Fleißig bei der Arbeit, Sokka?"},{"a":"atlab_sokka","t":"Hey Wallace. Danke, dass ich dein Werkzeug benutzen darf!"},{"a":"blacksmith","t":"Kein Problem! Ich hätte nicht erwartet, dass du in deinem Alter schon so ein geschickter Handwerker bist!"},{"a":"atlab_sokka","t":"Wenn man als Einziger in der Gruppe kein Bändiger ist, muss man sich alle möglichen Fähigkeiten aneignen."},{"a":"atlab_sokka","t":"Ich kann nicht jeden Tag so tolle Werkzeuge verwenden ..."},{"a":"atlab_sokka","t":"Die Arbeit ist im Nu getan!"},{"a":"blacksmith","t":"Das Schwert, das du da wetzt ... Wo hast du das her?"},{"a":"atlab_sokka","t":"Das ist mein Meteoritenschwert! Ich habe es selbst geschmiedet!"},{"a":"blacksmith","t":"Sternenmetall? Gar nicht schlecht, Kleiner!"},{"a":"blacksmith","t":"Es ist bestimmt ... nicht von dieser Welt!"},{"a":"atlab_sokka","t":"Stimmt! Kein Schwert ist vergleichbar!"},{"a":"polonia","t":"Ahoi! Entschuldigt die Störung, aber würde mir einer von euch netten Kerlen helfen, mein Schiff zu reparieren?"},{"a":"polonia","t":"Sie ist heute ganz schön schlecht drauf. Hat sich an ein paar seltsamen Eisenkugeln gestoßen und ist auf Strand gelaufen ..."},{"a":"blacksmith","t":"Also die volle Ladung Ärger!"},{"a":"atlab_sokka","t":"Hey, kein Problem, ich bin vom Wasserstamm! Ich werde mal sehen, was sich machen lässt. Tut mir leid, Wallace, ich muss los!"},{"a":"blacksmith","t":"Ich repariere in der Zwischenzeit deine restliche Ausrüstung. Viel Glück!"}]},{"id":"atlab_sokka_03","i":3,"title":"Großer Seefahrer Sokka","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"atlab_sokka","t":"So, damit solltest du wenigstens sicher in den Hafen kommen."},{"a":"polonia","t":"Das ist eine anständige Reparatur! Alles fest!"},{"a":"atlab_sokka","t":"... Dein Steuer wird mit Treibholz und Fetzen von meinem Hemd zusammengehalten."},{"a":"atlab_sokka","t":"Ich würde es nicht als fest bezeichnen. Eher als Sokka-Reparatur."},{"a":"polonia","t":"Joho! Wie kommt es denn, dass eine Landratte wie du Schiffe repariert?"},{"a":"atlab_sokka","t":"Im Wasserstamm dreht sich alles um Boote und das Fischen. Ich bin schon gesegelt, da konnte ich noch nicht mal gehen."},{"a":"atlab_sokka","t":"Erst vor Kurzem habe ich ein U-Boot erfunden, das mit Wasserbändigen betrieben werden kann!"},{"a":"polonia","t":"Ich versteh deine Landrattensprache nicht. Was soll das bedeuten?"},{"a":"atlab_sokka","t":"Es ist ... äh, ein Schiff aus Metall, das unter Wasser fährt."},{"a":"polonia","t":"Für mich klingt das, als wolltest du Seebären in einer hübschen Kiste auf den Meeresgrund schicken."},{"a":"engineer","t":"Habe ich gerade „höchstgefährlicher, ungetesteter Prototyp“ gehört?"},{"a":"atlab_sokka","t":"Äh ... Nicht ganz."},{"a":"engineer","t":"Mir gefällt dein Stil. Komm mal mit, Neuer."},{"a":"polonia","t":"Joho, zurück aufs Meer! Lichtet die Anker, bevor die Kopfgeldjäger hier sind!"},{"a":"polonia","t":"Arr, diesmal sollten wir den schwimmenden Eisenkugeln lieber ausweichen."}]},{"id":"atlab_sokka_04","i":4,"title":"Großer Erfinder Sokka","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"engineer","t":"Faszinierend! Ich will ehrlich sein, dein Entwurf ist ein wenig schlampig ..."},{"a":"engineer","t":"Aber mit ein wenig Muskelschmalz sollte dein U-Boot funktionieren!"},{"a":"atlab_sokka","t":"Genial, oder? Ich habe es gewusst!"},{"a":"atlab_sokka","t":"Aber bedenke, dass es dafür entwickelt wurde, von Wasserbändigern betrieben zu werden."},{"a":"engineer","t":"Details! Wir lassen uns schon etwas einfallen."},{"a":"engineer","t":"Denk nur mal nach! Damit könnten wir den Versunkenen Tempel erkunden!"},{"a":"atlab_sokka","t":"Oh, und es fasst nicht viel Luft, also solltet ihr die Reisen kurz halten."},{"a":"atlab_sokka","t":"... Hast du mir zugehört?"},{"a":"engineer","t":"Lehn dich nicht auf diese große Eisenkugel."},{"a":"atlab_sokka","t":"... Hä? Boah! Warum nicht?"},{"a":"engineer","t":"Mein Seeminen-Prototyp. Nicht anfassen. Sehr explodierend."},{"a":"atlab_sokka","t":"... Oh."},{"a":"atlab_sokka","t":"Aber egal, gib Bescheid, wie sich der Prototyp entwickelt."},{"a":"atlab_sokka","t":"Wenn er funktioniert ... haben wir dafür in Zukunft Verwendung."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Hey du. Ich glaube, ich habe genug vom Champion-Sein."},{"a":"leather","t":"Da hat man viel mehr Verantwortung, als ich dachte. Ich habe doch jetzt schon kaum genug Zeit für mein Leder!"},{"a":"leather","t":"Vielleicht probiere ich es nächstes Jahr wieder aus, Kumpel. Wir sehen uns in der Stadt!"}]},{"id":"leather_01","i":1,"title":"Lederindustrie","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"leather","t":"Danke für die Hilfe, Kumpel."},{"a":"argon","t":"Kein Problem, Tamas! Das ist ganz schön viel Leder!"},{"a":"leather","t":"Ich habe heute eine große Ausbeute gemacht. Aber pass auf, wo du hintrittst."},{"a":"argon","t":"Ja ... Es ist ziemlich holprig hier ... Boah!"},{"a":"leather","t":"Boah! Au!"},{"a":"argon","t":"Entschuldigung, Tamas! Bist du in Ordnung?"},{"a":"leather","t":"Ich habe mir den Kopf ein wenig gestoßen. Ich glaube, es ist alles gut."},{"a":"leather","t":"Aber ich hatte gerade einen Geistesblitz, Kumpel."},{"a":"leather","t":"Ich muss los. Das ist was Großes."},{"a":"argon","t":"Uh, klar! Schön, dass ich helfen konnte!"},{"a":"argon","t":"Aber was mache ich jetzt mit dem ganzen verstreuten Leder?"}]},{"id":"leather_02","i":2,"title":"Von der Prophezeiung vorausgesagt","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"leather","t":"... und so habe ich mir den Kopf gestoßen, Kumpel. Hier habe ich eine kleine Beule."},{"a":"mana","t":"Diese Person hier hört zu, aber helfen kann sie nicht."},{"a":"mana","t":"Der Äther prophezeit und enthüllt, aber heilen kann er nicht."},{"a":"leather","t":"Aber es ist trotzdem Magie, oder? Komm schon, Kumpel, leg einfach deine magischen Hände drauf."},{"a":"mana","t":"Es gibt keine ..."},{"a":"mana","t":"...!!!"},{"a":"mana","t":"Dieses ... Schicksal ...! Überwältigend ...!"},{"a":"leather","t":"Bist du sicher, dass das funktioniert hat, Kumpel? Mir ist immer noch ein wenig schwindelig."},{"a":"mana","t":"Entschuldige. Eine neue Vision hat sich offenbart und erfordert Meditation."},{"a":"mana","t":"Suche die von der Göttin Gesegnete auf für deine ... Wunden. Diese Person hier muss sofort aufbrechen."},{"a":"leather","t":"Alles klar. Das wird schon wieder, ich fühle mich in letzter Zeit ziemlich stark."}]},{"id":"leather_03","i":3,"title":"Das Championtreffen","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"argon","t":"Es gibt also einen neuen, äh, Champion in der Stadt."},{"a":"polonia","t":"Joho! Ich hoffe, er hat was drauf!"},{"a":"leather","t":"Hey Leute."},{"a":"polonia","t":"Potzblitz! Ist das dein Ernst?"},{"a":"lilu","t":"Tamas?! Wann hast du ..."},{"a":"leather","t":"Ich dachte mir, ich probier das Champion-Dasein mal aus, Kumpel. Sieht nicht allzu schwierig aus."},{"a":"argon","t":"Ähm ... Tamas, erzähl uns doch mal, was du tust."},{"a":"leather","t":"Ich verprügle Monster, Kumpel. Außerdem kann ich Ledergegenstände meilenweit erschnuppern."},{"a":"polonia","t":"Ey! Dinge zu stehlen ist MEINE Aufgabe! Such dir eine eigene!"},{"a":"leather","t":"Das hat nichts mit Stehlen zu tun, Kumpel. Die Leute lassen sie einfach überall herumliegen."},{"a":"lilu","t":"Die Dinge versprechen, interessant zu werden!"},{"a":"polonia","t":"Arr, du könntest recht haben ..."}]},{"id":"leather_04","i":4,"title":"Unbesungener Held","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Glücksmarken"},"side":false,"lines":[{"a":"sia","t":"Mein König, ich habe etwas höchst Ungewöhnliches zu berichten."},{"a":"king","t":"Ich bin ganz Ohr, wie immer! Sprich!"},{"a":"sia","t":"Helden und Karawanen berichten, dass die Straßen sicherer sind denn je."},{"a":"sia","t":"Monster sind kaum zu sehen und scheinen sogar Angst davor zu haben, jemanden anzugreifen."},{"a":"king","t":"Großartige Neuigkeiten!"},{"a":"sia","t":"Aber wir können uns dieses seltsame Verhalten einfach nicht erklären."},{"a":"sia","t":"Ebenso merkwürdig ist der plötzliche Einbruch des Markts für Lederwaren ..."},{"a":"king","t":"Sicher nur ein Zufall! Lass uns schmausen und diese guten Nachrichten feiern!"},{"a":"sia","t":"Vielleicht, mein König ... vielleicht."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"Wanderin aus Azuma","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Hehehe! Was haben wir denn hier?"},{"a":"yami","t":"Hmpf. Schwirr ab, Plagegeist."},{"a":"monster_forest_Boss","t":"Du hast aber schlechte Manieren, Lady! Und komische Klamotten!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Aha! Du riechst nach Azuma, dem Königreich der Menschen im Osten!"},{"a":"monster_forest_Boss","t":"Was treibst du denn so weit von Zuhause, Lady?"},{"a":"monster_forest_Boss","t":"Bis an die Zähne bewaffnet und verschwiegen ... Du bist doch sicher eine Assassinin, oder?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Hehe! Wusste ich’s doch! Blöde Menschen, töten sich dauernd gegenseitig!"},{"a":"yami","t":"Du hast recht. Ich bin hier, um einen tyrannischen König zu töten."},{"a":"monster_forest_Boss","t":"Pah! Wenn du das jedem auf die Nase bindest, kannst du keine besonders gute Assassinin sein. Warum hast du mir das verraten?"},{"a":"yami","t":"Weil du es niemandem weitererzählen können wirst. Und tschüss."},{"a":"monster_forest_Boss","t":"Aah!"},{"a":"yami","t":"Du bist der Nächste, König Reinhold."}]},{"id":"yami_02","i":2,"title":"Jäger oder Gejagter","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"yami","t":"Das Schloss ist gut gesichert."},{"a":"yami","t":"Ein Passwortsystem, das sich täglich ändert ..."},{"a":"yami","t":"Unvorhersehbare Wachpatrouillen ..."},{"a":"yami","t":"Ich muss äußerst ..."},{"a":"argon","t":"He da! Du, im Gebüsch!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Bist du auch hier, um ein Ritter zu werden?"},{"a":"argon","t":"Sia wird gleich hier sein! Kein Grund, sich zu verstecken. Sie ist echt nett!"},{"a":"yami","t":"Sia ...!"},{"a":"yami","t":"Ich muss los. Leb wohl."},{"a":"argon","t":"W-Warte!"},{"a":"argon","t":"Wow! Rauchbombe?!"},{"a":"yami","t":"Den Schwachkopf habe ich abgeschüttelt."},{"a":"yami","t":"Wenn Sia hier ist ... erschwert das meine Aufgabe."},{"a":"yami","t":"Aber es muss getan werden. Ich darf nicht scheitern."},{"a":"yami","t":"Für den Orden ... und für meine Schwester."}]},{"id":"yami_03","i":3,"title":"Wendepunkt","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"king","t":"Geschätztes Volk meines Königreichs! Danke, dass ihr zu meinem prächtigen Fest gekommen seid!"},{"a":"king","t":"Es ist auch die perfekte Gelegenheit für euch, meine wunderschöne Erscheinung zu bewundern! Lasst euch diese Chance nicht entgehen!"},{"a":"yami","t":"(Aufgeblasener Tyrann. Typisch.)"},{"a":"sia","t":"Ähm, ja. Danke für diese erbauliche Rede, Eure Majestät."},{"a":"sia","t":"Wir haben uns heute hier versammelt, um die unglaubliche Großzügigkeit des Königs zu feiern."},{"a":"sia","t":"In den vergangenen Monaten hat er Gold im Wert mehrerer Millionen aus seiner eigenen Kasse ..."},{"a":"sia","t":"... an verschiedene örtliche Tempel, Schulen und Waisenhäuser gespendet."},{"a":"sia","t":"Alle sind zu diesem Fest eingeladen, also bitte erzählt es euren Freunden und eurer Familie."},{"a":"sia","t":"Lang lebe König Reinhold!"},{"a":"yami","t":"(... Das sind nicht die Taten eines Tyrannen.)"},{"a":"yami","t":"(... Nein, der Orden würde nicht lügen. Das muss ein Trick sein.)"},{"a":"yami","t":"Reinhold, du Tyrann, deine Herrschaft endet jetzt!"},{"a":"sia","t":"Ein Shuriken ...! Die Assassinin aus Azuma!"},{"a":"yami","t":"Ich habe ihn verfehlt ...?! Unmöglich!"},{"a":"sia","t":"Wachen! Sperrt alle Ausgänge ab! Fasst diese Frau, sofort!"}]},{"id":"yami_04","i":4,"title":"Reflexion","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"yami","t":"(Ich habe gezögert ... und versagt.)"},{"a":"yami","t":"(Könnte der Orden gelogen haben ...?)"},{"a":"yami","t":"(Das tut nichts zur Sache. Ich bin jetzt auf mich allein gestellt.)"},{"a":"argon","t":"Endlich habe ich dich gefunden!"},{"a":"yami","t":"Der törichte Ritter!"},{"a":"argon","t":"Woah, ich bin nicht hier, um zu kämpfen!"},{"a":"yami","t":"Ich falle nicht auf deine Tricks herein, du Handlanger Reinholds!"},{"a":"argon","t":"... Du hast absichtlich nicht getroffen, stimmt’s?"},{"a":"yami","t":"...!"},{"a":"argon","t":"Ich habe dich beim Fest gesehen. Es hat sogar so ausgesehen, als hättest du es bereut, den Shuriken geworfen zu haben."},{"a":"argon","t":"Der König ist kein schlechter Mensch, weißt du? Manchmal ist er etwas eigenartig, aber er gibt sein Bestes!"},{"a":"argon","t":"Ich weiß nicht, wer dich dafür bezahlt hat, das zu tun, aber das können keine guten Menschen sein ..."},{"a":"argon","t":"Wie wäre es, wenn du zum Schloss zurückkehrst und dich entschuldigst? Ich bin sicher, Reinhold würde ..."},{"a":"yami","t":"... Mich entschuldigen? Wie blöd."},{"a":"yami","t":"Ich muss jetzt viel nachdenken. Du solltest mir nicht folgen, wenn dir dein Leben lieb ist."},{"a":"argon","t":"... Sie ist kein schlechter Mensch, da bin ich mir sicher."},{"a":"argon","t":"Jetzt muss ich Sia Bericht erstatten ..."},{"a":"argon","t":"Oh Mann, das gibt Ärger ..."}]},{"id":"yami_05","i":5,"title":"Im Mondlicht","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Sonnenlicht in hohen Weiden, ein Leuchten vergangener Zeit<sprite tint=1 name=Note2> ..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Auf der Elfenwiese werden wir – iih!"},{"a":"yami","t":"Der kalte Stich, den du spürst, ist meine Klinge an deinem Hals."},{"a":"yami","t":"Ich habe Fragen. Wenn du ehrlich antwortest, lasse ich dich vielleicht am Leben."},{"a":"fabric","t":"Aaah! J-Ja! Egal was! Au!"},{"a":"yami","t":"Sei still."},{"a":"yami","t":"Dieser Narr, den ihr König nennt ... Erzähl mir von ihm."},{"a":"fabric","t":"K-König Reinhold? Er ist der Herrscher über diese Lande ..."},{"a":"fabric","t":"Obwohl er ziemlich exzentrisch ist, sind seine Tugend und seine Großzügigkeit nicht zu leugnen."},{"a":"fabric","t":"Was ihm an Erfahrung fehlt, macht seine neueste Beraterin Sia locker wett!"},{"a":"yami","t":"Unmöglich! Deine Worte stinken nach Feigheit, aber sie klingen wahr."},{"a":"yami","t":"Diese Stadt! Beherbergt sie ein Orakel?"},{"a":"fabric","t":"Ah! Ja! Die Elfe, Serene, auf dem Hügel!"},{"a":"fabric","t":"Geheimnisvolle Fremde ... Würdest du mir die Ehre erweisen, deinen Namen ... Au!"},{"a":"yami","t":"Vor ein paar Tagen hätte ich nicht lange darüber nachgedacht, dich zu töten. Fordere dein Glück nicht heraus."},{"a":"yami","t":"Kehre zu deinem faden Leben zurück und vergiss alles, was hier geschehen ist."},{"a":"fabric","t":"Puh! Was für ein aufregendes Treffen!"},{"a":"fabric","t":"Schwarz gekleidete Dame ... Ich frage mich, werden wir uns je wiedersehen?"}]},{"id":"yami_06","i":6,"title":"Kaputter Bauer","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"mana","t":"Ein schwarzer Wind verrät die Anwesenheit der Pirschjägerin."},{"a":"yami","t":"...! Wie ...?"},{"a":"mana","t":"Die Pirschende schreitet wie eine Feder, aber ihr schweres Herz wird dem dritten Auge offenbart."},{"a":"yami","t":"... Genug der Scharaden, Orakel. Ich brauche Antworten."},{"a":"yami","t":"Über den Orden ... Meine Familie."},{"a":"mana","t":"Eine Verbreiterin des Todes sucht Rat. Was bietet sie im Gegenzug an?"},{"a":"yami","t":"Dein Leben."},{"a":"mana","t":"... So soll es sein."},{"a":"mana","t":"<c1>Die Aufgabe des Ordens in Azuma war es einst, Unrecht zu bekämpfen ...</c1>"},{"a":"mana","t":"<c1>... Die Champions der Gerechtigkeit wurden zu Sklaven für den Höchstbietenden ...</c1>"},{"a":"mana","t":"<c1>... Für eine unüberwindbare Aufgabe wird ein Bauer geopfert ...</c1>"},{"a":"mana","t":"<c1>... Egal ob Scheitern oder Erfolg, der Orden wird siegreich sein.</c1>"},{"a":"yami","t":"Unmöglich."},{"a":"mana","t":"Die Botin hat gesprochen."},{"a":"yami","t":"UNMÖGLICH!"},{"a":"mana","t":"..."},{"a":"mana","t":"Wer in den Schatten umherzieht, muss sich auch mit dem Licht gutstellen, wenn die Zeit gekommen ist."}]},{"id":"yami_07","i":7,"title":"Kaputter Bauer","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"yami","t":"Ich muss meine Sachen packen und so schnell wie möglich verschwinden."},{"a":"inn","t":"Hallo, geheimnisvolle Fremde."},{"a":"yami","t":"Wirt. Ich habe dich doch für dein Schweigen bezahlt."},{"a":"inn","t":"Keine Sorge, wir hier im Gasthaus „Zum Smaragd“ sind nicht neugierig!"},{"a":"inn","t":"Aber wir haben ein paar fies aussehende Gäste, die wohl auf der Suche nach dir sind."},{"a":"yami","t":"(Vollstrecker aus dem Orden? So schnell?)"},{"a":"inn","t":"Sie haben mir keine Namen genannt. Ganz schön zwielichtige Gestalten. Freunde von dir?"},{"a":"yami","t":"Nicht mehr. Sag ihnen, dass ich tot bin. Für sie bin ich das sowieso."},{"a":"inn","t":"Du hast es eilig, was? Das habe ich mir schon gedacht. Ich habe ein paar Vorräte für dich vorbereitet."},{"a":"yami","t":"Danke, Wirt. Aber dort, wo ich hingehe, brauche ich sie nicht."}]},{"id":"yami_08","i":8,"title":"Reise ohne Rückkehr","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Zum Düsterturmgipfel, sagst du?"},{"a":"wood","t":"Ja, ich habe ein Mädchen gesehen, das wie ein Ninja aussah und auf deine Beschreibung passt. Sie schien es eilig zu haben."},{"a":"sia","t":"Ausgezeichnet. Wir haben unsere Meuchelmörderin endlich aufgespürt."},{"a":"sia","t":"Ich werde eine Patrouille zusammenstellen und ..."},{"a":"wood","t":"Bist du dir sicher? Ich denke nicht, dass das notwendig sein wird."},{"a":"sia","t":"Und warum nicht, Gorza?"},{"a":"wood","t":"Eine Expedition zum Düsterturmgipfel auf eigene Faust kommt einem Selbstmord gleich. Das Mädchen hat nicht mal Vorräte mitgenommen."},{"a":"wood","t":"Sie muss das wissen. Nicht mal Rudo ist dumm genug, dort allein hinzugehen."},{"a":"sia","t":"Ist das so? Danke, Gorza, ich werde das bedenken."},{"a":"sia","t":"Ich vermute, dieses Problem wird sich von allein lösen, aber ..."},{"a":"sia","t":"... ein bisschen unwohl ist mir dabei schon. Was hast du vor, Meuchelmörderin?"}]},{"id":"yami_09","i":9,"title":"Treffen auf dem Düsterturm (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"argon","t":"Das muss Schicksal sein. Eine noch höhere Prämie als die für eine Harpyie!"},{"a":"yami","t":"Na komm schon. Dich mache ich im Handumdrehen fertig."},{"a":"argon","t":"Das sagst du, aber besonders überzeugt klingst du nicht ..."},{"a":"yami","t":"Du hast recht. Mir ist gerade alles egal."},{"a":"yami","t":"Wenn du mich wirklich tot sehen willst, lass mich hier sterben."},{"a":"argon","t":"Ich würde nie jemanden dem Tod überlassen! Ich werde dich zu König Reinhold bringen!"},{"a":"argon","t":"Ich weiß, dass er es verstehen wird! Wenn ich muss, trage ich dich auch zurück!"},{"a":"yami","t":"..."},{"a":"argon","t":"Komm schon, los!"},{"a":"argon","t":"Warte, du bist ja nur Haut und Knochen! Wann hast du zum letzten Mal etwas gegessen?"},{"a":"yami","t":"..."},{"a":"argon","t":"Iss ein wenig was auf dem Rückweg. Das wird holprig!"}]},{"id":"yami_10","i":10,"title":"Hinter feindlichen Linien","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Wachen! Holt Verstärkung und lasst sie keine Sekunde lang aus den Augen!"},{"a":"sia","t":"Argon, bitte warte draußen, während wir mit dieser ... Invasorin sprechen."},{"a":"argon","t":"Jawohl!"},{"a":"sia","t":"Also gut. Sprich, Meuchelmörderin."},{"a":"yami","t":"Hmpf, stimmt schon. Ich wurde bezahlt, um einen Tyrannen zu ermorden."},{"a":"yami","t":"Zumindest dachte ich das. Es hat sich aber herausgestellt, dass er nur ein wohlmeinender Tölpel ist."},{"a":"king","t":"T-Tölpel?!"},{"a":"sia","t":"Was haben deine Leute gegen unseren König?"},{"a":"yami","t":"Mein Orden dient nur der Gerechtigkeit ..."},{"a":"yami","t":"Aber das war wohl die ganze Zeit über nur eine Lüge. Und nach meinem Versagen werden sie mich auch jagen."},{"a":"yami","t":"Es ... tut mir leid. Ich werde mich meiner gerechten ... Strafe stellen ..."},{"a":"yami","t":"Uff."},{"a":"king","t":"Sie ist zusammengebrochen!"},{"a":"sia","t":"Erschöpft und fast verhungert ..."},{"a":"sia","t":"Wachen! Ruft unsere besten Ärzte für sie!"},{"a":"sia","t":"Behandelt sie mit Respekt, wie es einem Gast des Königs gebührt."}]},{"id":"yami_epilogue","i":11,"title":"Epilog","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Juwelen"},"side":false,"lines":[{"a":"sia","t":"Pff ... Pff ... Zu dir zu kommen ... erfordert ganz schöne Kletterkünste ..."},{"a":"yami","t":"Das ist jetzt mein Zuhause."},{"a":"sia","t":"Warum ziehst du nicht in die Stadt? Du wurdest ja begnadigt."},{"a":"yami","t":"Mein Orden hält mich höchstwahrscheinlich für tot. Mir wäre es recht, wenn das so bleibt."},{"a":"sia","t":"Ich verstehe. Ich werde dafür sorgen, dass du regelmäßig versorgt wirst."},{"a":"sia","t":"Also gut, zu deiner nächsten Aufgabe ..."},{"a":"yami","t":"Mehr Schlägertypen aus dem Imperium?"},{"a":"sia","t":"Genau. Wie du weißt, zieht seine Majestät viel Zorn seiner Neider auf sich."},{"a":"sia","t":"Dieses Dokument gibt dir nähere Informationen zu deinen Zielen."},{"a":"yami","t":"Ich kümmere mich darum."},{"a":"sia","t":"Ich sage das höchst ungern, aber ich glaube dir."},{"a":"sia","t":"Ich sollte jetzt wieder zurückgehen. Obwohl ich mich nicht auf die Wanderung freue ..."},{"a":"yami","t":"Sia ... Reinhold ..."},{"a":"yami","t":"Ich danke euch. Von ganzem Herzen."}]}]}];
